export const SETUP_SQL = "-- Amryn™ AIGrowthIntelligence® — complete database setup\n--\n-- Generated by scripts/build-setup-sql.mjs from supabase/migrations.\n-- Do not edit this file; edit the migrations and regenerate.\n--\n-- Paste the whole thing into the Supabase SQL editor and run it once.\n-- It is wrapped in a single transaction: if any statement fails, nothing is\n-- applied and the error names where it stopped. A half-applied schema is the\n-- one outcome this exists to prevent.\n--\n-- Safe on an empty database. NOT safe to run twice — the second run fails on\n-- the first `create table`, having changed nothing.\n\nbegin;\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090000_01_foundation.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090000_01_foundation.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 01 — Foundation: tenancy, identity, org structure, RBAC\n--\n-- Tenancy model\n-- -------------\n-- Every business table carries organisation_id and is protected by Row Level\n-- Security. A member's reach inside their organisation is further narrowed by\n-- a *scope*: org-wide, a set of regions, a set of branches, or a set of\n-- departments. Scope is resolved in SQL (not in the app) so that a bug in the\n-- application layer cannot widen what a user can read.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate extension if not exists \"pgcrypto\";\ncreate extension if not exists \"citext\";\n\ncreate schema if not exists amryn;\ncomment on schema amryn is 'Amryn internal helper functions. Not exposed through PostgREST.';\n\nrevoke all on schema amryn from public, anon, authenticated;\ngrant usage on schema amryn to authenticated, service_role;\n\n-- ── enums ─────────────────────────────────────────────────────────────────\n\ncreate type public.org_role as enum (\n  'super_admin',\n  'org_admin',\n  'executive',\n  'regional_manager',\n  'branch_manager',\n  'department_manager',\n  'analyst',\n  'viewer'\n);\n\ncreate type public.scope_kind as enum ('organisation', 'region', 'branch', 'department');\n\ncreate type public.member_status as enum ('invited', 'active', 'suspended');\n\ncreate type public.priority_level as enum ('critical', 'high', 'medium', 'low');\n\ncreate type public.trend_direction as enum ('up', 'down', 'flat');\n\ncreate type public.subscription_plan as enum ('starter', 'growth', 'professional', 'enterprise');\n\ncreate type public.subscription_status as enum ('trialing', 'active', 'past_due', 'cancelled');\n\n-- ── organisations ─────────────────────────────────────────────────────────\n\ncreate table public.organisations (\n  id                uuid primary key default gen_random_uuid(),\n  name              text not null check (length(btrim(name)) between 2 and 160),\n  slug              citext not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,62}$'),\n  industry          text,\n  country_code      char(2) not null default 'ZA',\n  currency_code     char(3) not null default 'ZAR',\n  timezone          text not null default 'Africa/Johannesburg',\n  fiscal_year_start smallint not null default 1 check (fiscal_year_start between 1 and 12),\n  -- Strategy profile the OpportunityRadar® scores relevance against.\n  strategy_profile  jsonb not null default '{}'::jsonb,\n  settings          jsonb not null default '{}'::jsonb,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now(),\n  deleted_at        timestamptz\n);\n\ncomment on column public.organisations.strategy_profile is\n  'Declared markets, segments, capabilities and growth intents. Feeds opportunity relevance and strategic-alignment scoring.';\n\n-- ── user profiles (mirrors auth.users) ────────────────────────────────────\n\ncreate table public.user_profiles (\n  id           uuid primary key references auth.users (id) on delete cascade,\n  email        citext not null,\n  full_name    text,\n  job_title    text,\n  avatar_url   text,\n  locale       text not null default 'en-ZA',\n  theme        text not null default 'system' check (theme in ('light', 'medium', 'dark', 'system')),\n  last_seen_at timestamptz,\n  created_at   timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\n-- ── organisational structure ──────────────────────────────────────────────\n\ncreate table public.regions (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  name            text not null,\n  code            text,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz,\n  unique (organisation_id, name)\n);\n\ncreate table public.branches (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  region_id       uuid references public.regions (id) on delete set null,\n  name            text not null,\n  code            text,\n  city            text,\n  opened_on       date,\n  headcount       integer check (headcount >= 0),\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz,\n  unique (organisation_id, name)\n);\n\ncreate table public.departments (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  name            text not null,\n  function        text,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz,\n  unique (organisation_id, branch_id, name)\n);\n\n-- A branch's region, and a department's branch, must belong to the same\n-- organisation as the row itself. Two small functions rather than one with a\n-- dispatch argument: PL/pgSQL resolves NEW's fields when the expression is\n-- planned, so a shared body would reference columns the other table lacks.\n\ncreate or replace function amryn.assert_branch_region_same_org()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  parent_org uuid;\nbegin\n  if new.region_id is not null then\n    select organisation_id into parent_org from public.regions where id = new.region_id;\n    if parent_org is distinct from new.organisation_id then\n      raise exception 'region % belongs to a different organisation', new.region_id;\n    end if;\n  end if;\n  return new;\nend;\n$$;\n\ncreate or replace function amryn.assert_department_branch_same_org()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  parent_org uuid;\nbegin\n  if new.branch_id is not null then\n    select organisation_id into parent_org from public.branches where id = new.branch_id;\n    if parent_org is distinct from new.organisation_id then\n      raise exception 'branch % belongs to a different organisation', new.branch_id;\n    end if;\n  end if;\n  return new;\nend;\n$$;\n\ncreate trigger branches_same_org\n  before insert or update on public.branches\n  for each row execute function amryn.assert_branch_region_same_org();\n\ncreate trigger departments_same_org\n  before insert or update on public.departments\n  for each row execute function amryn.assert_department_branch_same_org();\n\n-- ── membership ────────────────────────────────────────────────────────────\n\ncreate table public.organisation_members (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  user_id         uuid not null references auth.users (id) on delete cascade,\n  role            public.org_role not null default 'viewer',\n  status          public.member_status not null default 'active',\n  scope_kind      public.scope_kind not null default 'organisation',\n  -- Ids of the regions / branches / departments this member may see. Empty for\n  -- scope_kind = 'organisation'.\n  scope_ids       uuid[] not null default '{}',\n  invited_by      uuid references auth.users (id) on delete set null,\n  invited_at      timestamptz,\n  joined_at       timestamptz not null default now(),\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  unique (organisation_id, user_id),\n  constraint scope_ids_match_kind check (\n    (scope_kind = 'organisation' and cardinality(scope_ids) = 0)\n    or (scope_kind <> 'organisation' and cardinality(scope_ids) > 0)\n  )\n);\n\ncreate index organisation_members_user_idx on public.organisation_members (user_id) where status = 'active';\ncreate index organisation_members_org_idx on public.organisation_members (organisation_id);\n\n-- ── permissions ───────────────────────────────────────────────────────────\n\ncreate table public.permissions (\n  key         text primary key check (key ~ '^[a-z][a-z0-9_]*$'),\n  category    text not null,\n  description text not null\n);\n\ncreate table public.role_permissions (\n  role            public.org_role not null,\n  permission_key  text not null references public.permissions (key) on delete cascade,\n  primary key (role, permission_key)\n);\n\n-- Per-member grants and revocations layered on top of the role defaults.\ncreate table public.member_permission_overrides (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  member_id       uuid not null references public.organisation_members (id) on delete cascade,\n  permission_key  text not null references public.permissions (key) on delete cascade,\n  granted         boolean not null,\n  created_at      timestamptz not null default now(),\n  unique (member_id, permission_key)\n);\n\n-- ── subscriptions and billing ─────────────────────────────────────────────\n\ncreate table public.subscriptions (\n  id                   uuid primary key default gen_random_uuid(),\n  organisation_id      uuid not null unique references public.organisations (id) on delete cascade,\n  plan                 public.subscription_plan not null default 'starter',\n  status               public.subscription_status not null default 'trialing',\n  seats                integer not null default 3 check (seats > 0),\n  data_source_limit    integer not null default 2 check (data_source_limit >= 0),\n  ai_credits_monthly   integer not null default 500 check (ai_credits_monthly >= 0),\n  ai_credits_used      integer not null default 0 check (ai_credits_used >= 0),\n  price_cents_monthly  integer not null default 99900,\n  currency_code        char(3) not null default 'ZAR',\n  trial_ends_at        timestamptz,\n  current_period_start timestamptz not null default date_trunc('month', now()),\n  current_period_end   timestamptz not null default (date_trunc('month', now()) + interval '1 month'),\n  created_at           timestamptz not null default now(),\n  updated_at           timestamptz not null default now()\n);\n\ncreate table public.billing_records (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  description     text not null,\n  amount_cents    integer not null,\n  currency_code   char(3) not null default 'ZAR',\n  status          text not null default 'paid' check (status in ('draft', 'due', 'paid', 'failed', 'refunded')),\n  issued_on       date not null default current_date,\n  paid_at         timestamptz,\n  external_ref    text,\n  created_at      timestamptz not null default now()\n);\n\ncreate index billing_records_org_idx on public.billing_records (organisation_id, issued_on desc);\n\n-- ── audit log ─────────────────────────────────────────────────────────────\n\ncreate table public.audit_logs (\n  id              bigint generated always as identity primary key,\n  organisation_id uuid references public.organisations (id) on delete cascade,\n  actor_id        uuid references auth.users (id) on delete set null,\n  action          text not null,\n  entity_type     text not null,\n  entity_id       text,\n  summary         text,\n  metadata        jsonb not null default '{}'::jsonb,\n  ip_address      inet,\n  user_agent      text,\n  created_at      timestamptz not null default now()\n);\n\ncreate index audit_logs_org_idx on public.audit_logs (organisation_id, created_at desc);\ncreate index audit_logs_actor_idx on public.audit_logs (actor_id, created_at desc);\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090100_02_intelligence.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090100_02_intelligence.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 02 — Intelligence domain\n--   · Data plane        : sources, connections, imports, normalised records\n--   · AI DigitalTwin®   : metrics, health scores, events, insights\n--   · AI OpportunityRadar® : market signals, competitors, opportunities\n--   · Decision layer    : recommendations, goals, risks, alerts, reports\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- ── enums ─────────────────────────────────────────────────────────────────\n\ncreate type public.data_source_category as enum (\n  'accounting', 'crm', 'pos', 'erp', 'spreadsheet', 'database', 'api', 'manual'\n);\n\ncreate type public.connection_status as enum ('pending', 'connected', 'syncing', 'error', 'disabled');\n\ncreate type public.import_status as enum ('uploaded', 'mapping', 'validating', 'ready', 'importing', 'complete', 'failed');\n\ncreate type public.metric_kind as enum ('financial', 'sales', 'operational', 'customer', 'employee', 'growth', 'custom');\n\ncreate type public.health_category as enum ('financial', 'operational', 'sales', 'growth', 'customer', 'strategic');\n\ncreate type public.event_kind as enum ('anomaly', 'trend', 'threshold', 'milestone', 'ingestion', 'manual');\n\ncreate type public.opportunity_kind as enum (\n  'market_expansion', 'partnership', 'supplier', 'distribution',\n  'customer_acquisition', 'product', 'competitive_gap', 'investment'\n);\n\ncreate type public.opportunity_stage as enum (\n  'discovered', 'analysing', 'qualified', 'assigned', 'in_progress', 'won', 'lost', 'archived'\n);\n\ncreate type public.signal_kind as enum (\n  'market', 'industry', 'competitor', 'company_news', 'demand', 'trend', 'risk'\n);\n\ncreate type public.risk_status as enum ('open', 'mitigating', 'monitoring', 'closed', 'accepted');\n\ncreate type public.alert_status as enum ('new', 'acknowledged', 'assigned', 'snoozed', 'dismissed', 'resolved');\n\ncreate type public.goal_status as enum ('draft', 'active', 'at_risk', 'achieved', 'missed', 'cancelled');\n\ncreate type public.recommendation_status as enum ('new', 'accepted', 'in_progress', 'done', 'dismissed');\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- DATA PLANE\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.data_sources (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  name            text not null,\n  category        public.data_source_category not null,\n  provider        text,\n  description     text,\n  created_by      uuid references auth.users (id) on delete set null,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  deleted_at      timestamptz,\n  unique (organisation_id, name)\n);\n\ncreate table public.data_connections (\n  id                 uuid primary key default gen_random_uuid(),\n  organisation_id    uuid not null references public.organisations (id) on delete cascade,\n  data_source_id     uuid not null references public.data_sources (id) on delete cascade,\n  status             public.connection_status not null default 'pending',\n  -- Non-secret connection shape only. Credentials live in the secret manager\n  -- and are referenced by handle, never stored in the tenant database.\n  config             jsonb not null default '{}'::jsonb,\n  credential_ref     text,\n  sync_schedule      text not null default 'daily'\n                       check (sync_schedule in ('manual', 'hourly', 'daily', 'weekly')),\n  field_mapping      jsonb not null default '{}'::jsonb,\n  last_synced_at     timestamptz,\n  last_error         text,\n  consecutive_errors integer not null default 0,\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now()\n);\n\ncreate index data_connections_org_idx on public.data_connections (organisation_id, status);\n\ncreate table public.data_imports (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  filename        text,\n  status          public.import_status not null default 'uploaded',\n  row_count       integer not null default 0,\n  rows_imported   integer not null default 0,\n  rows_rejected   integer not null default 0,\n  column_mapping  jsonb not null default '{}'::jsonb,\n  validation      jsonb not null default '{}'::jsonb,\n  error_message   text,\n  uploaded_by     uuid references auth.users (id) on delete set null,\n  created_at      timestamptz not null default now(),\n  completed_at    timestamptz\n);\n\ncreate index data_imports_org_idx on public.data_imports (organisation_id, created_at desc);\n\n-- Rolling data-quality assessment per source, shown on the Data Health page.\ncreate table public.data_health_checks (\n  id                 uuid primary key default gen_random_uuid(),\n  organisation_id    uuid not null references public.organisations (id) on delete cascade,\n  data_source_id     uuid not null references public.data_sources (id) on delete cascade,\n  completeness_score numeric(5,2) not null check (completeness_score between 0 and 100),\n  freshness_hours    numeric(10,2),\n  error_count        integer not null default 0,\n  missing_fields     text[] not null default '{}',\n  checked_at         timestamptz not null default now()\n);\n\ncreate index data_health_checks_lookup_idx\n  on public.data_health_checks (organisation_id, data_source_id, checked_at desc);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- AI DIGITALTWIN® — normalised business state\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- The metric *definition*: what is measured and how it should be read.\ncreate table public.business_metrics (\n  id                uuid primary key default gen_random_uuid(),\n  organisation_id   uuid not null references public.organisations (id) on delete cascade,\n  key               text not null check (key ~ '^[a-z][a-z0-9_]*$'),\n  label             text not null,\n  kind              public.metric_kind not null,\n  unit              text not null default 'currency'\n                      check (unit in ('currency', 'percent', 'count', 'days', 'ratio', 'score')),\n  -- Which direction is good. Used by trend and anomaly detection to decide\n  -- whether a move is an improvement or a deterioration.\n  higher_is_better  boolean not null default true,\n  target_value      numeric(18,4),\n  health_category   public.health_category,\n  health_weight     numeric(5,4) not null default 0 check (health_weight between 0 and 1),\n  is_active         boolean not null default true,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now(),\n  unique (organisation_id, key)\n);\n\n-- The measurements. One row per metric per period per scope slice.\ncreate table public.metric_values (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  metric_id       uuid not null references public.business_metrics (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete cascade,\n  department_id   uuid references public.departments (id) on delete cascade,\n  period_start    date not null,\n  period_end      date not null,\n  granularity     text not null default 'month'\n                    check (granularity in ('day', 'week', 'month', 'quarter', 'year')),\n  value           numeric(18,4) not null,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  created_at      timestamptz not null default now(),\n  constraint metric_period_ordered check (period_end >= period_start),\n  unique (metric_id, branch_id, department_id, period_start, granularity)\n);\n\ncreate index metric_values_series_idx\n  on public.metric_values (organisation_id, metric_id, period_start desc);\ncreate index metric_values_branch_idx\n  on public.metric_values (organisation_id, branch_id, period_start desc)\n  where branch_id is not null;\n\n-- Transactional detail behind the metrics, kept so the assistant can answer\n-- \"why\" rather than only \"what\".\ncreate table public.financial_records (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  occurred_on     date not null,\n  category        text not null,\n  subcategory     text,\n  amount_cents    bigint not null,\n  currency_code   char(3) not null default 'ZAR',\n  direction       text not null check (direction in ('income', 'expense')),\n  reference       text,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  created_at      timestamptz not null default now()\n);\n\ncreate index financial_records_org_idx\n  on public.financial_records (organisation_id, occurred_on desc);\n\ncreate table public.sales_records (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  occurred_on     date not null,\n  customer_ref    text,\n  customer_name   text,\n  product_line    text,\n  quantity        numeric(14,3) not null default 1,\n  amount_cents    bigint not null,\n  currency_code   char(3) not null default 'ZAR',\n  margin_cents    bigint,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  created_at      timestamptz not null default now()\n);\n\ncreate index sales_records_org_idx on public.sales_records (organisation_id, occurred_on desc);\ncreate index sales_records_customer_idx\n  on public.sales_records (organisation_id, customer_ref, occurred_on desc)\n  where customer_ref is not null;\n\ncreate table public.operational_records (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  occurred_on     date not null,\n  measure         text not null,\n  value           numeric(18,4) not null,\n  unit            text,\n  data_source_id  uuid references public.data_sources (id) on delete set null,\n  created_at      timestamptz not null default now()\n);\n\ncreate index operational_records_org_idx\n  on public.operational_records (organisation_id, measure, occurred_on desc);\n\n-- Health score history — the Digital Twin's headline reading over time.\ncreate table public.business_health_scores (\n  id                uuid primary key default gen_random_uuid(),\n  organisation_id   uuid not null references public.organisations (id) on delete cascade,\n  branch_id         uuid references public.branches (id) on delete cascade,\n  score             numeric(5,2) not null check (score between 0 and 100),\n  classification    text not null\n                      check (classification in ('excellent', 'healthy', 'attention', 'at_risk', 'critical')),\n  -- { financial: 78.4, operational: 62.0, ... } plus the weights in force.\n  category_scores   jsonb not null default '{}'::jsonb,\n  weights           jsonb not null default '{}'::jsonb,\n  contributing_metrics jsonb not null default '[]'::jsonb,\n  calculated_for    date not null,\n  calculated_at     timestamptz not null default now(),\n  unique (organisation_id, branch_id, calculated_for)\n);\n\ncreate index business_health_scores_idx\n  on public.business_health_scores (organisation_id, calculated_for desc);\n\n-- Configurable weighting per organisation (spec §26).\ncreate table public.health_score_weights (\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  category        public.health_category not null,\n  weight          numeric(5,4) not null check (weight between 0 and 1),\n  updated_at      timestamptz not null default now(),\n  primary key (organisation_id, category)\n);\n\n-- Things that happened inside the business.\ncreate table public.business_events (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete cascade,\n  department_id   uuid references public.departments (id) on delete cascade,\n  metric_id       uuid references public.business_metrics (id) on delete set null,\n  kind            public.event_kind not null,\n  severity        public.priority_level not null default 'low',\n  title           text not null,\n  detail          text,\n  evidence        jsonb not null default '{}'::jsonb,\n  occurred_at     timestamptz not null default now(),\n  created_at      timestamptz not null default now()\n);\n\ncreate index business_events_feed_idx\n  on public.business_events (organisation_id, occurred_at desc);\n\n-- What the Digital Twin concluded, as opposed to what merely happened.\ncreate table public.business_insights (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n  branch_id        uuid references public.branches (id) on delete cascade,\n  headline         text not null,\n  narrative        text not null,\n  category         public.health_category,\n  direction        public.trend_direction not null default 'flat',\n  impact_cents     bigint,\n  confidence       numeric(4,3) not null default 0.5 check (confidence between 0 and 1),\n  evidence         jsonb not null default '[]'::jsonb,\n  source_event_ids uuid[] not null default '{}',\n  generated_by     text not null default 'engine' check (generated_by in ('engine', 'llm', 'human')),\n  valid_from       date not null default current_date,\n  valid_to         date,\n  created_at       timestamptz not null default now()\n);\n\ncreate index business_insights_org_idx\n  on public.business_insights (organisation_id, created_at desc);\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090200_03_market_and_decisions.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090200_03_market_and_decisions.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 03 — AI OpportunityRadar®, decision layer and assistant\n--\n-- Scanning policy: Amryn is a private-sector intelligence platform. Market\n-- sources carry a `sector_policy` and signals a `sector` so that public-sector\n-- tenders, programmes and events can be excluded by default (spec §2). The\n-- default org setting excludes them; an organisation may opt in explicitly.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate type public.market_sector as enum ('private', 'public', 'mixed', 'unknown');\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- EXTERNAL INTELLIGENCE\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.market_sources (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid references public.organisations (id) on delete cascade,\n  name            text not null,\n  kind            text not null\n                    check (kind in ('news', 'industry_report', 'company_filing', 'jobs_board',\n                                    'directory', 'social', 'search_trend', 'manual')),\n  url             text,\n  -- Which sectors this source is allowed to contribute. Defaults to private\n  -- only, which is the platform's standing scanning posture.\n  sector_policy   public.market_sector[] not null default '{private}',\n  is_global       boolean not null default false,\n  reliability     numeric(4,3) not null default 0.7 check (reliability between 0 and 1),\n  last_scanned_at timestamptz,\n  is_active       boolean not null default true,\n  created_at      timestamptz not null default now(),\n  constraint global_sources_have_no_org check (\n    (is_global and organisation_id is null) or (not is_global and organisation_id is not null)\n  )\n);\n\ncreate table public.competitors (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  name            text not null,\n  website         text,\n  description     text,\n  markets         text[] not null default '{}',\n  threat_level    public.priority_level not null default 'medium',\n  is_tracked      boolean not null default true,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  unique (organisation_id, name)\n);\n\ncreate table public.competitor_events (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  competitor_id   uuid not null references public.competitors (id) on delete cascade,\n  kind            text not null\n                    check (kind in ('launch', 'expansion', 'pricing', 'partnership',\n                                    'hiring', 'funding', 'exit', 'other')),\n  title           text not null,\n  detail          text,\n  impact          public.priority_level not null default 'medium',\n  source_url      text,\n  observed_on     date not null default current_date,\n  created_at      timestamptz not null default now()\n);\n\ncreate index competitor_events_org_idx\n  on public.competitor_events (organisation_id, observed_on desc);\n\ncreate table public.market_signals (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  market_source_id uuid references public.market_sources (id) on delete set null,\n  kind            public.signal_kind not null,\n  sector          public.market_sector not null default 'private',\n  title           text not null,\n  summary         text not null,\n  detail          text,\n  entities        text[] not null default '{}',\n  keywords        text[] not null default '{}',\n  relevance       numeric(4,3) not null default 0.5 check (relevance between 0 and 1),\n  confidence      numeric(4,3) not null default 0.5 check (confidence between 0 and 1),\n  source_url      text,\n  observed_at     timestamptz not null default now(),\n  created_at      timestamptz not null default now()\n);\n\ncreate index market_signals_feed_idx\n  on public.market_signals (organisation_id, observed_at desc);\ncreate index market_signals_sector_idx on public.market_signals (organisation_id, sector);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- OPPORTUNITIES\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.opportunities (\n  id                  uuid primary key default gen_random_uuid(),\n  organisation_id     uuid not null references public.organisations (id) on delete cascade,\n  branch_id           uuid references public.branches (id) on delete set null,\n  title               text not null,\n  kind                public.opportunity_kind not null,\n  sector              public.market_sector not null default 'private',\n  counterparty        text,\n  summary             text not null,\n  why_it_matters      text,\n  recommended_action  text,\n  estimated_value_cents bigint,\n  currency_code       char(3) not null default 'ZAR',\n  stage               public.opportunity_stage not null default 'discovered',\n  score               numeric(5,2) check (score between 0 and 100),\n  classification      text check (classification in ('high_priority', 'strong', 'potential', 'monitor')),\n  closes_on           date,\n  source_signal_ids   uuid[] not null default '{}',\n  source_urls         text[] not null default '{}',\n  is_saved            boolean not null default false,\n  created_at          timestamptz not null default now(),\n  updated_at          timestamptz not null default now(),\n  deleted_at          timestamptz\n);\n\ncreate index opportunities_pipeline_idx\n  on public.opportunities (organisation_id, stage, score desc nulls last);\ncreate index opportunities_saved_idx\n  on public.opportunities (organisation_id) where is_saved;\n\n-- Every scoring run is kept, so a change in ranking is explainable.\ncreate table public.opportunity_scores (\n  id                  uuid primary key default gen_random_uuid(),\n  organisation_id     uuid not null references public.organisations (id) on delete cascade,\n  opportunity_id      uuid not null references public.opportunities (id) on delete cascade,\n  relevance           numeric(5,2) not null check (relevance between 0 and 100),\n  potential_value     numeric(5,2) not null check (potential_value between 0 and 100),\n  strategic_alignment numeric(5,2) not null check (strategic_alignment between 0 and 100),\n  urgency             numeric(5,2) not null check (urgency between 0 and 100),\n  confidence          numeric(5,2) not null check (confidence between 0 and 100),\n  competition         numeric(5,2) not null check (competition between 0 and 100),\n  total               numeric(5,2) not null check (total between 0 and 100),\n  weights             jsonb not null default '{}'::jsonb,\n  rationale           text,\n  scored_at           timestamptz not null default now()\n);\n\ncreate index opportunity_scores_idx\n  on public.opportunity_scores (opportunity_id, scored_at desc);\n\n-- Configurable scoring weights per organisation (spec §27).\ncreate table public.opportunity_score_weights (\n  organisation_id uuid primary key references public.organisations (id) on delete cascade,\n  weights         jsonb not null default\n    '{\"relevance\":0.25,\"potential_value\":0.20,\"strategic_alignment\":0.20,\"urgency\":0.15,\"confidence\":0.10,\"competition\":0.10}'::jsonb,\n  updated_at      timestamptz not null default now()\n);\n\ncreate table public.opportunity_assignments (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  opportunity_id  uuid not null references public.opportunities (id) on delete cascade,\n  assignee_id     uuid not null references auth.users (id) on delete cascade,\n  assigned_by     uuid references auth.users (id) on delete set null,\n  due_on          date,\n  note            text,\n  released_at     timestamptz,\n  created_at      timestamptz not null default now()\n);\n\ncreate index opportunity_assignments_idx\n  on public.opportunity_assignments (organisation_id, assignee_id)\n  where released_at is null;\n\ncreate table public.opportunity_activities (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  opportunity_id  uuid not null references public.opportunities (id) on delete cascade,\n  actor_id        uuid references auth.users (id) on delete set null,\n  kind            text not null\n                    check (kind in ('note', 'stage_change', 'assignment', 'score_change',\n                                    'ai_analysis', 'attachment')),\n  body            text,\n  metadata        jsonb not null default '{}'::jsonb,\n  created_at      timestamptz not null default now()\n);\n\ncreate index opportunity_activities_idx\n  on public.opportunity_activities (opportunity_id, created_at desc);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- STRATEGY\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.goals (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  metric_id       uuid references public.business_metrics (id) on delete set null,\n  title           text not null,\n  description     text,\n  owner_id        uuid references auth.users (id) on delete set null,\n  baseline_value  numeric(18,4),\n  target_value    numeric(18,4) not null,\n  current_value   numeric(18,4),\n  unit            text not null default 'currency',\n  status          public.goal_status not null default 'active',\n  starts_on       date not null default current_date,\n  due_on          date not null,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\ncreate index goals_org_idx on public.goals (organisation_id, status, due_on);\n\ncreate table public.goal_progress (\n  id            uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  goal_id       uuid not null references public.goals (id) on delete cascade,\n  value         numeric(18,4) not null,\n  note          text,\n  recorded_on   date not null default current_date,\n  recorded_by   uuid references auth.users (id) on delete set null,\n  created_at    timestamptz not null default now(),\n  unique (goal_id, recorded_on)\n);\n\ncreate table public.strategic_initiatives (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  title           text not null,\n  thesis          text,\n  owner_id        uuid references auth.users (id) on delete set null,\n  status          text not null default 'proposed'\n                    check (status in ('proposed', 'approved', 'active', 'paused', 'complete', 'cancelled')),\n  goal_ids        uuid[] not null default '{}',\n  opportunity_ids uuid[] not null default '{}',\n  starts_on       date,\n  ends_on         date,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- RECOMMENDATIONS — where inside meets outside\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.ai_recommendations (\n  id                uuid primary key default gen_random_uuid(),\n  organisation_id   uuid not null references public.organisations (id) on delete cascade,\n  branch_id         uuid references public.branches (id) on delete set null,\n  title             text not null,\n  summary           text not null,\n  why_it_matters    text not null,\n  recommended_action text not null,\n  evidence          jsonb not null default '[]'::jsonb,\n  impact_cents      bigint,\n  impact_note       text,\n  confidence        numeric(4,3) not null default 0.5 check (confidence between 0 and 1),\n  priority          public.priority_level not null default 'medium',\n  status            public.recommendation_status not null default 'new',\n  -- Provenance: which internal insight and which external signal produced this.\n  insight_ids       uuid[] not null default '{}',\n  signal_ids        uuid[] not null default '{}',\n  opportunity_id    uuid references public.opportunities (id) on delete set null,\n  generated_by      text not null default 'engine' check (generated_by in ('engine', 'llm', 'human')),\n  owner_id          uuid references auth.users (id) on delete set null,\n  created_at        timestamptz not null default now(),\n  updated_at        timestamptz not null default now(),\n  expires_on        date\n);\n\ncreate index ai_recommendations_board_idx\n  on public.ai_recommendations (organisation_id, status, priority, created_at desc);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- RISK AND ALERTS\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.risks (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  title           text not null,\n  description     text,\n  category        text not null default 'operational'\n                    check (category in ('financial', 'operational', 'market', 'customer',\n                                        'compliance', 'people', 'technology', 'supply')),\n  likelihood      smallint not null default 3 check (likelihood between 1 and 5),\n  impact          smallint not null default 3 check (impact between 1 and 5),\n  -- Stored, not generated, so historical scores survive a scale change.\n  severity        public.priority_level not null default 'medium',\n  status          public.risk_status not null default 'open',\n  owner_id        uuid references auth.users (id) on delete set null,\n  mitigation      text,\n  review_on       date,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\ncreate index risks_register_idx on public.risks (organisation_id, status, severity);\n\ncreate table public.risk_events (\n  id           uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  risk_id      uuid not null references public.risks (id) on delete cascade,\n  actor_id     uuid references auth.users (id) on delete set null,\n  kind         text not null\n                 check (kind in ('raised', 'reassessed', 'mitigation', 'status_change', 'note', 'closed')),\n  body         text,\n  metadata     jsonb not null default '{}'::jsonb,\n  created_at   timestamptz not null default now()\n);\n\ncreate table public.alerts (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  branch_id       uuid references public.branches (id) on delete set null,\n  department_id   uuid references public.departments (id) on delete set null,\n  severity        public.priority_level not null default 'medium',\n  status          public.alert_status not null default 'new',\n  title           text not null,\n  detail          text,\n  -- What raised it, so the alert can be traced back to its evidence.\n  source_kind     text not null default 'engine'\n                    check (source_kind in ('engine', 'threshold', 'sync', 'radar', 'manual')),\n  business_event_id uuid references public.business_events (id) on delete set null,\n  risk_id         uuid references public.risks (id) on delete set null,\n  opportunity_id  uuid references public.opportunities (id) on delete set null,\n  assignee_id     uuid references auth.users (id) on delete set null,\n  snoozed_until   timestamptz,\n  acknowledged_at timestamptz,\n  resolved_at     timestamptz,\n  created_at      timestamptz not null default now()\n);\n\ncreate index alerts_inbox_idx\n  on public.alerts (organisation_id, status, severity, created_at desc);\n\ncreate table public.notifications (\n  id           uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  user_id      uuid not null references auth.users (id) on delete cascade,\n  title        text not null,\n  body         text,\n  href         text,\n  kind         text not null default 'info'\n                 check (kind in ('info', 'alert', 'opportunity', 'recommendation', 'system')),\n  read_at      timestamptz,\n  created_at   timestamptz not null default now()\n);\n\ncreate index notifications_user_idx\n  on public.notifications (user_id, created_at desc) where read_at is null;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- REPORTS AND ASSISTANT\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.reports (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  kind            text not null\n                    check (kind in ('executive_summary', 'business_performance', 'financial',\n                                    'opportunity', 'market_intelligence', 'risk', 'ai_briefing')),\n  title           text not null,\n  parameters      jsonb not null default '{}'::jsonb,\n  content         jsonb not null default '{}'::jsonb,\n  period_start    date,\n  period_end      date,\n  generated_by    uuid references auth.users (id) on delete set null,\n  created_at      timestamptz not null default now()\n);\n\ncreate index reports_org_idx on public.reports (organisation_id, created_at desc);\n\ncreate table public.ai_conversations (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  user_id         uuid not null references auth.users (id) on delete cascade,\n  title           text not null default 'New conversation',\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now()\n);\n\ncreate index ai_conversations_user_idx\n  on public.ai_conversations (user_id, updated_at desc);\n\ncreate table public.ai_messages (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  conversation_id uuid not null references public.ai_conversations (id) on delete cascade,\n  role            text not null check (role in ('user', 'assistant', 'system', 'tool')),\n  content         text not null,\n  -- Data the answer was drawn from, so every claim is traceable.\n  citations       jsonb not null default '[]'::jsonb,\n  visualisations  jsonb not null default '[]'::jsonb,\n  suggested_actions jsonb not null default '[]'::jsonb,\n  tokens_used     integer,\n  model           text,\n  created_at      timestamptz not null default now()\n);\n\ncreate index ai_messages_thread_idx\n  on public.ai_messages (conversation_id, created_at);\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090300_04_security_rls.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090300_04_security_rls.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 04 — Row Level Security\n--\n-- The rule this file enforces: a user reads a row only if\n--   (a) they are an ACTIVE member of that row's organisation, and\n--   (b) the row's branch/department falls inside their scope, and\n--   (c) for sensitive tables, they hold the relevant permission.\n--\n-- All three are decided in SQL. The application layer re-checks permissions to\n-- give good error messages, but it is not what keeps tenants apart.\n--\n-- The helper functions are SECURITY DEFINER on purpose: they read\n-- organisation_members, which is itself RLS-protected, and a policy that\n-- queried it directly would recurse.\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- ── helpers ───────────────────────────────────────────────────────────────\n\ncreate or replace function amryn.active_member(p_org uuid)\nreturns public.organisation_members\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select m.*\n  from public.organisation_members m\n  where m.organisation_id = p_org\n    and m.user_id = auth.uid()\n    and m.status = 'active'\n  limit 1;\n$$;\n\ncreate or replace function amryn.is_member(p_org uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select exists (\n    select 1\n    from public.organisation_members m\n    where m.organisation_id = p_org\n      and m.user_id = auth.uid()\n      and m.status = 'active'\n  );\n$$;\n\ncreate or replace function amryn.member_role(p_org uuid)\nreturns public.org_role\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select m.role\n  from public.organisation_members m\n  where m.organisation_id = p_org\n    and m.user_id = auth.uid()\n    and m.status = 'active'\n  limit 1;\n$$;\n\n-- Administrative reach: may manage members, structure and connections.\ncreate or replace function amryn.is_org_admin(p_org uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(amryn.member_role(p_org) in ('super_admin', 'org_admin'), false);\n$$;\n\n-- Effective permission = role default, then any per-member override.\ncreate or replace function amryn.has_permission(p_org uuid, p_permission text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  with member as (\n    select m.id, m.role\n    from public.organisation_members m\n    where m.organisation_id = p_org\n      and m.user_id = auth.uid()\n      and m.status = 'active'\n    limit 1\n  ),\n  override as (\n    select o.granted\n    from public.member_permission_overrides o\n    join member on member.id = o.member_id\n    where o.permission_key = p_permission\n    limit 1\n  ),\n  role_default as (\n    select true as granted\n    from public.role_permissions rp\n    join member on member.role = rp.role\n    where rp.permission_key = p_permission\n    limit 1\n  )\n  select coalesce(\n    (select granted from override),\n    (select granted from role_default),\n    false\n  );\n$$;\n\n-- The branches a member may see. NULL means \"the whole organisation\".\ncreate or replace function amryn.visible_branch_ids(p_org uuid)\nreturns uuid[]\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  m public.organisation_members;\n  result uuid[];\nbegin\n  select * into m from amryn.active_member(p_org);\n  if m.id is null then\n    return '{}'::uuid[];\n  end if;\n\n  case m.scope_kind\n    when 'organisation' then\n      return null;                                   -- unrestricted\n    when 'region' then\n      select coalesce(array_agg(b.id), '{}')\n        into result\n        from public.branches b\n       where b.organisation_id = p_org\n         and b.region_id = any (m.scope_ids);\n    when 'branch' then\n      select coalesce(array_agg(b.id), '{}')\n        into result\n        from public.branches b\n       where b.organisation_id = p_org\n         and b.id = any (m.scope_ids);\n    when 'department' then\n      select coalesce(array_agg(distinct d.branch_id), '{}')\n        into result\n        from public.departments d\n       where d.organisation_id = p_org\n         and d.id = any (m.scope_ids)\n         and d.branch_id is not null;\n  end case;\n\n  return coalesce(result, '{}'::uuid[]);\nend;\n$$;\n\n-- Can this member see a row carrying p_branch?\n--   · a NULL branch is an organisation-level row, reserved for org-wide scope\n--   · otherwise the branch must fall inside the member's visible set\ncreate or replace function amryn.can_see_branch(p_org uuid, p_branch uuid)\nreturns boolean\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  visible uuid[];\nbegin\n  if not amryn.is_member(p_org) then\n    return false;\n  end if;\n\n  visible := amryn.visible_branch_ids(p_org);\n\n  if visible is null then\n    return true;                                     -- organisation-wide scope\n  end if;\n\n  if p_branch is null then\n    return false;                                    -- aggregate row, scoped member\n  end if;\n\n  return p_branch = any (visible);\nend;\n$$;\n\ncreate or replace function amryn.can_see_department(p_org uuid, p_department uuid)\nreturns boolean\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  m public.organisation_members;\n  parent_branch uuid;\nbegin\n  select * into m from amryn.active_member(p_org);\n  if m.id is null then\n    return false;\n  end if;\n\n  if p_department is null then\n    return m.scope_kind <> 'department';\n  end if;\n\n  if m.scope_kind = 'department' then\n    return p_department = any (m.scope_ids);\n  end if;\n\n  select branch_id into parent_branch\n    from public.departments\n   where id = p_department and organisation_id = p_org;\n\n  return amryn.can_see_branch(p_org, parent_branch);\nend;\n$$;\n\ngrant execute on function\n  amryn.is_member(uuid),\n  amryn.member_role(uuid),\n  amryn.is_org_admin(uuid),\n  amryn.has_permission(uuid, text),\n  amryn.visible_branch_ids(uuid),\n  amryn.can_see_branch(uuid, uuid),\n  amryn.can_see_department(uuid, uuid)\nto authenticated;\n\n-- active_member returns a whole member row; keep it internal.\nrevoke all on function amryn.active_member(uuid) from public, anon, authenticated;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Enable RLS everywhere, then deny by default.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ndo $$\ndeclare\n  t text;\nbegin\n  foreach t in array array[\n    'organisations','user_profiles','regions','branches','departments',\n    'organisation_members','permissions','role_permissions',\n    'member_permission_overrides','subscriptions','billing_records','audit_logs',\n    'data_sources','data_connections','data_imports','data_health_checks',\n    'business_metrics','metric_values','financial_records','sales_records',\n    'operational_records','business_health_scores','health_score_weights',\n    'business_events','business_insights',\n    'market_sources','competitors','competitor_events','market_signals',\n    'opportunities','opportunity_scores','opportunity_score_weights',\n    'opportunity_assignments','opportunity_activities',\n    'goals','goal_progress','strategic_initiatives','ai_recommendations',\n    'risks','risk_events','alerts','notifications','reports',\n    'ai_conversations','ai_messages'\n  ]\n  loop\n    execute format('alter table public.%I enable row level security', t);\n    execute format('alter table public.%I force row level security', t);\n  end loop;\nend;\n$$;\n\n-- ── identity and tenancy ──────────────────────────────────────────────────\n\ncreate policy organisations_read on public.organisations\n  for select to authenticated\n  using (amryn.is_member(id) and deleted_at is null);\n\ncreate policy organisations_update on public.organisations\n  for update to authenticated\n  using (amryn.is_org_admin(id))\n  with check (amryn.is_org_admin(id));\n\n-- A user sees their own profile, plus the profiles of people they share an\n-- organisation with — needed to render owners, assignees and activity.\ncreate policy user_profiles_read on public.user_profiles\n  for select to authenticated\n  using (\n    id = auth.uid()\n    or exists (\n      select 1\n      from public.organisation_members me\n      join public.organisation_members them\n        on them.organisation_id = me.organisation_id\n      where me.user_id = auth.uid()\n        and me.status = 'active'\n        and them.user_id = public.user_profiles.id\n    )\n  );\n\ncreate policy user_profiles_write on public.user_profiles\n  for update to authenticated\n  using (id = auth.uid())\n  with check (id = auth.uid());\n\ncreate policy user_profiles_insert on public.user_profiles\n  for insert to authenticated\n  with check (id = auth.uid());\n\ncreate policy members_read on public.organisation_members\n  for select to authenticated\n  using (user_id = auth.uid() or amryn.is_member(organisation_id));\n\ncreate policy members_manage on public.organisation_members\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_users'))\n  with check (amryn.has_permission(organisation_id, 'manage_users'));\n\ncreate policy overrides_read on public.member_permission_overrides\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\ncreate policy overrides_manage on public.member_permission_overrides\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_users'))\n  with check (amryn.has_permission(organisation_id, 'manage_users'));\n\n-- The permission catalogue is reference data: readable, never writable.\ncreate policy permissions_read on public.permissions\n  for select to authenticated using (true);\n\ncreate policy role_permissions_read on public.role_permissions\n  for select to authenticated using (true);\n\n-- ── organisational structure ──────────────────────────────────────────────\n\ncreate policy regions_read on public.regions\n  for select to authenticated\n  using (amryn.is_member(organisation_id) and deleted_at is null);\n\ncreate policy regions_manage on public.regions\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ncreate policy branches_read on public.branches\n  for select to authenticated\n  using (amryn.can_see_branch(organisation_id, id) and deleted_at is null);\n\ncreate policy branches_manage on public.branches\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ncreate policy departments_read on public.departments\n  for select to authenticated\n  using (amryn.can_see_department(organisation_id, id) and deleted_at is null);\n\ncreate policy departments_manage on public.departments\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\n-- ── billing ───────────────────────────────────────────────────────────────\n\ncreate policy subscriptions_read on public.subscriptions\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\ncreate policy subscriptions_manage on public.subscriptions\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_billing'))\n  with check (amryn.has_permission(organisation_id, 'manage_billing'));\n\ncreate policy billing_read on public.billing_records\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_billing'));\n\n-- ── audit ─────────────────────────────────────────────────────────────────\n-- Readable by administrators; append-only for everyone, and never editable.\n\ncreate policy audit_read on public.audit_logs\n  for select to authenticated\n  using (organisation_id is not null and amryn.has_permission(organisation_id, 'view_audit_log'));\n\ncreate policy audit_append on public.audit_logs\n  for insert to authenticated\n  with check (organisation_id is null or amryn.is_member(organisation_id));\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090400_05_domain_rls.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090400_05_domain_rls.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 05 — Row Level Security for the intelligence domain\n--\n-- Most domain tables follow one of two shapes, so they are generated from a\n-- single declaration list. The list is the thing to review: it states, per\n-- table, which permission gates reading and writing and whether rows are\n-- narrowed by branch scope.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ndo $$\ndeclare\n  spec record;\n  branch_clause text;\nbegin\n  for spec in\n    select *\n    from (values\n      -- table,                        read permission,          write permission,        branch-scoped\n      ('data_sources',                 'view_data_sources',      'manage_integrations',   false),\n      ('data_connections',             'view_data_sources',      'manage_integrations',   false),\n      ('data_imports',                 'view_data_sources',      'import_data',           false),\n      ('data_health_checks',           'view_data_sources',      'manage_integrations',   false),\n\n      ('business_metrics',             'view_performance',       'manage_metrics',        false),\n      ('metric_values',                'view_performance',       'import_data',           true),\n      ('financial_records',            'view_financial_data',    'import_data',           true),\n      ('sales_records',                'view_sales_data',        'import_data',           true),\n      ('operational_records',          'view_operations_data',   'import_data',           true),\n\n      ('business_health_scores',       'view_performance',       'manage_metrics',        true),\n      ('health_score_weights',         'view_performance',       'manage_metrics',        false),\n      ('business_events',              'view_intelligence',      'manage_metrics',        true),\n      ('business_insights',            'view_intelligence',      'manage_metrics',        true),\n\n      ('competitors',                  'view_competitors',       'manage_competitors',    false),\n      ('competitor_events',            'view_competitors',       'manage_competitors',    false),\n      ('market_signals',               'view_market_intelligence','manage_radar',         false),\n\n      ('opportunities',                'view_opportunities',     'manage_opportunities',  true),\n      ('opportunity_scores',           'view_opportunities',     'manage_opportunities',  false),\n      ('opportunity_score_weights',    'view_opportunities',     'manage_radar',          false),\n      ('opportunity_activities',       'view_opportunities',     'view_opportunities',    false),\n\n      ('goals',                        'view_goals',             'manage_goals',          true),\n      ('goal_progress',                'view_goals',             'manage_goals',          false),\n      ('strategic_initiatives',        'view_goals',             'manage_goals',          false),\n      ('ai_recommendations',           'view_recommendations',   'manage_recommendations',true),\n\n      ('risks',                        'view_risks',             'manage_risks',          true),\n      ('risk_events',                  'view_risks',             'manage_risks',          false),\n      ('alerts',                       'view_alerts',            'manage_alerts',         true),\n      ('reports',                      'generate_reports',       'generate_reports',      false)\n    ) as t(tbl, read_perm, write_perm, branch_scoped)\n  loop\n    branch_clause := case\n      when spec.branch_scoped then ' and amryn.can_see_branch(organisation_id, branch_id)'\n      else ''\n    end;\n\n    execute format(\n      'create policy %I on public.%I for select to authenticated using (amryn.has_permission(organisation_id, %L)%s)',\n      spec.tbl || '_read', spec.tbl, spec.read_perm, branch_clause\n    );\n\n    execute format(\n      'create policy %I on public.%I for insert to authenticated with check (amryn.has_permission(organisation_id, %L)%s)',\n      spec.tbl || '_insert', spec.tbl, spec.write_perm, branch_clause\n    );\n\n    execute format(\n      'create policy %I on public.%I for update to authenticated using (amryn.has_permission(organisation_id, %L)%s) with check (amryn.has_permission(organisation_id, %L)%s)',\n      spec.tbl || '_update', spec.tbl, spec.write_perm, branch_clause, spec.write_perm, branch_clause\n    );\n\n    execute format(\n      'create policy %I on public.%I for delete to authenticated using (amryn.has_permission(organisation_id, %L)%s)',\n      spec.tbl || '_delete', spec.tbl, spec.write_perm, branch_clause\n    );\n  end loop;\nend;\n$$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Tables that do not fit the pattern\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Market sources: global catalogue rows are readable by every tenant; an\n-- organisation's own sources are private to it.\ncreate policy market_sources_read on public.market_sources\n  for select to authenticated\n  using (\n    is_global\n    or (organisation_id is not null and amryn.has_permission(organisation_id, 'view_market_intelligence'))\n  );\n\ncreate policy market_sources_manage on public.market_sources\n  for all to authenticated\n  using (organisation_id is not null and amryn.has_permission(organisation_id, 'manage_radar'))\n  with check (organisation_id is not null and amryn.has_permission(organisation_id, 'manage_radar'));\n\n-- Assignments: assignees always see their own, regardless of the wider\n-- opportunity permission, because the work has been given to them.\ncreate policy opportunity_assignments_read on public.opportunity_assignments\n  for select to authenticated\n  using (\n    assignee_id = auth.uid()\n    or amryn.has_permission(organisation_id, 'view_opportunities')\n  );\n\ncreate policy opportunity_assignments_manage on public.opportunity_assignments\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'assign_opportunities'))\n  with check (amryn.has_permission(organisation_id, 'assign_opportunities'));\n\n-- Notifications are personal.\ncreate policy notifications_read on public.notifications\n  for select to authenticated\n  using (user_id = auth.uid());\n\ncreate policy notifications_update on public.notifications\n  for update to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\ncreate policy notifications_insert on public.notifications\n  for insert to authenticated\n  with check (amryn.is_member(organisation_id));\n\n-- Assistant threads are private to the user who held the conversation. An\n-- executive cannot read a colleague's questions.\ncreate policy ai_conversations_own on public.ai_conversations\n  for all to authenticated\n  using (user_id = auth.uid() and amryn.is_member(organisation_id))\n  with check (user_id = auth.uid() and amryn.is_member(organisation_id));\n\ncreate policy ai_messages_own on public.ai_messages\n  for all to authenticated\n  using (\n    amryn.is_member(organisation_id)\n    and exists (\n      select 1 from public.ai_conversations c\n      where c.id = ai_messages.conversation_id and c.user_id = auth.uid()\n    )\n  )\n  with check (\n    amryn.is_member(organisation_id)\n    and exists (\n      select 1 from public.ai_conversations c\n      where c.id = ai_messages.conversation_id and c.user_id = auth.uid()\n    )\n  );\n\n-- ── grants ────────────────────────────────────────────────────────────────\n-- RLS decides which rows; these decide which verbs are possible at all.\n\ngrant usage on schema public to authenticated;\ngrant select, insert, update, delete on all tables in schema public to authenticated;\ngrant usage, select on all sequences in schema public to authenticated;\n\n-- Reference tables are never written from a session.\nrevoke insert, update, delete on public.permissions from authenticated;\nrevoke insert, update, delete on public.role_permissions from authenticated;\nrevoke update, delete on public.audit_logs from authenticated;\n\n-- Nothing in this schema is reachable without a session.\nrevoke all on all tables in schema public from anon;\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260829090500_06_permissions_and_triggers.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260829090500_06_permissions_and_triggers.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 06 — Permission catalogue, role matrix, triggers\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Migration 04 applies `force row level security` to all 45 tables, and these\n-- two carry a select policy and nothing else. FORCE is the part that matters:\n-- ordinary RLS exempts a table's owner, FORCE does not, so these seed inserts\n-- are refused for anyone lacking BYPASSRLS — including whoever is applying the\n-- migration.\n--\n--   ERROR: new row violates row-level security policy for table \"permissions\"\n--\n-- Superusers bypass RLS unconditionally, so a local PostgreSQL never showed\n-- it. Whether a hosted project does depends on whether its role happens to\n-- carry BYPASSRLS, which is not a thing to build a schema on.\n--\n-- FORCE is lifted for the length of the seed and restored immediately. Both\n-- statements are inside the migration's transaction, so there is no window in\n-- which the tables are deployed unprotected.\n--\n-- These two are a fixed catalogue, not tenant data: every organisation reads\n-- the same rows, which is why a select policy is all they ever needed.\nalter table public.permissions      no force row level security;\nalter table public.role_permissions no force row level security;\n\ninsert into public.permissions (key, category, description) values\n  ('view_performance',        'Performance',    'View business performance dashboards and metrics'),\n  ('view_financial_data',     'Performance',    'View revenue, cost, margin and cash figures'),\n  ('view_sales_data',         'Performance',    'View sales records, customers and pipeline value'),\n  ('view_operations_data',    'Performance',    'View operational measures such as delivery and utilisation'),\n  ('view_intelligence',       'Intelligence',   'View AI DigitalTwin® findings, events and insights'),\n  ('view_market_intelligence','Intelligence',   'View external market signals'),\n  ('view_competitors',        'Intelligence',   'View tracked competitors and their activity'),\n  ('view_opportunities',      'Opportunities',  'View the opportunity pipeline and radar'),\n  ('assign_opportunities',    'Opportunities',  'Assign opportunities to colleagues'),\n  ('manage_opportunities',    'Opportunities',  'Create, edit and progress opportunities'),\n  ('view_recommendations',    'Strategy',       'View AI recommendations'),\n  ('manage_recommendations',  'Strategy',       'Accept, dismiss and progress recommendations'),\n  ('view_goals',              'Strategy',       'View goals and strategic initiatives'),\n  ('manage_goals',            'Strategy',       'Create and edit goals and initiatives'),\n  ('view_risks',              'Risk',           'View the risk register and risk dashboard'),\n  ('manage_risks',            'Risk',           'Raise, reassess and close risks'),\n  ('view_alerts',             'Risk',           'View alerts'),\n  ('manage_alerts',           'Risk',           'Acknowledge, assign, snooze and dismiss alerts'),\n  ('view_data_sources',       'Data',           'View connected sources, imports and data health'),\n  ('import_data',             'Data',           'Upload and import business data'),\n  ('manage_integrations',     'Data',           'Create and configure data connections'),\n  ('manage_metrics',          'Data',           'Define metrics and health-score weighting'),\n  ('manage_competitors',      'Intelligence',   'Add and edit tracked competitors'),\n  ('manage_radar',            'Intelligence',   'Configure market sources and radar scoring'),\n  ('generate_reports',        'Reporting',      'Generate and export reports'),\n  ('use_ai_assistant',        'Intelligence',   'Ask the Amryn AI Assistant questions'),\n  ('view_audit_log',          'Administration', 'Read the organisation audit trail'),\n  ('manage_users',            'Administration', 'Invite, edit and remove members and permissions'),\n  ('manage_organisation',     'Administration', 'Edit the organisation, regions, branches and departments'),\n  ('manage_billing',          'Administration', 'View and change the subscription and billing details');\n\n-- ── role matrix ───────────────────────────────────────────────────────────\n-- Reach widens down the list; scope (which branches a member sees) is a\n-- separate axis, applied by RLS on top of these grants.\n\ndo $$\ndeclare\n  everything text[] := array(select key from public.permissions order by key);\n\n  viewer text[] := array[\n    'view_performance','view_intelligence','view_market_intelligence','view_competitors',\n    'view_opportunities','view_recommendations','view_goals','view_alerts','use_ai_assistant'\n  ];\n\n  department_manager text[] := viewer || array[\n    'view_sales_data','view_operations_data','view_risks','view_data_sources',\n    'manage_goals','manage_alerts','generate_reports'\n  ];\n\n  branch_manager text[] := department_manager || array[\n    'view_financial_data','manage_opportunities','manage_recommendations','manage_risks','import_data'\n  ];\n\n  regional_manager text[] := branch_manager || array[\n    'assign_opportunities','view_audit_log'\n  ];\n\n  analyst text[] := array[\n    'view_performance','view_financial_data','view_sales_data','view_operations_data',\n    'view_intelligence','view_market_intelligence','view_competitors','view_opportunities',\n    'view_recommendations','view_goals','view_risks','view_alerts','view_data_sources',\n    'import_data','manage_metrics','generate_reports','use_ai_assistant'\n  ];\n\n  -- The executive view is the whole business, minus the plumbing that\n  -- administrators and analysts own.\n  executive text[] := regional_manager || array[\n    'manage_competitors','manage_radar','manage_users'\n  ];\nbegin\n  insert into public.role_permissions (role, permission_key)\n  select 'super_admin'::public.org_role, unnest(everything)\n  union all select 'org_admin', unnest(everything)\n  union all select 'executive', unnest(executive)\n  union all select 'regional_manager', unnest(regional_manager)\n  union all select 'branch_manager', unnest(branch_manager)\n  union all select 'department_manager', unnest(department_manager)\n  union all select 'analyst', unnest(analyst)\n  union all select 'viewer', unnest(viewer)\n  on conflict do nothing;\nend;\n$$;\n\n-- Protection restored before anything else runs.\nalter table public.permissions      force row level security;\nalter table public.role_permissions force row level security;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Triggers\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate or replace function amryn.touch_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$$;\n\ndo $$\ndeclare\n  t text;\nbegin\n  foreach t in array array[\n    'organisations','user_profiles','regions','branches','departments',\n    'organisation_members','subscriptions','data_sources','data_connections',\n    'business_metrics','competitors','opportunities','goals',\n    'strategic_initiatives','ai_recommendations','risks','ai_conversations'\n  ]\n  loop\n    execute format(\n      'create trigger %I before update on public.%I for each row execute function amryn.touch_updated_at()',\n      t || '_touch', t\n    );\n  end loop;\nend;\n$$;\n\n-- Mirror new auth users into user_profiles so the app always has a profile to\n-- render, without a first-login write path that could fail.\ncreate or replace function amryn.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  insert into public.user_profiles (id, email, full_name, avatar_url)\n  values (\n    new.id,\n    new.email,\n    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),\n    new.raw_user_meta_data ->> 'avatar_url'\n  )\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.user_profiles.full_name, excluded.full_name);\n  return new;\nend;\n$$;\n\n-- Guarded, because creating a trigger requires owning the table and on a\n-- hosted Supabase project auth.users belongs to supabase_auth_admin rather\n-- than the role applying this file. Unguarded, this one statement failed the\n-- entire migration — taking the permission catalogue, the role matrix and\n-- create_organisation down with it, and leaving a database that looked like\n-- the migrations had never run.\n--\n-- Where the trigger cannot be installed, public.ensure_user_profile() in\n-- migration 10 does the same work on first sign-in instead.\ndo $$\nbegin\n  create trigger on_auth_user_created\n    after insert on auth.users\n    for each row execute function amryn.handle_new_user();\nexception\n  when insufficient_privilege then\n    raise notice 'not permitted to add a trigger to auth.users; profiles are created on first sign-in instead';\n  when duplicate_object then\n    raise notice 'profile trigger already present';\nend;\n$$;\n\n-- Risk severity is derived from likelihood × impact, but stored, so that a\n-- later change to the scale does not silently rewrite history.\ncreate or replace function amryn.derive_risk_severity()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  product integer := new.likelihood * new.impact;\nbegin\n  new.severity := case\n    when product >= 20 then 'critical'::public.priority_level\n    when product >= 12 then 'high'::public.priority_level\n    when product >= 6  then 'medium'::public.priority_level\n    else 'low'::public.priority_level\n  end;\n  return new;\nend;\n$$;\n\ncreate trigger risks_derive_severity\n  before insert or update of likelihood, impact on public.risks\n  for each row execute function amryn.derive_risk_severity();\n\n-- ── organisation bootstrap ────────────────────────────────────────────────\n-- Creating an organisation from the app is a single call: it must also create\n-- the caller's membership, the subscription and the default weighting, or none\n-- of it. SECURITY DEFINER because the caller is not yet a member of the\n-- organisation whose rows are being written.\n\ncreate or replace function public.create_organisation(\n  p_name text,\n  p_slug text,\n  p_industry text default null,\n  p_country_code char(2) default 'ZA',\n  p_currency_code char(3) default 'ZAR'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  new_org uuid;\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  insert into public.organisations (name, slug, industry, country_code, currency_code)\n  values (p_name, lower(p_slug), p_industry, upper(p_country_code), upper(p_currency_code))\n  returning id into new_org;\n\n  insert into public.organisation_members (organisation_id, user_id, role, status, scope_kind)\n  values (new_org, uid, 'org_admin', 'active', 'organisation');\n\n  insert into public.subscriptions (organisation_id, plan, status, trial_ends_at)\n  values (new_org, 'starter', 'trialing', now() + interval '30 days');\n\n  insert into public.health_score_weights (organisation_id, category, weight) values\n    (new_org, 'financial',   0.25),\n    (new_org, 'operational', 0.20),\n    (new_org, 'sales',       0.20),\n    (new_org, 'growth',      0.15),\n    (new_org, 'customer',    0.10),\n    (new_org, 'strategic',   0.10);\n\n  insert into public.opportunity_score_weights (organisation_id) values (new_org);\n\n  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values (new_org, uid, 'organisation.created', 'organisation', new_org::text, p_name);\n\n  return new_org;\nend;\n$$;\n\nrevoke all on function public.create_organisation(text, text, text, char, char) from public, anon;\ngrant execute on function public.create_organisation(text, text, text, char, char) to authenticated;\n\n-- Health-score weights must sum to 1 for the score to be a true weighted mean.\ncreate or replace function amryn.assert_health_weights_sum()\nreturns trigger\nlanguage plpgsql\nas $$\ndeclare\n  total numeric;\n  org uuid := coalesce(new.organisation_id, old.organisation_id);\nbegin\n  select sum(weight) into total\n    from public.health_score_weights\n   where organisation_id = org;\n\n  if total is not null and abs(total - 1) > 0.001 then\n    raise exception 'health score weights for organisation % sum to %, expected 1', org, total;\n  end if;\n  return null;\nend;\n$$;\n\ncreate constraint trigger health_weights_sum_to_one\n  after insert or update or delete on public.health_score_weights\n  deferrable initially deferred\n  for each row execute function amryn.assert_health_weights_sum();\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260830080000_07_sector_policy.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260830080000_07_sector_policy.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 07 — Sector policy belongs to the customer, not to the platform\n--\n-- Migration 03 defaulted market scanning to the private sector alone and the\n-- recommendation layer refused to surface tenders at all. That conflated two\n-- different things:\n--\n--   · Amryn's own commercial posture — the company does not take on\n--     government-sector business. That is a fact about who Amryn sells to,\n--     and it belongs in the company's positioning, not in a WHERE clause.\n--\n--   · What an Amryn customer should be shown. Customers are private\n--     businesses, and a municipal supply tender is ordinary revenue to a\n--     wholesaler. Filtering it out withheld real money from the people\n--     paying for the product.\n--\n-- So sector scope becomes an explicit, per-organisation setting. The default\n-- is to surface everything and let relevance and strategic alignment decide\n-- what ranks — which is what those factors are for. An organisation that does\n-- not pursue public-sector work narrows the setting once, and the radar\n-- honours it everywhere.\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- A tender is its own kind of opportunity: a defined scope, a published\n-- deadline and a competitive submission. Modelling it as 'market_expansion'\n-- lost the shape that makes it actionable.\nalter type public.opportunity_kind add value if not exists 'tender';\n\n-- ── per-organisation sector scope ─────────────────────────────────────────\n-- Which sectors this organisation wants its radar to surface. Defaults to all\n-- of them: an opportunity is filtered out only because a customer chose to\n-- filter it, never because the platform decided on their behalf.\n\nalter table public.organisations\n  add column if not exists sector_scope public.market_sector[]\n    not null default '{private,public,mixed,unknown}';\n\ncomment on column public.organisations.sector_scope is\n  'Sectors the AI OpportunityRadar® may surface for this organisation. Set by the customer. Amryn''s own commercial posture is not encoded here.';\n\nalter table public.organisations\n  add constraint sector_scope_not_empty check (cardinality(sector_scope) > 0);\n\n-- Existing market sources were seeded private-only by the previous default.\n-- Widen them to match the new posture; a customer narrows from here.\nalter table public.market_sources\n  alter column sector_policy set default '{private,public,mixed,unknown}';\n\nupdate public.market_sources\n   set sector_policy = '{private,public,mixed,unknown}'\n where sector_policy = '{private}';\n\n-- ── honouring the setting ─────────────────────────────────────────────────\n-- Enforced in the database rather than only in the query layer, so a report,\n-- an export and the assistant all see the same set. A row outside the\n-- organisation's chosen scope is simply not selectable.\n\ncreate or replace function amryn.sector_in_scope(p_org uuid, p_sector public.market_sector)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(\n    (select p_sector = any (o.sector_scope) from public.organisations o where o.id = p_org),\n    false\n  );\n$$;\n\ngrant execute on function amryn.sector_in_scope(uuid, public.market_sector) to authenticated;\n\ndrop policy if exists opportunities_read on public.opportunities;\ncreate policy opportunities_read on public.opportunities\n  for select to authenticated\n  using (\n    amryn.has_permission(organisation_id, 'view_opportunities')\n    and amryn.can_see_branch(organisation_id, branch_id)\n    and amryn.sector_in_scope(organisation_id, sector)\n  );\n\ndrop policy if exists market_signals_read on public.market_signals;\ncreate policy market_signals_read on public.market_signals\n  for select to authenticated\n  using (\n    amryn.has_permission(organisation_id, 'view_market_intelligence')\n    and amryn.sector_in_scope(organisation_id, sector)\n  );\n\n-- PostgREST answers from a cached copy of the schema and is not told by\n-- applying SQL. Without this, everything above exists and stays invisible to\n-- the application — which reads exactly like a migration that never ran.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260830190000_08_organisation_bootstrap_rpc.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260830190000_08_organisation_bootstrap_rpc.sql'; end $setup$;\n\n-- ── organisation bootstrap, made reachable ────────────────────────────────\n--\n-- Symptom this fixes, seen on the live deployment at /onboarding:\n--\n--   Could not find the function public.create_organisation(p_country_code,\n--   p_currency_code, p_industry, p_name, p_slug) in the schema cache\n--\n-- PostgREST resolves a remote call against a cache of the schema, not against\n-- the schema. Three separate things produce that one message, and the reader\n-- cannot tell them apart:\n--\n--   1. The function is genuinely absent — migration 06 was never applied.\n--   2. It exists, but PostgREST last built its cache before it did. Applying\n--      migrations through the SQL editor does not reload that cache, so a\n--      correct database serves a stale answer indefinitely.\n--   3. It exists, but the caller's arguments cannot be coerced to its\n--      parameter types, so no candidate matches.\n--\n-- This migration settles all three, and is safe to run whether or not 06 was.\n--\n-- On (3): the parameters were char(2) and char(3). A blank-padded fixed-width\n-- type is a poor thing to expose over an interface that sends everything as\n-- JSON text, and it buys nothing here — the columns are still char(2)/char(3)\n-- with their own check constraints, so the storage guarantee is unchanged.\n-- The parameters become text, and the function validates them itself so a bad\n-- value is a sentence rather than a silent truncation.\n--\n-- A type change cannot be made with `create or replace`: Postgres treats a\n-- different parameter type as a different function and would leave both in\n-- place. Two candidates with identical argument names is worse than none —\n-- PostgREST then fails as ambiguous. So both signatures are dropped first.\n\ndrop function if exists public.create_organisation(text, text, text, char, char);\ndrop function if exists public.create_organisation(text, text, text, text, text);\n\ncreate function public.create_organisation(\n  p_name text,\n  p_slug text,\n  p_industry text default null,\n  p_country_code text default 'ZA',\n  p_currency_code text default 'ZAR'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\n-- SECURITY DEFINER because the caller is not yet a member of the organisation\n-- whose rows are being written. search_path is pinned so the elevated body\n-- cannot be redirected to a caller-controlled schema.\nset search_path = public, pg_temp\nas $$\ndeclare\n  new_org  uuid;\n  uid      uuid := auth.uid();\n  country  text := upper(btrim(coalesce(p_country_code, 'ZA')));\n  currency text := upper(btrim(coalesce(p_currency_code, 'ZAR')));\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  -- Validated here rather than left to the column cast. char(2) silently\n  -- truncates anything longer, so 'ZAF' would have been stored as 'ZA' and\n  -- nobody would have been told.\n  if length(country) <> 2 then\n    raise exception 'country code must be two letters, got %', country\n      using errcode = '22023';\n  end if;\n\n  if length(currency) <> 3 then\n    raise exception 'currency code must be three letters, got %', currency\n      using errcode = '22023';\n  end if;\n\n  insert into public.organisations (name, slug, industry, country_code, currency_code)\n  values (p_name, lower(p_slug), p_industry, country, currency)\n  returning id into new_org;\n\n  insert into public.organisation_members (organisation_id, user_id, role, status, scope_kind)\n  values (new_org, uid, 'org_admin', 'active', 'organisation');\n\n  insert into public.subscriptions (organisation_id, plan, status, trial_ends_at)\n  values (new_org, 'starter', 'trialing', now() + interval '30 days');\n\n  insert into public.health_score_weights (organisation_id, category, weight) values\n    (new_org, 'financial',   0.25),\n    (new_org, 'operational', 0.20),\n    (new_org, 'sales',       0.20),\n    (new_org, 'growth',      0.15),\n    (new_org, 'customer',    0.10),\n    (new_org, 'strategic',   0.10);\n\n  insert into public.opportunity_score_weights (organisation_id) values (new_org);\n\n  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values (new_org, uid, 'organisation.created', 'organisation', new_org::text, p_name);\n\n  return new_org;\nend;\n$$;\n\n-- anon must never reach this: it writes an organisation and an admin\n-- membership, and it runs as its owner.\nrevoke all on function public.create_organisation(text, text, text, text, text) from public, anon;\ngrant execute on function public.create_organisation(text, text, text, text, text) to authenticated;\n\n-- Cause (2). Without this the function above exists and stays invisible over\n-- the API until something else happens to reload the cache.\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260830200000_09_default_privileges.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260830200000_09_default_privileges.sql'; end $setup$;\n\n-- ── privileges for tables added later ─────────────────────────────────────\n--\n-- Migration 05 grants `authenticated` its table privileges with\n-- `grant ... on all tables in schema public`. That phrasing is a snapshot: it\n-- covers the tables existing at the moment it runs, and says nothing about any\n-- added afterwards. A table created by a future migration would therefore be\n-- unreachable by every signed-in user, and PostgREST would report it as\n-- missing from the schema cache rather than as a privilege problem — which is\n-- a long way from the cause.\n--\n-- Default privileges close that, so the grant applies to what does not exist\n-- yet.\n--\n-- Deliberately nothing for `anon`. It holds no privilege on these tables and\n-- should not: every one of the 45 policies targets `authenticated`, so Row\n-- Level Security alone would already return an anonymous caller nothing, and\n-- withholding the grant as well means a policy misconfigured tomorrow still\n-- cannot leak to an anonymous request. 10_rls_isolation_test.sql asserts that\n-- second wall is standing.\n\nalter default privileges in schema public\n  grant select, insert, update, delete on tables to authenticated;\n\nalter default privileges in schema public\n  grant usage, select on sequences to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260830210000_10_profile_without_auth_trigger.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260830210000_10_profile_without_auth_trigger.sql'; end $setup$;\n\n-- ── surviving a trigger that cannot be created ────────────────────────────\n--\n-- Migration 06 ends with:\n--\n--   create trigger on_auth_user_created after insert on auth.users ...\n--\n-- Creating a trigger requires ownership of the table, and on a hosted Supabase\n-- project auth.users belongs to supabase_auth_admin, not to the role the SQL\n-- editor runs as. Whether that succeeds depends on the vintage of the project;\n-- on the ones where it does not, it fails with\n--\n--   ERROR: 42501: must be owner of relation users\n--\n-- and because the editor runs each script in a transaction, the whole of\n-- migration 06 rolls back — the permission catalogue, the role matrix and\n-- create_organisation with it. The database is then left with every table and\n-- policy in place and none of its seed data, which reads exactly like\n-- migrations that were never applied.\n--\n-- A local PostgreSQL owns everything, so the suite never saw it.\n--\n-- Rather than depend on knowing which kind of project this is, the trigger\n-- becomes optional and its work is made reachable another way.\n\n-- 1. Never let this be the statement that fails a migration.\ndo $$\nbegin\n  create trigger on_auth_user_created\n    after insert on auth.users\n    for each row execute function amryn.handle_new_user();\n  raise notice 'profile trigger installed on auth.users';\nexception\n  when insufficient_privilege then\n    raise notice 'not permitted to add a trigger to auth.users on this project; profiles are created on first sign-in instead';\n  when duplicate_object then\n    raise notice 'profile trigger already present';\nend;\n$$;\n\n-- 2. The first-login write path the trigger existed to avoid needing.\n--\n-- SECURITY DEFINER so it can read auth.users, which the caller cannot. It acts\n-- only on auth.uid(), so a caller can create a profile for themselves and for\n-- nobody else — there is no parameter to point at another user.\ncreate or replace function public.ensure_user_profile()\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    return;\n  end if;\n\n  insert into public.user_profiles (id, email, full_name, avatar_url)\n  select\n    u.id,\n    u.email,\n    coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),\n    u.raw_user_meta_data ->> 'avatar_url'\n  from auth.users u\n  where u.id = uid\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.user_profiles.full_name, excluded.full_name);\nend;\n$$;\n\nrevoke all on function public.ensure_user_profile() from public, anon;\ngrant execute on function public.ensure_user_profile() to authenticated;\n\n-- 3. Anyone who signed up while the trigger was absent has no profile. Backfill\n-- them, so this migration repairs the accounts it was too late to prevent.\ninsert into public.user_profiles (id, email, full_name, avatar_url)\nselect\n  u.id,\n  u.email,\n  coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),\n  u.raw_user_meta_data ->> 'avatar_url'\nfrom auth.users u\non conflict (id) do nothing;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831090000_11_invitations.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831090000_11_invitations.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 11 — Invitations\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Until now every person who signed up got an organisation of their own, and\n-- there was no way into anyone else's. The members screen already rendered an\n-- `invited` status and nothing ever wrote one.\n--\n-- The obvious implementation does not work: organisation_members.user_id\n-- references auth.users and is not null, so a membership cannot exist for\n-- somebody who has not signed up yet — which is exactly who an invitation is\n-- for. So an invitation is its own record, and becomes a membership when it is\n-- accepted.\n--\n-- The link is the credential, so it is treated as one. Only a SHA-256 hash of\n-- the token is stored: the database never holds anything that grants access,\n-- and a leaked backup does not let anyone in. The raw token exists once, in the\n-- response that creates it, and is shown to the person who will send it on.\n\ncreate table public.organisation_invitations (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  -- citext, so an invitation to Someone@Example.com is accepted by\n  -- someone@example.com. Case-sensitivity here would be a support burden and\n  -- protects nothing.\n  email           citext not null,\n  role            public.org_role not null default 'viewer',\n  scope_kind      public.scope_kind not null default 'organisation',\n  scope_ids       uuid[] not null default '{}',\n  -- Never the token itself.\n  token_hash      text not null unique,\n  invited_by      uuid references auth.users (id) on delete set null,\n  expires_at      timestamptz not null default now() + interval '14 days',\n  accepted_at     timestamptz,\n  accepted_by     uuid references auth.users (id) on delete set null,\n  revoked_at      timestamptz,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  constraint scope_ids_match_kind check (\n    (scope_kind = 'organisation' and cardinality(scope_ids) = 0)\n    or (scope_kind <> 'organisation' and cardinality(scope_ids) > 0)\n  ),\n  -- An invitation is either open, accepted or revoked. Recording both an\n  -- acceptance and a revocation would leave no answer to \"did they get in\".\n  constraint not_both_accepted_and_revoked check (\n    accepted_at is null or revoked_at is null\n  )\n);\n\n-- One open invitation per address per organisation. A partial index rather than\n-- a plain unique constraint, so the same person can be re-invited after an\n-- invitation is revoked or expires.\ncreate unique index organisation_invitations_open_email\n  on public.organisation_invitations (organisation_id, email)\n  where accepted_at is null and revoked_at is null;\n\ncreate index organisation_invitations_org on public.organisation_invitations (organisation_id);\n\ncreate trigger organisation_invitations_touch\n  before update on public.organisation_invitations\n  for each row execute function amryn.touch_updated_at();\n\n-- ── who may see and write them ────────────────────────────────────────────\nalter table public.organisation_invitations enable row level security;\nalter table public.organisation_invitations force row level security;\n\n-- Reading an invitation reveals who is being brought into the business, so it\n-- is limited to the people who manage members — not every colleague.\ncreate policy organisation_invitations_read on public.organisation_invitations\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_users'));\n\ncreate policy organisation_invitations_write on public.organisation_invitations\n  for insert to authenticated\n  with check (amryn.has_permission(organisation_id, 'manage_users'));\n\n-- Update covers revoking. Acceptance does not come through here: the invitee\n-- is not a member yet and no policy would let them touch the row, which is why\n-- accept_invitation() runs as its owner.\ncreate policy organisation_invitations_update on public.organisation_invitations\n  for update to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_users'))\n  with check (amryn.has_permission(organisation_id, 'manage_users'));\n\ngrant select, insert, update on public.organisation_invitations to authenticated;\n\n-- ── looking at an invitation before accepting it ──────────────────────────\n--\n-- The invitee cannot read the row — they are not a member of anything yet — so\n-- this reads it for them and returns only what the page needs to say: which\n-- organisation, which role, and whether the link is still good. Not who else\n-- is invited, and not the token.\n--\n-- Takes the raw token, so possession of the link is the whole authorisation.\ncreate or replace function public.invitation_preview(p_token text)\nreturns table (\n  organisation_name text,\n  role              public.org_role,\n  email             text,\n  state             text\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  hashed text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');\n  -- Not named `found`: that is PL/pgSQL's own boolean, and shadowing it makes\n  -- `if not found` a type error rather than the check it looks like.\n  invite record;\nbegin\n  select i.*, o.name as org_name\n    into invite\n    from public.organisation_invitations i\n    join public.organisations o on o.id = i.organisation_id\n   where i.token_hash = hashed;\n\n  if invite.id is null then\n    -- Deliberately indistinguishable from an expired one on the caller's side:\n    -- a separate \"no such invitation\" would make this a way to test tokens.\n    return query select null::text, null::public.org_role, null::text, 'invalid'::text;\n    return;\n  end if;\n\n  return query select\n    invite.org_name::text,\n    invite.role,\n    invite.email::text,\n    case\n      when invite.revoked_at is not null then 'revoked'\n      when invite.accepted_at is not null then 'accepted'\n      when invite.expires_at <= now() then 'expired'\n      else 'open'\n    end;\nend;\n$$;\n\nrevoke all on function public.invitation_preview(text) from public;\n-- anon may call it: someone following an invitation link has usually not\n-- signed in yet, and being told what they are being invited to is the point.\ngrant execute on function public.invitation_preview(text) to anon, authenticated;\n\n-- ── accepting ─────────────────────────────────────────────────────────────\n--\n-- SECURITY DEFINER because the caller is, by definition, not yet a member of\n-- the organisation whose membership row is about to be written — the same\n-- reason create_organisation() runs this way.\n--\n-- The membership is created with the role and scope recorded on the\n-- invitation, never with anything the caller sends. There is no parameter here\n-- but the token.\ncreate or replace function public.accept_invitation(p_token text)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid        uuid := auth.uid();\n  user_email citext;\n  invite     public.organisation_invitations;\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  select u.email into user_email from auth.users u where u.id = uid;\n\n  select * into invite\n    from public.organisation_invitations\n   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')\n     for update;\n\n  if not found then\n    raise exception 'this invitation link is not valid' using errcode = '22023';\n  end if;\n\n  if invite.revoked_at is not null then\n    raise exception 'this invitation has been withdrawn' using errcode = '22023';\n  end if;\n\n  if invite.expires_at <= now() then\n    raise exception 'this invitation has expired' using errcode = '22023';\n  end if;\n\n  -- Bound to the address it was sent to. Holding the link is not enough:\n  -- a forwarded invitation would otherwise hand a stranger access to the\n  -- company's data under someone else's name.\n  if user_email is null or user_email <> invite.email then\n    raise exception 'this invitation was sent to a different email address'\n      using errcode = '42501';\n  end if;\n\n  -- Already accepted is only an error if somebody else accepted it. For the\n  -- same person it is a repeated click, and the answer is where they were\n  -- going anyway.\n  if invite.accepted_at is not null then\n    if invite.accepted_by = uid then\n      return invite.organisation_id;\n    end if;\n    raise exception 'this invitation has already been used' using errcode = '22023';\n  end if;\n\n  insert into public.organisation_members\n    (organisation_id, user_id, role, status, scope_kind, scope_ids, invited_by, invited_at)\n  values\n    (invite.organisation_id, uid, invite.role, 'active', invite.scope_kind,\n     invite.scope_ids, invite.invited_by, invite.created_at)\n  on conflict (organisation_id, user_id) do update\n    set status = 'active';\n\n  update public.organisation_invitations\n     set accepted_at = now(), accepted_by = uid\n   where id = invite.id;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values\n    (invite.organisation_id, uid, 'member.joined', 'organisation_member', uid::text,\n     invite.email || ' accepted an invitation as ' || invite.role);\n\n  return invite.organisation_id;\nend;\n$$;\n\nrevoke all on function public.accept_invitation(text) from public, anon;\ngrant execute on function public.accept_invitation(text) to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831120000_12_rate_limits.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831120000_12_rate_limits.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 12 — Rate limiting\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Sign-in, sign-up, organisation creation and invitations had no limit on how\n-- often they could be attempted. That is a credential-stuffing surface on the\n-- first two and, on the last, a way for one administrator to issue unbounded\n-- invitations.\n--\n-- In the database rather than in memory, because the application runs as\n-- serverless functions: an in-memory counter is per-instance, resets whenever\n-- one is recycled, and counts nothing at all once there is more than one.\n--\n-- ── what is stored ────────────────────────────────────────────────────────\n-- Only a hash. The thing being limited is an email address or an IP address,\n-- and both are personal information under POPIA — keeping either in readable\n-- form would mean a table of who tried to sign in and from where, retained for\n-- no purpose the person consented to. A SHA-256 of the identifier answers\n-- \"has this one been seen too often\" without recording whose it is.\n\ncreate table public.rate_limits (\n  -- The hash is the identity of the bucket; there is nothing else to key on.\n  bucket      text primary key,\n  attempts    integer not null default 0,\n  -- When the current window began. A window is a fixed period from the first\n  -- attempt, not a sliding one: simpler to reason about, and the difference\n  -- does not matter at the resolution of a login form.\n  window_start timestamptz not null default now(),\n  updated_at   timestamptz not null default now()\n);\n\ncreate index rate_limits_window_start on public.rate_limits (window_start);\n\n-- Locked down completely. Nothing reads or writes this except the function\n-- below, which runs as its owner: the counts are not the application's\n-- business, and a client that could read them could enumerate activity.\nalter table public.rate_limits enable row level security;\nalter table public.rate_limits force row level security;\nrevoke all on public.rate_limits from public, anon, authenticated;\n\n-- ── the check ─────────────────────────────────────────────────────────────\n--\n-- Returns true when the attempt is allowed. Atomic: the insert-on-conflict is\n-- a single statement, so two requests arriving together cannot both read a\n-- count of four and both decide they are the fifth.\n--\n-- Callable by anon, because sign-in and sign-up are attempted before anyone is\n-- authenticated. It takes an already-hashed key, so the raw address never\n-- travels to the database and never appears in a query log.\ncreate or replace function public.check_rate_limit(\n  p_bucket   text,\n  p_max      integer,\n  p_window   interval\n)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  current_attempts integer;\nbegin\n  if p_bucket is null or length(p_bucket) = 0 then\n    -- Nothing to key on. Allowing it is the right failure: a rate limiter that\n    -- refuses when it cannot identify the caller locks everyone out.\n    return true;\n  end if;\n\n  insert into public.rate_limits (bucket, attempts, window_start, updated_at)\n  values (p_bucket, 1, now(), now())\n  on conflict (bucket) do update\n    set\n      -- Past the window, the count starts again rather than accumulating\n      -- forever.\n      attempts = case\n        when public.rate_limits.window_start < now() - p_window then 1\n        else public.rate_limits.attempts + 1\n      end,\n      window_start = case\n        when public.rate_limits.window_start < now() - p_window then now()\n        else public.rate_limits.window_start\n      end,\n      updated_at = now()\n  returning attempts into current_attempts;\n\n  return current_attempts <= p_max;\nend;\n$$;\n\nrevoke all on function public.check_rate_limit(text, integer, interval) from public;\ngrant execute on function public.check_rate_limit(text, integer, interval) to anon, authenticated;\n\n-- ── housekeeping ──────────────────────────────────────────────────────────\n--\n-- Rows outlive their usefulness the moment their window closes. Keeping them\n-- would turn a counter into a log of attempts, which is the thing this table\n-- was designed not to be.\ncreate or replace function public.prune_rate_limits()\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  removed integer;\nbegin\n  delete from public.rate_limits where window_start < now() - interval '1 day';\n  get diagnostics removed = row_count;\n  return removed;\nend;\n$$;\n\nrevoke all on function public.prune_rate_limits() from public, anon, authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831140000_13_consent_and_data_rights.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831140000_13_consent_and_data_rights.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 13 — Consent, and the right to ask what is held\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- POPIA (Act 4 of 2013) requires that processing rest on a lawful basis, that\n-- the data subject be able to establish what is held about them, and that they\n-- can ask for it to be corrected or destroyed. Two things follow that the\n-- schema did not have.\n--\n-- ── consent, with a date ──────────────────────────────────────────────────\n-- \"They accepted the terms\" is not a fact unless it is written down. The\n-- version matters as much as the timestamp: terms change, and consent to one\n-- wording is not consent to a later one, so both are recorded and a change of\n-- version is visible as an absence rather than assumed away.\n\nalter table public.user_profiles\n  add column terms_accepted_at timestamptz,\n  add column terms_version     text,\n  add column privacy_accepted_at timestamptz,\n  add column privacy_version   text;\n\ncomment on column public.user_profiles.terms_accepted_at is\n  'When this person accepted the terms of service. Null means they have not.';\ncomment on column public.user_profiles.terms_version is\n  'Which wording they accepted. Consent to one version is not consent to the next.';\n\n-- An organisation is a separate consenting party: its administrator agrees to\n-- the data processing addendum on the organisation''s behalf, which is a\n-- different act from that person accepting the terms as an individual.\nalter table public.organisations\n  add column dpa_accepted_at timestamptz,\n  add column dpa_version     text,\n  add column dpa_accepted_by uuid references auth.users (id) on delete set null;\n\ncomment on column public.organisations.dpa_accepted_at is\n  'When an administrator accepted the data processing addendum for this organisation.';\n\n-- ── the right to ask ──────────────────────────────────────────────────────\n--\n-- A request is recorded rather than acted on immediately. Export and erasure\n-- both need judgement — an organisation''s records are not one member''s to\n-- delete, and a request from an administrator may implicate colleagues — so\n-- this creates an auditable obligation with a clock on it, which is what the\n-- Act actually asks for.\n\ncreate type public.data_request_kind as enum ('export', 'deletion', 'correction');\ncreate type public.data_request_status as enum ('received', 'in_progress', 'completed', 'refused');\n\ncreate table public.data_requests (\n  id             uuid primary key default gen_random_uuid(),\n  user_id        uuid not null references auth.users (id) on delete cascade,\n  kind           public.data_request_kind not null,\n  status         public.data_request_status not null default 'received',\n  -- What the person said, in their words. Useful for a correction request,\n  -- where the substance is the point.\n  note           text check (note is null or length(note) <= 2000),\n  -- What was done, for the audit trail. Never shown to the requester as-is.\n  resolution     text,\n  requested_at   timestamptz not null default now(),\n  responded_at   timestamptz,\n  created_at     timestamptz not null default now(),\n  updated_at     timestamptz not null default now()\n);\n\ncreate index data_requests_user on public.data_requests (user_id);\ncreate index data_requests_open on public.data_requests (status) where status in ('received', 'in_progress');\n\ncreate trigger data_requests_touch\n  before update on public.data_requests\n  for each row execute function amryn.touch_updated_at();\n\nalter table public.data_requests enable row level security;\nalter table public.data_requests force row level security;\n\n-- A person may see and make their own requests, and nobody else''s. There is\n-- deliberately no policy letting an organisation administrator read these: a\n-- request to exercise a personal right is between the individual and the\n-- responsible party, and an employer reading it would chill the exercise of it.\ncreate policy data_requests_read_own on public.data_requests\n  for select to authenticated\n  using (user_id = auth.uid());\n\ncreate policy data_requests_create_own on public.data_requests\n  for insert to authenticated\n  with check (user_id = auth.uid());\n\n-- No update or delete policy at all. A request cannot be withdrawn by editing\n-- it away, and its status is set by whoever handles it, outside this interface.\n\ngrant select, insert on public.data_requests to authenticated;\n\n-- ── carrying consent through sign-up ──────────────────────────────────────\n--\n-- Consent is given on the sign-up form, but the profile row it belongs on may\n-- not exist yet: where the project confirms addresses by email, the account is\n-- created and the person disappears into their inbox for a while, and where\n-- the trigger below could not be installed the profile is not written until\n-- their first sign-in. Recording the acceptance in the account's own metadata\n-- at the moment it is given, and copying it onto the profile whichever path\n-- creates that profile, is what makes the record survive both gaps.\n--\n-- Both writers use coalesce on the existing timestamp, so a later acceptance\n-- of a newer version is never overwritten by the one captured at sign-up.\n\ncreate or replace function amryn.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  insert into public.user_profiles (\n    id, email, full_name, avatar_url,\n    terms_accepted_at, terms_version, privacy_accepted_at, privacy_version\n  )\n  values (\n    new.id,\n    new.email,\n    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),\n    new.raw_user_meta_data ->> 'avatar_url',\n    (new.raw_user_meta_data ->> 'terms_accepted_at')::timestamptz,\n    new.raw_user_meta_data ->> 'terms_version',\n    (new.raw_user_meta_data ->> 'privacy_accepted_at')::timestamptz,\n    new.raw_user_meta_data ->> 'privacy_version'\n  )\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.user_profiles.full_name, excluded.full_name),\n        terms_accepted_at = coalesce(public.user_profiles.terms_accepted_at, excluded.terms_accepted_at),\n        terms_version = coalesce(public.user_profiles.terms_version, excluded.terms_version),\n        privacy_accepted_at = coalesce(public.user_profiles.privacy_accepted_at, excluded.privacy_accepted_at),\n        privacy_version = coalesce(public.user_profiles.privacy_version, excluded.privacy_version);\n  return new;\nend;\n$$;\n\ncreate or replace function public.ensure_user_profile()\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    return;\n  end if;\n\n  insert into public.user_profiles (\n    id, email, full_name, avatar_url,\n    terms_accepted_at, terms_version, privacy_accepted_at, privacy_version\n  )\n  select\n    u.id,\n    u.email,\n    coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),\n    u.raw_user_meta_data ->> 'avatar_url',\n    (u.raw_user_meta_data ->> 'terms_accepted_at')::timestamptz,\n    u.raw_user_meta_data ->> 'terms_version',\n    (u.raw_user_meta_data ->> 'privacy_accepted_at')::timestamptz,\n    u.raw_user_meta_data ->> 'privacy_version'\n  from auth.users u\n  where u.id = uid\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.user_profiles.full_name, excluded.full_name),\n        terms_accepted_at = coalesce(public.user_profiles.terms_accepted_at, excluded.terms_accepted_at),\n        terms_version = coalesce(public.user_profiles.terms_version, excluded.terms_version),\n        privacy_accepted_at = coalesce(public.user_profiles.privacy_accepted_at, excluded.privacy_accepted_at),\n        privacy_version = coalesce(public.user_profiles.privacy_version, excluded.privacy_version);\nend;\n$$;\n\nrevoke all on function public.ensure_user_profile() from public, anon;\ngrant execute on function public.ensure_user_profile() to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831160000_14_security_events.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831160000_14_security_events.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 14 — Security events that can be trusted\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- audit_logs has existed since migration 01 and had one writer: a change of\n-- radar sector scope. Everything a security log exists for — who signed in,\n-- who was invited, who joined, who took a copy of their own information — went\n-- unrecorded, which made the privacy policy's promise that \"sign-ins and\n-- organisation changes are recorded\" a sentence about something that was not\n-- happening.\n--\n-- ── and the writes it did allow were not evidence ─────────────────────────\n-- The insert policy was:\n--\n--   with check (organisation_id is null or amryn.is_member(organisation_id))\n--\n-- Any member could write any row: an action of their choosing, a summary of\n-- their choosing, and — because actor_id was supplied by the caller — somebody\n-- else's name on it. A log a subject can forge is not an audit log; it is a\n-- table with an official-sounding name, and relying on it in an investigation\n-- would be worse than having none.\n--\n-- So the row is written by a function that decides the two fields that matter,\n-- and the direct insert is withdrawn.\n\ncreate or replace function public.record_security_event(\n  p_organisation_id uuid,\n  p_action          text,\n  p_entity_type     text default 'account',\n  p_entity_id       text default null,\n  p_summary         text default null,\n  p_metadata        jsonb default '{}'::jsonb\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid uuid := auth.uid();\nbegin\n  -- The actor is never taken from the caller. This is the whole point.\n  if p_organisation_id is not null and not amryn.is_member(p_organisation_id) then\n    raise exception 'not a member of that organisation' using errcode = '42501';\n  end if;\n\n  insert into public.audit_logs (\n    organisation_id, actor_id, action, entity_type, entity_id, summary, metadata\n  )\n  values (\n    p_organisation_id, uid, p_action, coalesce(p_entity_type, 'account'),\n    p_entity_id, p_summary, coalesce(p_metadata, '{}'::jsonb)\n  );\nend;\n$$;\n\ncomment on function public.record_security_event is\n  'The only way the application writes an audit row. Sets actor_id from the session, so an entry cannot be attributed to somebody else.';\n\nrevoke all on function public.record_security_event(uuid, text, text, text, text, jsonb)\n  from public, anon;\ngrant execute on function public.record_security_event(uuid, text, text, text, text, jsonb)\n  to authenticated;\n\n-- A sign-in has no organisation yet, and the person may belong to none. That\n-- row is ours as responsible party rather than any employer's, which is also\n-- why the read policy below leaves it invisible to organisation administrators.\ncreate or replace function public.record_account_event(\n  p_action  text,\n  p_summary text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, summary)\n  values (null, auth.uid(), p_action, 'account', p_summary);\nend;\n$$;\n\nrevoke all on function public.record_account_event(text, text) from public, anon;\n-- anon may call this one: a failed sign-in has no session, and a log that\n-- records only the attempts that succeeded is not a security log. The function\n-- writes auth.uid(), which is null in that case, so an anonymous caller cannot\n-- attribute an entry to anybody.\ngrant execute on function public.record_account_event(text, text) to authenticated, anon;\n\n-- ── withdraw the forgeable path ──────────────────────────────────────────\n--\n-- Two changes, and the second is the one that makes the first survivable.\n--\n-- Dropping the policy is what removes the forgeable write. But audit_logs\n-- carries FORCE row level security, which applies to the table's owner too —\n-- and with no insert policy left, \"everyone\" includes the owner. Every\n-- SECURITY DEFINER function that writes an audit row runs as that owner:\n-- the two below, and create_organisation(), whose last statement records\n-- 'organisation.created'. An error inside a function rolls the whole call\n-- back, so dropping the policy alone would have broken organisation creation\n-- outright — on the onboarding form, for every new customer.\n--\n-- On a local PostgreSQL this is invisible: there the owner is a superuser, and\n-- a superuser bypasses row level security whether or not it is forced. On a\n-- hosted Supabase project the postgres role is not a superuser, so it is\n-- subject to the policies like anyone else. This is the third time that\n-- difference has hidden a fault from the test suite; supabase/tests/17 now\n-- reproduces it deliberately.\n--\n-- Lifting FORCE is the correct answer rather than a workaround. What must be\n-- true of an append-only log is that the application cannot write to it\n-- directly and can only read its own organisation's rows — and both survive:\n-- the revoke below removes the write privilege from authenticated entirely,\n-- which is a stronger guarantee than a policy, and audit_read still governs\n-- every read, because a caller is never the owner. The only writers left are\n-- the definer functions, which is what \"the only way the application writes an\n-- audit row\" was meant to mean.\nalter table public.audit_logs no force row level security;\n\ndrop policy if exists audit_append on public.audit_logs;\nrevoke insert, update, delete on public.audit_logs from authenticated, anon;\n\n-- Reading is unchanged and deliberately narrow: an organisation administrator\n-- with view_audit_log sees their own organisation's entries. Account-level\n-- rows carry no organisation_id and so match no policy at all — nobody reads\n-- those through the API, which is correct for a record of an individual's\n-- sign-ins held by us rather than by their employer.\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260831180000_15_two_factor.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260831180000_15_two_factor.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 15 — Two-factor authentication\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Until now a stolen password was the whole attack. For a platform holding a\n-- company's financial records, customer list and pipeline, that is the largest\n-- single gap in the product.\n--\n-- Supabase issues and verifies the second factor itself, so none of the TOTP\n-- machinery lives here. What lives here is the part an application must not\n-- get wrong: making the requirement real.\n--\n-- ── why this is not only an application check ─────────────────────────────\n-- The obvious implementation is a redirect: if the session has not completed\n-- the challenge, send it to the verify page. That is worth doing and is not\n-- enough. Every browser session also carries a key that speaks to PostgREST\n-- directly, and a session that skipped the challenge is a perfectly valid\n-- session as far as the database is concerned — so anyone willing to use the\n-- API instead of the interface would read everything the redirect was hiding.\n-- A second factor that can be walked around with curl is a checkbox, not a\n-- control.\n--\n-- So the requirement is enforced where the data is. Supabase records the\n-- authenticator assurance level in the token as `aal`: aal1 is a password,\n-- aal2 is a password and a second factor. Every policy in this schema already\n-- reaches the caller through amryn.is_member() or amryn.has_permission(), so\n-- adding the condition to those two puts it in front of all 147 of them.\n\n-- ── who has it turned on ──────────────────────────────────────────────────\n--\n-- Kept here rather than read from auth.mfa_factors, which belongs to another\n-- role and may not be readable from this schema on every project. A guard that\n-- cannot read its own input has to choose between failing open — which is not\n-- a guard — and locking every customer out of their data over a missing grant.\n-- This is our own table, and the application writes it in the same action that\n-- verifies the factor.\nalter table public.user_profiles\n  add column mfa_enabled boolean not null default false,\n  add column mfa_enabled_at timestamptz;\n\ncomment on column public.user_profiles.mfa_enabled is\n  'Whether this person has a verified second factor. Set when enrolment is confirmed, cleared when the last factor is removed. The database refuses their data to a session that has not presented it.';\n\n-- ── the guard ─────────────────────────────────────────────────────────────\ncreate or replace function amryn.mfa_satisfied()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select\n    -- Presented the second factor on this session.\n    coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2'\n    -- Or has none to present. Someone who has not turned it on is not asked\n    -- for it, and neither is a background job, which carries no token at all:\n    -- auth.uid() is null there, the row is not found, and the answer is true.\n    or not exists (\n      select 1\n      from public.user_profiles p\n      where p.id = auth.uid()\n        and p.mfa_enabled\n    );\n$$;\n\ncomment on function amryn.mfa_satisfied is\n  'False only for a session belonging to someone with two-factor turned on that has not completed the second step. Used by is_member() and has_permission(), so it applies to every policy without repeating it in each.';\n\n-- ── applied to the two functions every policy goes through ────────────────\n--\n-- Deliberately not added to the policies one at a time. There are 147 of them;\n-- a condition repeated 147 times is a condition that will be missing from the\n-- 148th.\n\ncreate or replace function amryn.is_member(p_org uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select amryn.mfa_satisfied() and exists (\n    select 1\n    from public.organisation_members m\n    where m.organisation_id = p_org\n      and m.user_id = auth.uid()\n      and m.status = 'active'\n  );\n$$;\n\ncreate or replace function amryn.has_permission(p_org uuid, p_permission text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  with member as (\n    select m.id, m.role\n    from public.organisation_members m\n    where m.organisation_id = p_org\n      and m.user_id = auth.uid()\n      and m.status = 'active'\n    limit 1\n  ),\n  override as (\n    select o.granted\n    from public.member_permission_overrides o\n    join member on member.id = o.member_id\n    where o.permission_key = p_permission\n    limit 1\n  ),\n  role_default as (\n    select true as granted\n    from public.role_permissions rp\n    join member on member.role = rp.role\n    where rp.permission_key = p_permission\n    limit 1\n  )\n  select amryn.mfa_satisfied() and coalesce(\n    (select granted from override),\n    (select granted from role_default),\n    false\n  );\n$$;\n\n-- member_role() is deliberately left alone. It answers \"what is this person's\n-- role\", which the interface needs in order to render the page that explains\n-- they must complete the second step — and it returns a label, never data.\n\n-- ── recovery codes ────────────────────────────────────────────────────────\n--\n-- The failure mode of two-factor authentication is not an attacker; it is a\n-- lost phone. Without a way back, turning it on is a way to lose an account,\n-- and the people most likely to turn it on are the ones with the most to lose.\n--\n-- Ten single-use codes, stored as SHA-256 hashes for the same reason passwords\n-- are: a database that can produce the codes is a database that can bypass the\n-- factor. Redeeming one is not a sign-in — it removes the factor, and the\n-- person is asked to enrol again. So the two things needed to get back in are\n-- the password and a code, which is still two factors.\n\ncreate table public.mfa_recovery_codes (\n  id         uuid primary key default gen_random_uuid(),\n  user_id    uuid not null references auth.users (id) on delete cascade,\n  code_hash  text not null,\n  used_at    timestamptz,\n  created_at timestamptz not null default now(),\n  unique (user_id, code_hash)\n);\n\ncreate index mfa_recovery_codes_user on public.mfa_recovery_codes (user_id)\n  where used_at is null;\n\nalter table public.mfa_recovery_codes enable row level security;\n\n-- No force: the definer functions below are the only writers, exactly as with\n-- audit_logs. See migration 14 for why forcing it would refuse them too.\n\n-- A person may see that they have codes, and how many are left. The hash is\n-- readable in the sense that any column of a visible row is, which is why it\n-- is a hash: reading it yields nothing usable. Nobody sees anybody else's.\ncreate policy mfa_recovery_read_own on public.mfa_recovery_codes\n  for select to authenticated\n  using (user_id = auth.uid());\n\n-- No insert, update or delete policy at all. Codes are issued and spent by the\n-- functions below, so a caller cannot mint themselves a code, and cannot\n-- un-spend one.\ngrant select on public.mfa_recovery_codes to authenticated;\nrevoke insert, update, delete on public.mfa_recovery_codes from authenticated, anon;\n\n/**\n * Replaces this person's recovery codes with the ones given.\n *\n * Takes hashes, never codes: the plaintext is generated in the application,\n * shown once, and never sent to the database. Replacing rather than adding,\n * because a fresh set has to invalidate the old one — otherwise a code from a\n * printout two years ago still works.\n */\ncreate or replace function public.replace_recovery_codes(p_hashes text[])\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid uuid := auth.uid();\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  if array_length(p_hashes, 1) is null or array_length(p_hashes, 1) > 20 then\n    raise exception 'expected between 1 and 20 recovery codes' using errcode = '22023';\n  end if;\n\n  delete from public.mfa_recovery_codes where user_id = uid;\n\n  insert into public.mfa_recovery_codes (user_id, code_hash)\n  select uid, hash from unnest(p_hashes) as hash;\nend;\n$$;\n\nrevoke all on function public.replace_recovery_codes(text[]) from public, anon;\ngrant execute on function public.replace_recovery_codes(text[]) to authenticated;\n\n/**\n * Spends a recovery code, if it is one of this person's unused ones.\n *\n * Returns whether it was accepted. The update is the check — a single\n * statement that matches only an unused code and marks it used in the same\n * breath, so two simultaneous attempts with the same code cannot both succeed.\n */\ncreate or replace function public.redeem_recovery_code(p_hash text)\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  uid     uuid := auth.uid();\n  spent   uuid;\nbegin\n  if uid is null then\n    raise exception 'authentication required' using errcode = '42501';\n  end if;\n\n  update public.mfa_recovery_codes\n     set used_at = now()\n   where user_id = uid\n     and code_hash = p_hash\n     and used_at is null\n  returning id into spent;\n\n  if spent is null then\n    return false;\n  end if;\n\n  -- The code is spent and the factor is about to be removed by the caller,\n  -- which holds the credentials to do it. Clearing the flag here keeps the\n  -- two in step: a profile that still said mfa_enabled with no factor left\n  -- would lock the account out of its own data with nothing able to satisfy\n  -- the guard.\n  update public.user_profiles\n     set mfa_enabled = false, mfa_enabled_at = null\n   where id = uid;\n\n  return true;\nend;\n$$;\n\nrevoke all on function public.redeem_recovery_code(text) from public, anon;\ngrant execute on function public.redeem_recovery_code(text) to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260901090000_16_subscription_entitlements.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260901090000_16_subscription_entitlements.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 16 — Subscription plans, entitlements and lapsed-account writes\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Migration 01 gave every organisation a `subscriptions` row carrying a plan\n-- name and three numbers. Nothing read the plan. What a tier actually included\n-- lived in a constant array on the billing page, and what a tier permitted\n-- lived nowhere at all — an organisation whose subscription was cancelled a\n-- year ago kept full use of the platform, because no code ever asked.\n--\n-- This migration supplies the two halves that were missing:\n--\n--   1. A catalogue. What each tier costs and what it includes are rows, so the\n--      pricing page, the entitlement check and the payment webhook read one\n--      answer. Changing what Growth includes is an update, not a deployment.\n--\n--   2. Enforcement. A subscription that has lapsed stops write access to the\n--      business data, in the database, for every caller — including one\n--      holding a valid token and talking to PostgREST directly rather than to\n--      our pages.\n--\n-- ── why writes and not reads ──────────────────────────────────────────────\n-- The blunt version of this is to refuse a lapsed organisation everything.\n-- That is wrong on two counts. Commercially, a customer who cannot see the\n-- invoice cannot pay it. Legally, POPIA s23 gives the data subject a right of\n-- access that does not lapse when a card expires — locking someone out of\n-- their own records to collect a debt would be the platform withholding\n-- personal information it holds on request.\n--\n-- So a lapsed organisation keeps reading its own data, keeps its billing page,\n-- keeps its export and deletion requests — and cannot add to, change or\n-- destroy the business records until the subscription is current again.\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 1. The catalogue\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.subscription_plans (\n  plan                 public.subscription_plan primary key,\n  name                 text    not null,\n  tagline              text    not null,\n  -- Rand, in cents. Null where the price is negotiated rather than published.\n  price_cents_monthly  integer check (price_cents_monthly is null or price_cents_monthly >= 0),\n  price_cents_annual   integer check (price_cents_annual is null or price_cents_annual >= 0),\n  currency_code        char(3) not null default 'ZAR',\n  -- The defaults a new subscription on this tier is opened with. The\n  -- subscription row remains the effective state: an Enterprise contract is\n  -- negotiated, and negotiating it must not require a catalogue edit that\n  -- would move every other Enterprise customer with it.\n  seats                integer not null default 3  check (seats > 0),\n  -- Null is no limit. It has to be nullable for the same reason `included`\n  -- and `limit_value` are separate columns below: unlimited and not-sold are\n  -- different answers, and one number cannot carry both.\n  data_source_limit    integer check (data_source_limit is null or data_source_limit >= 0),\n  ai_credits_monthly   integer not null default 500 check (ai_credits_monthly >= 0),\n  trial_days           integer not null default 30 check (trial_days >= 0),\n  -- Enterprise is a conversation, not a checkout button.\n  contact_sales        boolean not null default false,\n  is_public            boolean not null default true,\n  sort_order           integer not null default 0,\n  created_at           timestamptz not null default now(),\n  updated_at           timestamptz not null default now()\n);\n\ncomment on table public.subscription_plans is\n  'What each tier costs and what a subscription on it is opened with. Read by the pricing page, the billing page and the payment webhook, so the three cannot disagree.';\n\ncreate trigger subscription_plans_touch\n  before update on public.subscription_plans\n  for each row execute function amryn.touch_updated_at();\n\ninsert into public.subscription_plans\n  (plan, name, tagline, price_cents_monthly, price_cents_annual, seats, data_source_limit, ai_credits_monthly, trial_days, contact_sales, sort_order)\nvalues\n  ('starter',      'Starter',      'One site, two data sources, the numbers that matter.',\n     99900,  1_078_900,   3,   2,    500, 30, false, 1),\n  ('growth',       'Growth',       'Several branches, eight sources, and the market watched for you.',\n    399900,  4_318_900,  10,   8,  2_500, 30, false, 2),\n  ('professional', 'Professional', 'The full radar, unlimited sources, reports on your own terms.',\n    999900, 10_798_900,  30, null, 10_000, 14, false, 3),\n  ('enterprise',   'Enterprise',   'Single sign-on, negotiated scale and a named person to call.',\n   2_000_000, null,     100, null, 50_000,  0, true,  4);\n\ncomment on column public.subscription_plans.price_cents_annual is\n  'Twelve months for the price of about eleven. Null where the tier is negotiated.';\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 2. Entitlements\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Deliberately the same shape as `permissions`: a catalogue of keys and a\n-- join table saying which tier carries which. The application mirrors the\n-- vocabulary so it can explain a refusal, and the database decides.\n--\n-- Permissions and entitlements answer different questions and are not\n-- interchangeable. A permission asks \"is this person allowed to?\" — an analyst\n-- may not change billing however much the company pays. An entitlement asks\n-- \"has this company bought it?\" — the founder on Starter is allowed to use the\n-- competitor radar and has not purchased it. Both must be satisfied.\n\ncreate table public.entitlements (\n  key         text primary key,\n  category    text not null,\n  name        text not null,\n  description text not null,\n  -- 'feature' is on or off. 'quota' carries a number, and null means no limit.\n  kind        text not null default 'feature' check (kind in ('feature', 'quota')),\n  sort_order  integer not null default 0\n);\n\ncomment on table public.entitlements is\n  'The vocabulary of what a subscription can include. Mirrored in src/lib/billing/entitlements.ts so the application can name what is missing.';\n\ninsert into public.entitlements (key, category, name, description, kind, sort_order) values\n  ('command_centre',        'Intelligence', 'Executive Command Centre',   'The daily view of the business.',                            'feature',  1),\n  ('financial_intelligence','Intelligence', 'Financial intelligence',     'Revenue, margin, cash and the forecast.',                    'feature',  2),\n  ('performance_tracking',  'Intelligence', 'Performance tracking',       'KPIs, goals and the action centre.',                         'feature',  3),\n  ('risk_radar',            'Intelligence', 'Risk radar',                 'Risks scored, ranked and tracked to closure.',               'feature',  4),\n  ('opportunity_pipeline',  'Growth',       'Opportunity pipeline',       'Opportunities found, scored and assigned.',                  'feature',  5),\n  ('market_intelligence',   'Growth',       'Market intelligence',        'Signals from your market, read for you.',                    'feature',  6),\n  ('competitor_radar',      'Growth',       'Competitor radar',           'Named competitors watched continuously.',                    'feature',  7),\n  ('ai_assistant',          'Intelligence', 'AI DigitalTwin® assistant',  'Ask the twin about your own figures.',                       'feature',  8),\n  ('report_weekly',         'Reporting',    'Weekly briefing',            'The weekly brief, written and delivered.',                   'feature',  9),\n  ('report_monthly',        'Reporting',    'Monthly board pack',         'The monthly review, in board-meeting form.',                 'feature', 10),\n  ('custom_reports',        'Reporting',    'Reports on your own terms',  'Choose the sections, the period and the recipients.',        'feature', 11),\n  ('api_access',            'Operations',   'API access',                 'Read your intelligence from your own systems.',              'feature', 12),\n  ('sso',                   'Operations',   'Single sign-on',             'Sign in with your company identity provider.',               'feature', 13),\n  ('white_label',           'Operations',   'Your branding',              'Reports and the interface in your own colours.',             'feature', 14),\n  ('priority_support',      'Support',      'Priority support',           'A four-hour response during business hours.',                'feature', 15),\n  ('success_manager',       'Support',      'Named success manager',      'A person who knows your business and answers the phone.',    'feature', 16),\n  ('seats',                 'Operations',   'People',                     'How many colleagues can be given an account.',               'quota',   17),\n  ('data_sources',          'Operations',   'Data sources',               'How many systems can feed the platform.',                    'quota',   18),\n  ('ai_credits',            'Intelligence', 'AI usage',                   'How much the assistant may be asked each month.',            'quota',   19),\n  ('audit_retention_days',  'Operations',   'Audit history',              'How far back the audit log is kept.',                        'quota',   20),\n  ('branches',              'Operations',   'Sites',                      'How many branches may be tracked separately.',               'quota',   21);\n\ncreate table public.plan_entitlements (\n  plan            public.subscription_plan not null references public.subscription_plans (plan) on delete cascade,\n  entitlement_key text not null references public.entitlements (key) on delete cascade,\n  included        boolean not null default true,\n  -- Only meaningful for a quota. Null on an included quota means no limit.\n  limit_value     integer check (limit_value is null or limit_value >= 0),\n  primary key (plan, entitlement_key)\n);\n\ncomment on table public.plan_entitlements is\n  'The matrix. One row per tier per entitlement; absent is the same as not included, so a new entitlement is off everywhere until it is deliberately sold.';\n\n-- Features. Written as a matrix rather than four separate inserts so that the\n-- shape of the offer is legible in one screen — which is the point of having\n-- it in one place at all.\ninsert into public.plan_entitlements (plan, entitlement_key, included)\nselect t.plan, m.key, t.included\nfrom (values\n  --  key                       starter growth  professional enterprise\n  ('command_centre',            true,   true,   true,        true),\n  ('financial_intelligence',    true,   true,   true,        true),\n  ('performance_tracking',      true,   true,   true,        true),\n  ('risk_radar',                false,  true,   true,        true),\n  ('opportunity_pipeline',      false,  true,   true,        true),\n  ('market_intelligence',       false,  true,   true,        true),\n  ('competitor_radar',          false,  false,  true,        true),\n  ('ai_assistant',              true,   true,   true,        true),\n  ('report_weekly',             true,   true,   true,        true),\n  ('report_monthly',            false,  true,   true,        true),\n  ('custom_reports',            false,  false,  true,        true),\n  ('api_access',                false,  false,  true,        true),\n  ('sso',                       false,  false,  false,       true),\n  ('white_label',               false,  false,  false,       true),\n  ('priority_support',          false,  false,  true,        true),\n  ('success_manager',           false,  false,  false,       true)\n) as m(key, starter, growth, professional, enterprise)\ncross join lateral (values\n  ('starter'::public.subscription_plan,      m.starter),\n  ('growth'::public.subscription_plan,       m.growth),\n  ('professional'::public.subscription_plan, m.professional),\n  ('enterprise'::public.subscription_plan,   m.enterprise)\n) as t(plan, included);\n\n-- Quotas.\n--\n-- The three that a subscription carries a column for are selected *from* the\n-- catalogue rather than typed again beside it. Written out by hand they were\n-- wrong within the hour: the matrix said Professional had unlimited data\n-- sources while the catalogue said a hundred, and both were being read — the\n-- pricing page from one, the enforcement from the other. Two places to state\n-- one number is one place too many.\ninsert into public.plan_entitlements (plan, entitlement_key, included, limit_value)\nselect plan, 'seats',        true, seats              from public.subscription_plans\nunion all\nselect plan, 'data_sources', true, data_source_limit  from public.subscription_plans\nunion all\nselect plan, 'ai_credits',   true, ai_credits_monthly from public.subscription_plans;\n\n-- The rest have no column on `subscriptions` and live here alone.\ninsert into public.plan_entitlements (plan, entitlement_key, included, limit_value) values\n  ('starter',      'audit_retention_days', true,    90),\n  ('growth',       'audit_retention_days', true,   365),\n  ('professional', 'audit_retention_days', true, 1_095),\n  ('enterprise',   'audit_retention_days', true,  null),\n\n  ('starter',      'branches',             true,     1),\n  ('growth',       'branches',             true,    10),\n  ('professional', 'branches',             true,  null),\n  ('enterprise',   'branches',             true,  null);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 3. What the subscription now has to record\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- There is no payment gateway. Customers pay by electronic transfer against a\n-- reference, email the proof, and an operator issues an activation link. That\n-- is a deliberate choice and not a placeholder: it needs no card processing\n-- agreement, no gateway account, no secret in the deployment, and it matches\n-- how South African business-to-business software of this size is actually\n-- bought. The columns below record the outcome of that process, whoever\n-- eventually performs it — a gateway added later writes the same fields.\n\n-- Null is no limit, matching the catalogue. It was not null with a default of\n-- two, which left no way to express the unlimited sources Professional is sold\n-- with other than a large number that would eventually be reached.\nalter table public.subscriptions\n  alter column data_source_limit drop not null;\n\nalter table public.subscriptions\n  add column cancel_at_period_end boolean not null default false,\n  add column cancelled_at         timestamptz,\n  -- A payment that has not landed yet is not the same as a refusal to pay.\n  -- Transfers between South African banks still take a day, and a customer who\n  -- has paid should not lose the platform while the money is in flight. Set\n  -- when the period lapses; cleared when an activation is redeemed.\n  add column grace_until          timestamptz,\n  add column last_payment_at      timestamptz,\n  add column activated_at         timestamptz,\n  add column activated_by         uuid references auth.users (id) on delete set null;\n\ncomment on column public.subscriptions.grace_until is\n  'How long an unpaid period is tolerated before writes are refused. Null when the subscription is not in arrears.';\n\n-- Bring the existing rows in line with the catalogue they were opened against.\n-- Every organisation created before this migration is on Starter's defaults\n-- already; this makes that a fact rather than a coincidence of two numbers\n-- that happened to be typed the same.\nupdate public.subscriptions s\n   set price_cents_monthly = coalesce(p.price_cents_monthly, s.price_cents_monthly)\n  from public.subscription_plans p\n where p.plan = s.plan\n   and s.price_cents_monthly is distinct from coalesce(p.price_cents_monthly, s.price_cents_monthly);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 4. Paying by transfer, and being activated\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- The sequence, and where each step is recorded:\n--\n--   1. The customer chooses a plan and a term.       request_subscription()\n--      They are given a reference to quote on the transfer.\n--   2. They pay, and email the proof.                (outside the platform)\n--   3. An operator confirms the money arrived.       issue_activation()\n--      That mints a one-time link and returns it to be sent to the customer.\n--   4. The customer opens the link.                  redeem_activation()\n--      The plan is applied and the period starts from that moment.\n--\n-- Step 3 is the control. Nothing a customer can do — not the request, not the\n-- proof they attach, not any field they can write — moves a subscription to\n-- active. The platform never takes the customer's word for a payment, which is\n-- the same rule a gateway integration would follow when it refuses to trust\n-- the browser and waits for the webhook.\n\ncreate table public.subscription_activations (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  plan            public.subscription_plan not null,\n  -- One month or twelve. Stored rather than derived so a change to the\n  -- catalogue's annual price cannot retrospectively alter what was invoiced.\n  term_months     integer not null default 1 check (term_months in (1, 12)),\n  amount_cents    integer not null check (amount_cents >= 0),\n  currency_code   char(3) not null default 'ZAR',\n  -- What the customer quotes on the transfer, and what the operator matches\n  -- the proof against. Unique, and generated rather than chosen.\n  reference       text not null unique,\n\n  state           text not null default 'awaiting_payment'\n                    check (state in ('awaiting_payment', 'payment_confirmed', 'activated', 'cancelled', 'expired')),\n\n  requested_by    uuid references auth.users (id) on delete set null,\n  requested_at    timestamptz not null default now(),\n\n  -- Set at step 3. Never the link itself: only a SHA-256 hash is stored, so a\n  -- leaked backup activates nothing. The raw token exists once, in the\n  -- response to the operator who will send it on. Same rule as invitations.\n  token_hash      text unique,\n  confirmed_by    uuid references auth.users (id) on delete set null,\n  confirmed_at    timestamptz,\n  payment_note    text,\n  expires_at      timestamptz,\n\n  activated_at    timestamptz,\n  activated_by    uuid references auth.users (id) on delete set null,\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  -- The states are not independent of the columns that record them.\n  constraint confirmed_carries_a_token check (\n    state = 'awaiting_payment' or state = 'cancelled' or token_hash is not null\n  ),\n  constraint activated_carries_a_time check (\n    (state = 'activated') = (activated_at is not null)\n  )\n);\n\ncomment on table public.subscription_activations is\n  'One row per attempt to buy or renew a subscription: what was asked for, what reference was quoted, who confirmed the money arrived, and when the customer redeemed the link. The billing history a dispute is answered from.';\n\n-- One open request per organisation. A partial index rather than a plain\n-- constraint, so the same organisation can request again after cancelling,\n-- letting a request expire, or completing one.\ncreate unique index subscription_activations_open\n  on public.subscription_activations (organisation_id)\n  where state in ('awaiting_payment', 'payment_confirmed');\n\ncreate index subscription_activations_org_idx\n  on public.subscription_activations (organisation_id, requested_at desc);\n\ncreate trigger subscription_activations_touch\n  before update on public.subscription_activations\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 5. Reading an entitlement\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Is this organisation's subscription in a state that permits work?\n--\n-- Split out from the entitlement question because the two fail differently: a\n-- missing entitlement is an upgrade, an inactive subscription is a payment.\ncreate or replace function amryn.subscription_current(org uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(\n    (select\n       case s.status\n         when 'active'    then true\n         -- A trial is a subscription until the day it says it is not.\n         when 'trialing'  then coalesce(s.trial_ends_at, s.current_period_end) > now()\n         -- In arrears, inside the grace period we allowed for it.\n         when 'past_due'  then coalesce(s.grace_until, s.current_period_end + interval '7 days') > now()\n         when 'cancelled' then false\n         else false\n       end\n     from public.subscriptions s\n     where s.organisation_id = org),\n    -- No subscription row is not a free pass. Every organisation is created\n    -- with one; an organisation without one is a broken record, and the safe\n    -- reading of a broken billing record is \"not paid\".\n    false);\n$$;\n\ncomment on function amryn.subscription_current is\n  'Whether the organisation may currently be worked in. Reads are never gated on this — see the header of migration 16.';\n\n-- Does the organisation''s plan include this?\n--\n-- Note what is *not* here: the subscription''s status. A cancelled Professional\n-- customer still has the Professional feature set — they simply cannot write.\n-- Conflating the two would mean a lapsed account silently losing pages as well\n-- as write access, and being told the wrong thing about why.\ncreate or replace function amryn.has_entitlement(org uuid, key text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(\n    (select pe.included\n       from public.subscriptions s\n       join public.plan_entitlements pe\n         on pe.plan = s.plan and pe.entitlement_key = key\n      where s.organisation_id = org),\n    false);\n$$;\n\n-- The number attached to a quota, or null for no limit.\n--\n-- The subscription row wins over the catalogue where it carries its own\n-- column, because that is where a negotiated contract is recorded. The\n-- catalogue is what a tier opens with, not a ceiling it can never exceed.\ncreate or replace function amryn.entitlement_limit(org uuid, key text)\nreturns integer\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select case key\n    when 'seats'        then s.seats\n    when 'data_sources' then s.data_source_limit\n    when 'ai_credits'   then s.ai_credits_monthly\n    else pe.limit_value\n  end\n  from public.subscriptions s\n  left join public.plan_entitlements pe\n    on pe.plan = s.plan and pe.entitlement_key = key\n  where s.organisation_id = org;\n$$;\n\n-- One round trip for the whole picture, which is what a page render needs.\ncreate view public.organisation_entitlements\nwith (security_invoker = true) as\nselect\n  s.organisation_id,\n  e.key            as entitlement_key,\n  e.category,\n  e.name,\n  e.description,\n  e.kind,\n  e.sort_order,\n  coalesce(pe.included, false) as included,\n  case e.key\n    when 'seats'        then s.seats\n    when 'data_sources' then s.data_source_limit\n    when 'ai_credits'   then s.ai_credits_monthly\n    else pe.limit_value\n  end              as limit_value\nfrom public.subscriptions s\ncross join public.entitlements e\nleft join public.plan_entitlements pe\n  on pe.plan = s.plan and pe.entitlement_key = e.key;\n\ncomment on view public.organisation_entitlements is\n  'Every entitlement resolved for every organisation the caller can see. security_invoker, so Row Level Security on subscriptions decides which organisations that is.';\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 6. Refusing writes on a lapsed subscription\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- ── why a trigger and not a policy ────────────────────────────────────────\n-- The policy version of this means appending a condition to the `with check`\n-- of every write policy in the schema — around ninety of them, each edited by\n-- hand, with no way to assert afterwards that none was missed. Worse, the\n-- obvious shortcut of folding the condition into amryn.has_permission() would\n-- catch reads too: several select policies are written against a manage_\n-- permission, so a lapsed customer would lose sight of their own invoices,\n-- which is the one thing they must be able to see.\n--\n-- A trigger separates the two cleanly. It fires on writes and never on reads,\n-- it attaches by iterating the catalogue rather than by being remembered, and\n-- it is one function to read when someone asks what the rule is.\n\ncreate or replace function amryn.refuse_lapsed_write()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  org uuid;\nbegin\n  -- The service role and the owner carry no `sub` claim: a webhook applying a\n  -- payment, a scheduled job and a migration must all keep working, and it is\n  -- specifically a payment that has to get through to end the lapse.\n  if coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''),\n              nullif(auth.jwt() ->> 'sub', '')) is null then\n    return coalesce(new, old);\n  end if;\n\n  org := case tg_op when 'DELETE' then old.organisation_id else new.organisation_id end;\n  if org is null then\n    return coalesce(new, old);\n  end if;\n\n  if not amryn.subscription_current(org) then\n    raise exception\n      'This organisation''s subscription is not active, so its records cannot be changed. Reading, exporting and billing are unaffected.'\n      using errcode = 'check_violation',\n            hint = 'Settle the subscription on the billing page to resume.';\n  end if;\n\n  return coalesce(new, old);\nend $$;\n\ncomment on function amryn.refuse_lapsed_write is\n  'Refuses changes to business records while a subscription is lapsed. Reads, billing and data-rights records are exempt — see migration 16 header.';\n\n-- Which tables it guards.\n--\n-- Everything owned by an organisation, except:\n--   billing              a customer who cannot pay cannot recover, and the\n--                        activation that ends the lapse is itself a write\n--   audit                the record of what happened must not have a gap\n--   membership           removing a person's access must always be possible\n--\n-- The POPIA machinery is absent from the list for a better reason than\n-- exemption: none of it is organisation-scoped. A data request belongs to the\n-- person who made it and consent is columns on user_profiles and\n-- organisations, so the loop below — which selects on organisation_id — never\n-- reaches any of them. The right of access keeps working for the same reason\n-- reads do, not because somebody remembered to name it here.\ndo $$\ndeclare\n  t text;\n  exempt constant text[] := array[\n    'subscriptions', 'billing_records', 'subscription_activations',\n    'audit_logs',\n    'organisation_members', 'member_permission_overrides',\n    'organisation_invitations'\n  ];\nbegin\n  for t in\n    select c.relname\n      from pg_class c\n      join pg_namespace n on n.oid = c.relnamespace\n      join pg_attribute a on a.attrelid = c.oid and a.attname = 'organisation_id'\n     where n.nspname = 'public'\n       and c.relkind = 'r'\n       and not a.attisdropped\n       and c.relname <> all (exempt)\n     order by c.relname\n  loop\n    execute format(\n      'create trigger %I before insert or update or delete on public.%I '\n      || 'for each row execute function amryn.refuse_lapsed_write()',\n      left('zz_subscription_' || t, 63), t);\n  end loop;\nend $$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 7. Moving a subscription, from one place\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Puts an organisation on a plan and copies the catalogue's opening figures.\n--\n-- Definer, and deliberately not callable by a signed-in user. This is the only\n-- statement in the schema that makes a subscription active, so it is reached\n-- through redeem_activation() or by an operator holding the service role, and\n-- never by posting to an endpoint.\ncreate or replace function public.apply_subscription_plan(\n  p_organisation uuid,\n  p_plan         public.subscription_plan,\n  p_status       public.subscription_status default null,\n  p_period_start timestamptz default null,\n  p_period_end   timestamptz default null\n)\nreturns public.subscriptions\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  catalogue public.subscription_plans;\n  updated     public.subscriptions;\n  -- Not named `status`: PL/pgSQL refuses a bare name that matches both a\n  -- variable and a column of a table in the statement, and `subscriptions`\n  -- has one.\n  next_status public.subscription_status;\nbegin\n  select * into catalogue from public.subscription_plans where plan = p_plan;\n  if not found then\n    raise exception 'no such plan: %', p_plan using errcode = '22023';\n  end if;\n\n  select coalesce(p_status, s.status) into next_status\n    from public.subscriptions s where s.organisation_id = p_organisation;\n\n  update public.subscriptions s\n     set plan                 = p_plan,\n         status               = coalesce(p_status, s.status),\n         -- Seats can be negotiated above the catalogue, and a plan change\n         -- never silently takes them away. Reducing someone's seat count is a\n         -- decision for a person, not a side effect of applying a tier.\n         seats                = greatest(catalogue.seats, s.seats),\n         data_source_limit    = catalogue.data_source_limit,\n         ai_credits_monthly   = catalogue.ai_credits_monthly,\n         price_cents_monthly  = coalesce(catalogue.price_cents_monthly, s.price_cents_monthly),\n         currency_code        = catalogue.currency_code,\n         current_period_start = coalesce(p_period_start, s.current_period_start),\n         current_period_end   = coalesce(p_period_end, s.current_period_end),\n         -- Becoming active ends the arrears and the trial in one step.\n         grace_until          = case when next_status = 'active' then null else s.grace_until end,\n         trial_ends_at        = case when next_status = 'active' then null else s.trial_ends_at end,\n         cancelled_at         = case when next_status = 'cancelled'\n                                     then coalesce(s.cancelled_at, now()) else null end,\n         activated_at         = case when next_status = 'active'\n                                     then now() else s.activated_at end\n   where s.organisation_id = p_organisation\n  returning * into updated;\n\n  if not found then\n    raise exception 'organisation % has no subscription', p_organisation\n      using errcode = 'P0002';\n  end if;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)\n  values\n    (p_organisation, auth.uid(), 'subscription.plan_applied', 'subscription', updated.id::text,\n     catalogue.name,\n     jsonb_build_object('plan', p_plan, 'status', updated.status));\n\n  return updated;\nend $$;\n\nrevoke all on function public.apply_subscription_plan(uuid, public.subscription_plan, public.subscription_status, timestamptz, timestamptz) from public, anon, authenticated;\n\n-- ── step 1: the customer asks ─────────────────────────────────────────────\n--\n-- Returns the reference to quote on the transfer. Deliberately says nothing\n-- about the subscription itself: asking does not change what the organisation\n-- currently has, and a request left unpaid must not remove anything either.\ncreate or replace function public.request_subscription(\n  p_plan        public.subscription_plan,\n  p_term_months integer default 1\n)\nreturns public.subscription_activations\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  catalogue public.subscription_plans;\n  org       uuid;\n  amount    integer;\n  created   public.subscription_activations;\nbegin\n  if auth.uid() is null then\n    raise exception 'not signed in' using errcode = '28000';\n  end if;\n  if p_term_months not in (1, 12) then\n    raise exception 'a subscription is bought by the month or by the year'\n      using errcode = '22023';\n  end if;\n\n  -- The organisation is taken from the caller's own membership rather than\n  -- from an argument, so nobody can open a request against a company they\n  -- happen to know the identifier of.\n  select m.organisation_id into org\n    from public.organisation_members m\n   where m.user_id = auth.uid()\n     and m.status = 'active'\n     and amryn.has_permission(m.organisation_id, 'manage_billing')\n   order by m.joined_at\n   limit 1;\n\n  if org is null then\n    raise exception 'only someone who manages billing can request a subscription'\n      using errcode = '42501';\n  end if;\n\n  select * into catalogue from public.subscription_plans where plan = p_plan;\n  if not found then\n    raise exception 'no such plan: %', p_plan using errcode = '22023';\n  end if;\n  if catalogue.contact_sales then\n    raise exception 'the % plan is arranged with us directly', catalogue.name\n      using errcode = '22023',\n            hint = 'Email the team and we will put the agreement together.';\n  end if;\n\n  amount := case when p_term_months = 12\n                 then coalesce(catalogue.price_cents_annual, catalogue.price_cents_monthly * 12)\n                 else catalogue.price_cents_monthly end;\n  if amount is null then\n    raise exception 'the % plan has no published price', catalogue.name\n      using errcode = '22023';\n  end if;\n\n  -- Supersede whatever was open. Someone who changes their mind before paying\n  -- should not have to ask an operator to clear the old request first.\n  update public.subscription_activations\n     set state = 'cancelled'\n   where organisation_id = org\n     and state in ('awaiting_payment', 'payment_confirmed');\n\n  insert into public.subscription_activations\n    (organisation_id, plan, term_months, amount_cents, currency_code, reference, requested_by)\n  values\n    (org, p_plan, p_term_months, amount, catalogue.currency_code,\n     -- Short enough to be typed into a banking app's reference field, which is\n     -- commonly twenty characters, and long enough not to collide.\n     'AMR-' || upper(encode(gen_random_bytes(4), 'hex')),\n     auth.uid())\n  returning * into created;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)\n  values\n    (org, auth.uid(), 'subscription.requested', 'subscription_activation', created.id::text,\n     catalogue.name,\n     jsonb_build_object('plan', p_plan, 'term_months', p_term_months, 'reference', created.reference));\n\n  return created;\nend $$;\n\n-- ── step 3: an operator confirms the money arrived ────────────────────────\n--\n-- Takes the hash, not the token. The link is generated by the application,\n-- shown once to the operator who will send it, and never stored anywhere it\n-- could be read back — the same treatment an invitation gets.\n--\n-- Revoked from every signed-in role. Confirming a payment is an operator\n-- action carried out with the service role; a customer with manage_billing\n-- must not be able to confirm their own transfer.\ncreate or replace function public.issue_activation(\n  p_activation uuid,\n  p_token_hash text,\n  p_confirmed_by uuid default null,\n  p_note       text default null,\n  p_valid_for  interval default interval '14 days'\n)\nreturns public.subscription_activations\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  updated public.subscription_activations;\nbegin\n  update public.subscription_activations a\n     set state        = 'payment_confirmed',\n         token_hash   = p_token_hash,\n         confirmed_by = p_confirmed_by,\n         confirmed_at = now(),\n         payment_note = p_note,\n         expires_at   = now() + p_valid_for\n   where a.id = p_activation\n     and a.state = 'awaiting_payment'\n  returning * into updated;\n\n  if not found then\n    raise exception 'no activation awaiting payment with id %', p_activation\n      using errcode = 'P0002';\n  end if;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)\n  values\n    (updated.organisation_id, p_confirmed_by, 'subscription.payment_confirmed',\n     'subscription_activation', updated.id::text, updated.reference,\n     jsonb_build_object('plan', updated.plan, 'amount_cents', updated.amount_cents));\n\n  return updated;\nend $$;\n\nrevoke all on function public.issue_activation(uuid, text, uuid, text, interval) from public, anon, authenticated;\n\n-- ── what the activation page may say before anyone is signed in ───────────\n--\n-- Possession of the link is the whole authorisation, so this returns only what\n-- the page needs to render: which organisation, which plan, and whether the\n-- link is still good. Not the amount, not the reference, not who paid.\ncreate or replace function public.activation_preview(p_token text)\nreturns table (\n  organisation_name text,\n  plan              public.subscription_plan,\n  plan_name         text,\n  term_months       integer,\n  state             text\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  hashed text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');\n  record_ record;\nbegin\n  select a.*, o.name as org_name, p.name as tier_name\n    into record_\n    from public.subscription_activations a\n    join public.organisations o on o.id = a.organisation_id\n    join public.subscription_plans p on p.plan = a.plan\n   where a.token_hash = hashed;\n\n  if record_.id is null then\n    return query select null::text, null::public.subscription_plan, null::text, null::integer, 'unknown'::text;\n    return;\n  end if;\n\n  return query select\n    record_.org_name::text,\n    record_.plan,\n    record_.tier_name::text,\n    record_.term_months,\n    case\n      when record_.state = 'activated' then 'already_used'\n      when record_.state <> 'payment_confirmed' then 'unavailable'\n      when record_.expires_at is not null and record_.expires_at < now() then 'expired'\n      else 'ready'\n    end::text;\nend $$;\n\n-- ── step 4: the customer redeems the link ─────────────────────────────────\n--\n-- The period runs from redemption rather than from confirmation, so a link\n-- sent on a Friday and opened on a Monday does not cost the customer a\n-- weekend. The activation is marked used in the same transaction that makes\n-- the subscription active, so a link cannot be redeemed twice.\ncreate or replace function public.redeem_activation(p_token text)\nreturns public.subscriptions\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  hashed  text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');\n  claim   public.subscription_activations;\n  result  public.subscriptions;\nbegin\n  -- for update, so two clicks on the same link race for the row rather than\n  -- both reading it as unused.\n  select * into claim\n    from public.subscription_activations\n   where token_hash = hashed\n   for update;\n\n  if claim.id is null then\n    raise exception 'this activation link is not recognised' using errcode = '22023';\n  end if;\n  if claim.state = 'activated' then\n    raise exception 'this activation link has already been used' using errcode = '22023';\n  end if;\n  if claim.state <> 'payment_confirmed' then\n    raise exception 'this activation link is not ready to be used' using errcode = '22023';\n  end if;\n  if claim.expires_at is not null and claim.expires_at < now() then\n    update public.subscription_activations set state = 'expired' where id = claim.id;\n    raise exception 'this activation link has expired' using errcode = '22023',\n      hint = 'Ask us for a new one; the payment is still on record.';\n  end if;\n\n  result := public.apply_subscription_plan(\n    claim.organisation_id,\n    claim.plan,\n    'active',\n    now(),\n    now() + make_interval(months => claim.term_months));\n\n  update public.subscriptions\n     set last_payment_at = now(),\n         activated_by    = auth.uid()\n   where organisation_id = claim.organisation_id\n  returning * into result;\n\n  update public.subscription_activations\n     set state = 'activated', activated_at = now(), activated_by = auth.uid()\n   where id = claim.id;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)\n  values\n    (claim.organisation_id, auth.uid(), 'subscription.activated',\n     'subscription_activation', claim.id::text, claim.reference,\n     jsonb_build_object('plan', claim.plan, 'term_months', claim.term_months));\n\n  return result;\nend $$;\n\n-- ── who may see an activation record ──────────────────────────────────────\nalter table public.subscription_activations enable row level security;\n\n-- Readable by whoever manages billing, so the customer can see the reference\n-- to pay against and what has been confirmed.\ncreate policy subscription_activations_read on public.subscription_activations\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_billing'));\n\n-- No write policy, and the grant is revoked as well. Every write goes through\n-- one of the definer functions above, which is what keeps the confirmation\n-- step out of the customer's hands: a policy alone would let anyone with\n-- manage_billing set state = 'activated' on their own row, because Row Level\n-- Security decides rows, not columns.\n--\n-- Deliberately not forced: the definer functions run as this table's owner,\n-- and forcing it would refuse them along with everyone else. The revoked grant\n-- is the stronger control here and is unaffected either way — the same\n-- reasoning, and the same exception, as audit_logs and mfa_recovery_codes.\nrevoke insert, update, delete on public.subscription_activations from authenticated;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 8. Who may read the catalogue\n-- ═══════════════════════════════════════════════════════════════════════════\n\nalter table public.subscription_plans  enable row level security;\nalter table public.subscription_plans  force row level security;\nalter table public.entitlements        enable row level security;\nalter table public.entitlements        force row level security;\nalter table public.plan_entitlements   enable row level security;\nalter table public.plan_entitlements   force row level security;\n\n-- The catalogue is the price list. It is on the marketing site, so treating it\n-- as a secret from a signed-in customer would be theatre.\n--\n-- `to public` rather than `to authenticated` because forcing row level\n-- security applies to the table's owner too, and the definer functions above\n-- read these rows as the owner. A policy naming only `authenticated` would\n-- leave apply_subscription_plan() reading an empty catalogue and reporting\n-- \"no such plan\" for a tier that is sitting right there. The grant, not the\n-- policy, is what keeps anonymous callers out: migration 09 grants these\n-- tables to `authenticated` alone, and `anon` holds nothing.\ncreate policy subscription_plans_read on public.subscription_plans\n  for select to public using (true);\n\ncreate policy entitlements_read on public.entitlements\n  for select to public using (true);\n\ncreate policy plan_entitlements_read on public.plan_entitlements\n  for select to public using (true);\n\n-- Nobody signed in changes the price list. It changes by migration, or by an\n-- operator holding the service role.\nrevoke insert, update, delete on public.subscription_plans from authenticated;\nrevoke insert, update, delete on public.entitlements from authenticated;\nrevoke insert, update, delete on public.plan_entitlements from authenticated;\n\ngrant select on public.organisation_entitlements to authenticated;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 9. Privileges for the role that does the operator's work\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Found while writing the confirmation step, and older than this migration.\n--\n-- Migration 09 established default privileges so that a table added by a later\n-- migration is reachable by `authenticated` — the snapshot problem, fixed for\n-- one role. `service_role` has exactly the same problem and was not covered:\n-- Supabase grants it the public schema once, at project creation, and that\n-- grant likewise says nothing about tables that do not exist yet. Every table\n-- added since migration 09 — rate limits, data requests, and now these — was\n-- therefore invisible to the one client that is supposed to be able to reach\n-- everything, and would have failed the first time an operator tool touched\n-- one, reported as a missing table rather than as a missing privilege.\n--\n-- Row Level Security is not weakened by any of this: service_role bypasses it\n-- by design, which is why the key never reaches a browser.\ngrant all on all tables in schema public to service_role;\ngrant all on all sequences in schema public to service_role;\n\nalter default privileges in schema public\n  grant all on tables to service_role;\n\nalter default privileges in schema public\n  grant all on sequences to service_role;\n\n-- The two functions the operator holds alone. Revoked from every signed-in\n-- role above; granted here to the one role that is meant to have them, because\n-- `revoke ... from public` took the default away from service_role as well.\ngrant execute on function public.apply_subscription_plan(uuid, public.subscription_plan, public.subscription_status, timestamptz, timestamptz) to service_role;\ngrant execute on function public.issue_activation(uuid, text, uuid, text, interval) to service_role;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260901120000_17_onboarding.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260901120000_17_onboarding.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 17 — Intelligence onboarding\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Creating an organisation takes four fields and thirty seconds. What the\n-- platform needs in order to say anything useful about a business takes rather\n-- more: its shape, what it is trying to achieve, which systems hold its\n-- numbers, and who it competes with. Until now none of that was ever asked,\n-- so a new customer arrived at a Command Centre with nothing in it and no path\n-- from there to something worth looking at.\n--\n-- Seven steps ask for it. This migration is what makes them resumable.\n--\n-- ── why a record and not a wizard ─────────────────────────────────────────\n-- The obvious implementation keeps the answers in the browser until the last\n-- step and writes everything at the end. That fails the way real onboarding\n-- actually goes: it is done over several sittings, by more than one person,\n-- and half of it is delegated (\"ask the accountant which system that is\").\n-- Anything held client-side is lost by then.\n--\n-- So each step writes as it is answered, to the real tables — a branch entered\n-- in step two is a branch, not a draft — and this record tracks only which\n-- steps have been answered, which were skipped, and where to resume.\n\ncreate table public.onboarding_progress (\n  organisation_id uuid primary key references public.organisations (id) on delete cascade,\n\n  -- Where \"continue\" goes.\n  current_step    text not null default 'identity',\n  completed_steps text[] not null default '{}',\n  -- Skipping is a first-class answer, not an absence of one. A business with\n  -- one site should not be made to invent a structure, and the review step has\n  -- to be able to tell \"not applicable\" from \"not yet done\".\n  skipped_steps   text[] not null default '{}',\n\n  -- What was said that has no table of its own — how the business describes\n  -- itself, roughly how large it is, which of its systems are on paper. Kept\n  -- as a document because the questions will change and a column per question\n  -- would mean a migration each time somebody rewords one.\n  answers         jsonb not null default '{}'::jsonb,\n\n  started_at      timestamptz not null default now(),\n  completed_at    timestamptz,\n  -- When the twin was first built from the answers. Separate from completion:\n  -- somebody can finish the questions and not press the button.\n  initialised_at  timestamptz,\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  -- A misspelled step would otherwise sit in the array for ever, never\n  -- matching, and the customer would be asked the same question at every\n  -- sitting with no error anywhere to explain it.\n  constraint steps_are_known check (\n    current_step = any (array['identity','structure','objectives','systems','data','market','review'])\n    and completed_steps <@ array['identity','structure','objectives','systems','data','market','review']\n    and skipped_steps   <@ array['identity','structure','objectives','systems','data','market','review']\n  ),\n  -- A step cannot be both answered and skipped. Without this the review page\n  -- has two contradictory sources for the same question.\n  constraint not_both_done_and_skipped check (\n    not (completed_steps && skipped_steps)\n  )\n);\n\ncomment on table public.onboarding_progress is\n  'Which of the seven onboarding steps an organisation has answered, skipped, and where to resume. The answers themselves go to the real tables; only what has no table of its own is kept here.';\n\ncreate trigger onboarding_progress_touch\n  before update on public.onboarding_progress\n  for each row execute function amryn.touch_updated_at();\n\nalter table public.onboarding_progress enable row level security;\nalter table public.onboarding_progress force row level security;\n\n-- Every member can see how far setup has got — a colleague who lands on a half\n-- empty Command Centre deserves to know why rather than assume it is broken.\ncreate policy onboarding_progress_read on public.onboarding_progress\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\ncreate policy onboarding_progress_write on public.onboarding_progress\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\n-- ── the guard from migration 16 does not reach this table ─────────────────\n--\n-- refuse_lapsed_write() was attached by iterating the catalogue at the moment\n-- migration 16 ran. That is a snapshot, and this table did not exist yet — so\n-- it carries no trigger, and neither will anything added after it unless\n-- somebody remembers.\n--\n-- Here that is the right answer and is stated rather than inherited: setting\n-- up is how a trial becomes a customer, and an organisation whose trial ran\n-- out mid-onboarding must be able to finish and then pay. Test 19 asserts that\n-- every other table with an organisation_id either carries the guard or is on\n-- the exemption list, so the next table added is a failing test rather than a\n-- silent gap.\n\n-- ── opening the record ────────────────────────────────────────────────────\n--\n-- Definer, because the first caller is the person who has just created the\n-- organisation and the row has to exist before anything can be saved against\n-- it. Idempotent, so a refresh or a second tab costs nothing.\ncreate or replace function public.ensure_onboarding(p_organisation uuid)\nreturns public.onboarding_progress\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  result public.onboarding_progress;\nbegin\n  if not amryn.is_member(p_organisation) then\n    raise exception 'not a member of that organisation' using errcode = '42501';\n  end if;\n\n  insert into public.onboarding_progress (organisation_id)\n  values (p_organisation)\n  on conflict (organisation_id) do nothing;\n\n  select * into result from public.onboarding_progress\n   where organisation_id = p_organisation;\n\n  return result;\nend $$;\n\n-- ── finishing ─────────────────────────────────────────────────────────────\n--\n-- One statement, so that \"the questions are answered\" and \"the twin has been\n-- built\" cannot disagree, and so the audit entry is written in the same\n-- transaction as the thing it records.\ncreate or replace function public.complete_onboarding(p_organisation uuid)\nreturns public.onboarding_progress\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  result public.onboarding_progress;\nbegin\n  if not amryn.has_permission(p_organisation, 'manage_organisation') then\n    raise exception 'only an administrator can finish setting up' using errcode = '42501';\n  end if;\n\n  update public.onboarding_progress\n     set completed_at   = coalesce(completed_at, now()),\n         initialised_at = coalesce(initialised_at, now()),\n         current_step   = 'review'\n   where organisation_id = p_organisation\n  returning * into result;\n\n  if not found then\n    raise exception 'that organisation has not started setting up' using errcode = 'P0002';\n  end if;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values\n    (p_organisation, auth.uid(), 'onboarding.completed', 'organisation',\n     p_organisation::text, 'Setup finished and the twin initialised');\n\n  return result;\nend $$;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260902130000_18_stock_control.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260902130000_18_stock_control.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 18 — Advanced Inventory Control\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- The inventory module was built against the second Excel workbook and read a\n-- fixed dataset. Every screen worked, every calculation was right, and none of\n-- it was anybody's stock: a real organisation opening Advanced Inventory\n-- Control was shown a demonstration pharmacy's shelves. The module was\n-- recently changed to say \"not connected\" instead, which was honest and not a\n-- product. This is the table behind it.\n--\n-- ── the shape follows the workbook, because the workbook is the product ───\n-- SETTINGS holds who is auditing what, on which shift; AUDIT LOG holds one row\n-- per stock line. That is a session and its lines, so it is two tables rather\n-- than one — and the second table is what makes a history possible. An audit\n-- in March and an audit in June are two rows in `stock_audits`, and \"what did\n-- the shelves look like at year end\" becomes answerable instead of being\n-- overwritten.\n--\n-- ── what is deliberately not here ─────────────────────────────────────────\n-- Compliance profiles stay in code. They encode what a sector's regulator\n-- requires — SAHPRA retention, disposal evidence, who signs an audit off —\n-- and a change to one should arrive as a reviewed diff, not as somebody\n-- editing a text field on a Tuesday. `complianceProfile()` already falls back\n-- to the general profile for an id it does not know, so adding a fourth is a\n-- code change with no migration.\n\n-- ── the vocabulary ────────────────────────────────────────────────────────\n--\n-- Snake case, not the workbook's display strings. The six actions are labels\n-- an operator reads — \"Marked Down / Clearance\" — and rewording a label should\n-- not be a schema change. The display strings live in the engine, where they\n-- belong, and the mapping is one table in src/lib/inventory/mapping.ts.\ncreate type public.stock_action as enum (\n  'pending_review',\n  'left_on_shelf',\n  'removed_from_shelf',\n  'returned_to_supplier',\n  'marked_down',\n  'destroyed'\n);\n\ncreate type public.stock_audit_status as enum ('draft', 'in_progress', 'complete');\n\n-- ── the session ───────────────────────────────────────────────────────────\n\ncreate table public.stock_audits (\n  id                    uuid primary key default gen_random_uuid(),\n  organisation_id       uuid not null references public.organisations (id) on delete cascade,\n  -- Which site was walked. Null for an organisation that does not separate\n  -- them, which is the single-shop case and must stay easy.\n  branch_id             uuid references public.branches (id) on delete set null,\n\n  -- SETTINGS!B4–B7. Kept as text rather than as references to people: the\n  -- person who walked the shelves is often not a platform user, and an audit\n  -- that cannot record a stocktaker because they have no login is an audit\n  -- nobody does.\n  site_name             text not null,\n  auditor_name          text not null default '',\n  responsible_name      text not null default '',\n  shift                 text not null default '',\n\n  -- Resolved in code against COMPLIANCE_PROFILES; an unknown id falls back to\n  -- the general profile rather than failing, so a profile removed from the\n  -- code does not strand an audit.\n  compliance_profile_id text not null default 'general-inventory',\n\n  audit_date            date not null default current_date,\n  status                public.stock_audit_status not null default 'draft',\n\n  created_by            uuid references auth.users (id) on delete set null,\n  completed_at          timestamptz,\n  created_at            timestamptz not null default now(),\n  updated_at            timestamptz not null default now(),\n\n  -- A completed audit is one with a completion time, and an incomplete one is\n  -- not. Without this the report can be generated from a session somebody is\n  -- still halfway through, and dated as though it were finished.\n  constraint complete_carries_a_time check (\n    (status = 'complete') = (completed_at is not null)\n  )\n);\n\ncomment on table public.stock_audits is\n  'One stocktake: who walked which site, on what date, against which sector profile. The lines are in stock_items.';\n\ncreate index stock_audits_org_idx on public.stock_audits (organisation_id, audit_date desc);\n\ncreate trigger stock_audits_touch\n  before update on public.stock_audits\n  for each row execute function amryn.touch_updated_at();\n\n-- ── the lines ─────────────────────────────────────────────────────────────\n\ncreate table public.stock_items (\n  id              uuid primary key default gen_random_uuid(),\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  audit_id        uuid not null references public.stock_audits (id) on delete cascade,\n\n  -- AUDIT LOG!B–H.\n  product_name    text not null,\n  sku             text not null default '',\n  batch_number    text not null default '',\n  department      text not null default '',\n  location        text not null default '',\n  qty             integer not null default 0 check (qty >= 0),\n  expiry_date     date not null,\n\n  -- AUDIT LOG!I–N. `action` is nullable-by-default rather than null: a line\n  -- nobody has looked at is 'pending_review', which is a state the workbook\n  -- names, and the dormancy rules test against it. Null would make every rule\n  -- carry a coalesce.\n  action          public.stock_action not null default 'pending_review',\n  actioned_by     text not null default '',\n  actioned_on     date,\n  notes           text not null default '',\n\n  -- AUDIT LOG!O — the auditor's tick that this line has been dealt with.\n  verified        boolean not null default false,\n\n  -- Cents, like every other money column here, so the report can state\n  -- capital at risk without a float. Null where the cost is not known, which\n  -- is common and must not read as zero.\n  unit_cost_cents bigint check (unit_cost_cents is null or unit_cost_cents >= 0),\n\n  -- Set where a sales feed shows the item moving. Overrides the workbook's\n  -- inference that an item left on the shelf and not near expiry is dormant —\n  -- an inference it makes because it cannot see turnover.\n  has_movement    boolean,\n\n  -- The order the lines were counted in. The report prints them as numbered\n  -- rows and an auditor reads down the shelf, so the order is information.\n  position        integer not null default 0,\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  -- An action that has been taken has a date. Recording one without the other\n  -- is how a disposal ends up undocumented, which is the specific thing the\n  -- insurance and regulator notes on the report depend on.\n  constraint actioned_lines_carry_a_date check (\n    action = 'pending_review' or actioned_on is not null\n  )\n);\n\ncomment on table public.stock_items is\n  'One line of a stocktake. Expiry status, dormancy and value at risk are computed by the engine from these columns rather than stored, so a figure can never disagree with its own formula.';\n\ncreate index stock_items_audit_idx on public.stock_items (audit_id, position);\ncreate index stock_items_org_idx on public.stock_items (organisation_id);\n-- Expiry is what every report section sorts and filters on.\ncreate index stock_items_expiry_idx on public.stock_items (organisation_id, expiry_date);\n\ncreate trigger stock_items_touch\n  before update on public.stock_items\n  for each row execute function amryn.touch_updated_at();\n\n-- ── the permission ────────────────────────────────────────────────────────\n--\n-- A new key rather than reusing import_data. Importing a spreadsheet and\n-- marking a batch destroyed are different acts with different consequences,\n-- and the second is the one a regulator asks about. Naming it separately means\n-- it can be granted separately.\ninsert into public.permissions (key, category, description) values\n  ('manage_inventory', 'Operations', 'Record stocktakes, action stock lines and import stock');\n\ndo $$\ndeclare\n  r public.org_role;\nbegin\n  -- Everyone who can already see operational data, plus the analyst who does\n  -- the importing. Deliberately not the viewer: actioning a line is a\n  -- decision about stock, not a way of reading about it.\n  foreach r in array array[\n    'super_admin','org_admin','executive','regional_manager',\n    'branch_manager','department_manager','analyst'\n  ]::public.org_role[]\n  loop\n    insert into public.role_permissions (role, permission_key)\n    values (r, 'manage_inventory')\n    on conflict do nothing;\n  end loop;\nend $$;\n\n-- ── who may read and write them ───────────────────────────────────────────\n\nalter table public.stock_audits enable row level security;\nalter table public.stock_audits force row level security;\nalter table public.stock_items  enable row level security;\nalter table public.stock_items  force row level security;\n\ncreate policy stock_audits_read on public.stock_audits\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'view_operations_data'));\n\ncreate policy stock_audits_write on public.stock_audits\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_inventory'))\n  with check (amryn.has_permission(organisation_id, 'manage_inventory'));\n\ncreate policy stock_items_read on public.stock_items\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'view_operations_data'));\n\ncreate policy stock_items_write on public.stock_items\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_inventory'))\n  with check (amryn.has_permission(organisation_id, 'manage_inventory'));\n\n-- ── the lapsed-subscription guard ─────────────────────────────────────────\n--\n-- Attached by hand, and that is the point. Migration 16 attached it by\n-- iterating the catalogue at the moment it ran, which is a snapshot: a table\n-- added afterwards carries no trigger and nothing about writing this migration\n-- would say so. Test 19 asserts the whole list, so leaving these two out is a\n-- failing test rather than a silent gap — which is exactly what it was written\n-- to catch.\n--\n-- Stock is business data, so it is guarded rather than exempt: an organisation\n-- whose subscription has lapsed keeps reading its stocktakes and its report,\n-- and cannot record new ones.\ncreate trigger zz_subscription_stock_audits\n  before insert or update or delete on public.stock_audits\n  for each row execute function amryn.refuse_lapsed_write();\n\ncreate trigger zz_subscription_stock_items\n  before insert or update or delete on public.stock_items\n  for each row execute function amryn.refuse_lapsed_write();\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260905060000_19_extension_schema_resolution.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260905060000_19_extension_schema_resolution.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 19 — where the database looks for pgcrypto\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Five functions were dead on the hosted database. Not slow, not wrong —\n-- dead, every call, for every caller:\n--\n--   request_subscription   42883  function gen_random_bytes(integer) does not exist\n--   activation_preview     42883  function digest(text, unknown) does not exist\n--   redeem_activation      42883  function digest(text, unknown) does not exist\n--   invitation_preview     42883  function digest(text, unknown) does not exist\n--   accept_invitation      42883  function digest(text, unknown) does not exist\n--\n-- Between them that is the whole of the paid journey and the whole of the team\n-- journey: nobody could take out a subscription, nobody could be handed an\n-- activation link after paying by EFT, and nobody could be invited into an\n-- organisation. The screens were all built and all correct; the call at the\n-- bottom of each one raised before it did anything.\n--\n-- ── why it was invisible ──────────────────────────────────────────────────\n--\n-- Migration 01 asks for the extension without saying where:\n--\n--     create extension if not exists \"pgcrypto\";\n--\n-- On a plain PostgreSQL instance that installs it into `public`, which is on\n-- the search_path, and everything resolves. On Supabase pgcrypto is already\n-- installed — into `extensions` — so `if not exists` does nothing at all and\n-- the functions stay where Supabase put them.\n--\n-- Each of the five then pins `search_path = public, pg_temp`, correctly, so\n-- that a caller cannot shadow what a SECURITY DEFINER function resolves. That\n-- pin excludes `extensions`. The symbols are present in the database and\n-- unreachable from inside the function.\n--\n-- CI runs the SQL suite against a plain PostgreSQL, where the extension lands\n-- in `public` and all five pass. The failure exists only on the layout nobody\n-- tested, which is the layout in production. Test 22 now recreates the hosted\n-- arrangement, so this cannot come back silently.\n--\n-- ── the fix ───────────────────────────────────────────────────────────────\n--\n-- Add `extensions` to the pin rather than schema-qualifying each call site.\n-- Qualifying would hardcode one of the two layouts and break the other; naming\n-- both schemas is correct on both, because PostgreSQL ignores an entry in\n-- search_path that does not exist. Nothing untrusted can write to `extensions`\n-- — it is owned by the database owner and neither anon nor authenticated holds\n-- CREATE on it — so widening the pin by that one schema gives up none of what\n-- the pin is for.\n--\n-- ALTER rather than CREATE OR REPLACE: the bodies are right and were never the\n-- problem, and restating them here would leave two copies to keep in step.\n\nalter function public.request_subscription(public.subscription_plan, integer)\n  set search_path = public, extensions, pg_temp;\nalter function public.activation_preview(text)\n  set search_path = public, extensions, pg_temp;\nalter function public.redeem_activation(text)\n  set search_path = public, extensions, pg_temp;\nalter function public.invitation_preview(text)\n  set search_path = public, extensions, pg_temp;\nalter function public.accept_invitation(text)\n  set search_path = public, extensions, pg_temp;\n\n-- ── prove it, here, rather than trusting the ALTERs ───────────────────────\n--\n-- The five above are the ones known to be broken. This resolves the symbols\n-- the way those functions now resolve them and fails the migration if either\n-- is still unreachable, so a database that would go on refusing every payment\n-- and every invitation cannot record this migration as applied.\ndo $$\ndeclare\n  probe bytea;\nbegin\n  perform set_config('search_path', 'public, extensions, pg_temp', true);\n  probe := digest('resolution probe', 'sha256');\n  probe := gen_random_bytes(4);\nexception when undefined_function then\n  raise exception\n    'pgcrypto is not reachable from public, extensions, pg_temp — subscriptions, activations and invitations would still fail'\n    using errcode = '42883';\nend $$;\n\n-- ── while here: the five trigger functions with no pin at all ─────────────\n--\n-- Found by the same sweep. These are SECURITY INVOKER, so an unpinned path is\n-- not the privilege escalation it would be above — a caller who shadowed a\n-- name would only be shadowing it for themselves. It is still the one rule the\n-- rest of the schema keeps without exception, and a trigger that decides\n-- whether a branch belongs to your organisation is not where to start making\n-- exceptions. Every object each of them touches is already schema-qualified,\n-- so pinning changes no behaviour.\n\nalter function amryn.assert_branch_region_same_org()     set search_path = public, pg_temp;\nalter function amryn.assert_department_branch_same_org() set search_path = public, pg_temp;\nalter function amryn.assert_health_weights_sum()         set search_path = public, pg_temp;\nalter function amryn.derive_risk_severity()              set search_path = public, pg_temp;\nalter function amryn.touch_updated_at()                  set search_path = public, pg_temp;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260905070000_20_rls_initplan.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260905070000_20_rls_initplan.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 20 — evaluate auth.uid() once per query, not once per row\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Twelve policies name auth.uid() directly. PostgreSQL treats that as a\n-- per-row expression and calls it again for every row it examines, so reading\n-- a thousand notifications reads the JWT a thousand times. Wrapping it in a\n-- scalar subquery makes it an InitPlan: computed once, before the scan, and\n-- compared against as a constant.\n--\n--   using (user_id = auth.uid())            → one call per row\n--   using (user_id = (select auth.uid()))   → one call per query\n--\n-- The two are equivalent. auth.uid() is STABLE — by definition it cannot\n-- change within a statement — so a single evaluation is not an approximation\n-- of the per-row one, it is the same answer arrived at once. Nothing about who\n-- can see what changes here, which is the only reason this is worth doing at\n-- all: an optimisation that alters a tenancy boundary is not an optimisation.\n--\n-- Left alone deliberately: amryn.is_member(organisation_id) and\n-- amryn.has_permission(organisation_id, ...). They read auth.uid() too, but\n-- they take a column as an argument, so they genuinely do depend on the row\n-- and cannot be hoisted out of the scan. Wrapping those would change what they\n-- are asked, not when.\n--\n-- Policies are dropped and recreated rather than altered, because ALTER POLICY\n-- cannot change a policy's command or roles and restating the whole thing\n-- makes the diff readable. Each is recreated with the same command, the same\n-- roles and the same predicate, differing only in the parenthesised select.\n\n-- ── user_profiles ─────────────────────────────────────────────────────────\n\ndrop policy user_profiles_read on public.user_profiles;\ncreate policy user_profiles_read on public.user_profiles\n  for select to authenticated\n  using (\n    id = (select auth.uid())\n    or exists (\n      select 1\n        from public.organisation_members me\n        join public.organisation_members them\n          on them.organisation_id = me.organisation_id\n       where me.user_id = (select auth.uid())\n         and me.status = 'active'\n         and them.user_id = user_profiles.id\n    )\n  );\n\ndrop policy user_profiles_write on public.user_profiles;\ncreate policy user_profiles_write on public.user_profiles\n  for update to authenticated\n  using (id = (select auth.uid()))\n  with check (id = (select auth.uid()));\n\ndrop policy user_profiles_insert on public.user_profiles;\ncreate policy user_profiles_insert on public.user_profiles\n  for insert to authenticated\n  with check (id = (select auth.uid()));\n\n-- ── organisation_members ──────────────────────────────────────────────────\n--\n-- The first arm is what lets somebody see their own membership row in an\n-- organisation they are not yet active in; is_member() would refuse it.\n\ndrop policy members_read on public.organisation_members;\ncreate policy members_read on public.organisation_members\n  for select to authenticated\n  using (user_id = (select auth.uid()) or amryn.is_member(organisation_id));\n\n-- ── opportunity_assignments ───────────────────────────────────────────────\n\ndrop policy opportunity_assignments_read on public.opportunity_assignments;\ncreate policy opportunity_assignments_read on public.opportunity_assignments\n  for select to authenticated\n  using (\n    assignee_id = (select auth.uid())\n    or amryn.has_permission(organisation_id, 'view_opportunities')\n  );\n\n-- ── notifications ─────────────────────────────────────────────────────────\n--\n-- The table this matters most on: a notification list is read constantly and\n-- is the one place a user routinely scans many of their own rows at once.\n\ndrop policy notifications_read on public.notifications;\ncreate policy notifications_read on public.notifications\n  for select to authenticated\n  using (user_id = (select auth.uid()));\n\ndrop policy notifications_update on public.notifications;\ncreate policy notifications_update on public.notifications\n  for update to authenticated\n  using (user_id = (select auth.uid()))\n  with check (user_id = (select auth.uid()));\n\n-- ── the assistant's own conversations ─────────────────────────────────────\n\ndrop policy ai_conversations_own on public.ai_conversations;\ncreate policy ai_conversations_own on public.ai_conversations\n  for all to authenticated\n  using (user_id = (select auth.uid()) and amryn.is_member(organisation_id))\n  with check (user_id = (select auth.uid()) and amryn.is_member(organisation_id));\n\ndrop policy ai_messages_own on public.ai_messages;\ncreate policy ai_messages_own on public.ai_messages\n  for all to authenticated\n  using (\n    amryn.is_member(organisation_id)\n    and exists (\n      select 1 from public.ai_conversations c\n       where c.id = ai_messages.conversation_id\n         and c.user_id = (select auth.uid())\n    )\n  )\n  with check (\n    amryn.is_member(organisation_id)\n    and exists (\n      select 1 from public.ai_conversations c\n       where c.id = ai_messages.conversation_id\n         and c.user_id = (select auth.uid())\n    )\n  );\n\n-- ── POPIA requests and recovery codes ─────────────────────────────────────\n\ndrop policy data_requests_read_own on public.data_requests;\ncreate policy data_requests_read_own on public.data_requests\n  for select to authenticated\n  using (user_id = (select auth.uid()));\n\ndrop policy data_requests_create_own on public.data_requests;\ncreate policy data_requests_create_own on public.data_requests\n  for insert to authenticated\n  with check (user_id = (select auth.uid()));\n\ndrop policy mfa_recovery_read_own on public.mfa_recovery_codes;\ncreate policy mfa_recovery_read_own on public.mfa_recovery_codes\n  for select to authenticated\n  using (user_id = (select auth.uid()));\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260905080000_21_revoke_unused_anon_grants.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260905080000_21_revoke_unused_anon_grants.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 21 — take back the anon grants nothing asked for\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Every SECURITY DEFINER function from migration 04 to migration 15 ends with\n-- a line taking back what PostgreSQL grants by default:\n--\n--     revoke all on function public.accept_invitation(text) from public, anon;\n--\n-- Migrations 16 and 17 wrote nine such functions and remembered it twice.\n-- The other five are reachable by anyone holding the publishable key, over\n-- /rest/v1/rpc/, without signing in.\n--\n-- None of them is exploitable — each was probed on the live database as anon\n-- and each refuses:\n--\n--     ensure_onboarding      42501  not a member of that organisation\n--     complete_onboarding    42501  only an administrator can finish setting up\n--     request_subscription   28000  not signed in\n--     redeem_activation      requires auth.uid() to record who activated\n--\n-- So this changes no answer. It changes where the answer is decided: at the\n-- grant, rather than eleven statements into a function body that had to be\n-- read to know it was safe. Every one of these is called by the application\n-- with a session — redeem_activation() through requireUser() in\n-- features/billing/activate.ts — so nothing loses a caller it had.\n--\n-- The point is not this week's function bodies. It is that a guard added in\n-- one place is one edit away from being removed, and the convention the rest\n-- of the schema keeps means that edit cannot silently open a door.\n\n-- Revoke then grant, both halves, as migration 11 does for accept_invitation.\n-- The revoke alone would lock out the people these exist for: on a database\n-- built from these migrations `authenticated` has no grant of its own on any\n-- of the four and reaches them through the default PUBLIC one, so taking that\n-- back takes their own access with it. The SQL suite caught exactly that —\n-- test 19 could no longer buy a subscription.\n\nrevoke all on function public.ensure_onboarding(uuid) from public, anon;\ngrant execute on function public.ensure_onboarding(uuid) to authenticated;\n\nrevoke all on function public.complete_onboarding(uuid) from public, anon;\ngrant execute on function public.complete_onboarding(uuid) to authenticated;\n\nrevoke all on function public.request_subscription(public.subscription_plan, integer) from public, anon;\ngrant execute on function public.request_subscription(public.subscription_plan, integer) to authenticated;\n\nrevoke all on function public.redeem_activation(text) from public, anon;\ngrant execute on function public.redeem_activation(text) to authenticated;\n\n-- ── the one that stays open, and why ──────────────────────────────────────\n--\n-- activation_preview() answers the page somebody lands on from the email\n-- before they have signed in — \"Amryn (Pty) Ltd, Professional, ready\" — and\n-- must keep answering it. Possession of the link is the whole authorisation,\n-- which is why the function returns the organisation, the plan and the state\n-- and not the amount, the reference, or who paid.\n--\n-- Revoked from PUBLIC and granted to anon deliberately, exactly as\n-- invitation_preview() is: the two are the same shape and the same decision.\nrevoke all on function public.activation_preview(text) from public;\ngrant execute on function public.activation_preview(text) to anon, authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260905190000_22_foreign_key_indexes.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260905190000_22_foreign_key_indexes.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 22 — an index on every foreign key\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Seventy-four foreign keys had no index. PostgreSQL does not create one: a\n-- foreign key constrains the child, and indexing it is left to whoever knows\n-- how the data will be read.\n--\n-- Two things go wrong without them, and only one is about queries.\n--\n-- ── the one everybody thinks of ───────────────────────────────────────────\n-- Every row-level security policy in this schema filters on organisation_id.\n-- Ten tables carried that column as an unindexed foreign key, so every read\n-- against them was a sequential scan filtered afterwards. That is invisible at\n-- a few hundred rows and is exactly the shape of thing that becomes a support\n-- ticket at a few hundred thousand.\n--\n-- ── the one that bites first ──────────────────────────────────────────────\n-- Deleting a parent row makes PostgreSQL check every child table that\n-- references it — to cascade, to null, or to refuse. Without an index that\n-- check is a sequential scan of the child, per parent row deleted, whether or\n-- not anybody ever queries by that column.\n--\n-- Most of these cascade from organisations. Deleting one customer's\n-- organisation would have scanned every table in the schema, holding locks\n-- throughout. The POPIA erasure path does exactly that, and it is the one\n-- operation that must not time out halfway.\n--\n-- ── why all of them, rather than a chosen few ─────────────────────────────\n-- Because the second reason applies to every foreign key regardless of query\n-- patterns, and because choosing a subset means predicting which columns will\n-- be filtered on later — a guess that reads as engineering judgement and is\n-- not. The write cost is a few bytes per row per index on tables that are\n-- currently small; the alternative is finding out which ones mattered from a\n-- customer.\n--\n-- Single-column, and deliberately not composite. An index only serves a\n-- foreign key's integrity check when the key's columns are a *prefix* of it,\n-- so (organisation_id, branch_id) would serve the organisation_id key and do\n-- nothing at all for the branch_id one.\n--\n-- `if not exists` throughout, so this is safe to re-run and safe on a database\n-- where somebody has already added one by hand.\n\n-- ── organisation_id: the column every RLS policy filters on ───────────────\n--\n-- These ten are the highest value in the file on both counts — the filter path\n-- for every read, and the cascade path when an organisation is deleted.\n\ncreate index if not exists ai_conversations_org_idx\n  on public.ai_conversations (organisation_id);\ncreate index if not exists ai_messages_org_idx\n  on public.ai_messages (organisation_id);\ncreate index if not exists goal_progress_org_idx\n  on public.goal_progress (organisation_id);\ncreate index if not exists market_sources_org_idx\n  on public.market_sources (organisation_id);\ncreate index if not exists member_permission_overrides_org_idx\n  on public.member_permission_overrides (organisation_id);\ncreate index if not exists notifications_org_idx\n  on public.notifications (organisation_id);\ncreate index if not exists opportunity_activities_org_idx\n  on public.opportunity_activities (organisation_id);\ncreate index if not exists opportunity_scores_org_idx\n  on public.opportunity_scores (organisation_id);\ncreate index if not exists risk_events_org_idx\n  on public.risk_events (organisation_id);\ncreate index if not exists strategic_initiatives_org_idx\n  on public.strategic_initiatives (organisation_id);\n\n-- ── where a record sits: region, branch, department ───────────────────────\n--\n-- The scoping columns. A regional manager's every query narrows by branch, and\n-- closing a branch cascades through all of these.\n\ncreate index if not exists ai_recommendations_branch_idx\n  on public.ai_recommendations (branch_id);\ncreate index if not exists alerts_branch_idx\n  on public.alerts (branch_id);\ncreate index if not exists alerts_department_idx\n  on public.alerts (department_id);\ncreate index if not exists branches_region_idx\n  on public.branches (region_id);\ncreate index if not exists business_events_branch_idx\n  on public.business_events (branch_id);\ncreate index if not exists business_events_department_idx\n  on public.business_events (department_id);\ncreate index if not exists business_health_scores_branch_idx\n  on public.business_health_scores (branch_id);\ncreate index if not exists business_insights_branch_idx\n  on public.business_insights (branch_id);\ncreate index if not exists departments_branch_idx\n  on public.departments (branch_id);\ncreate index if not exists financial_records_branch_idx\n  on public.financial_records (branch_id);\ncreate index if not exists financial_records_department_idx\n  on public.financial_records (department_id);\ncreate index if not exists goals_branch_idx\n  on public.goals (branch_id);\ncreate index if not exists goals_department_idx\n  on public.goals (department_id);\n-- Not metric_values_branch_idx: that name is taken by a partial composite,\n-- (organisation_id, branch_id, period_start DESC) WHERE branch_id IS NOT NULL,\n-- which serves the organisation_id key and does nothing for this one — wrong\n-- leading column, and partial besides. `if not exists` matched the name and\n-- skipped the index silently; test 23 is what noticed.\ncreate index if not exists metric_values_branch_fk_idx\n  on public.metric_values (branch_id);\ncreate index if not exists metric_values_department_idx\n  on public.metric_values (department_id);\ncreate index if not exists operational_records_branch_idx\n  on public.operational_records (branch_id);\ncreate index if not exists operational_records_department_idx\n  on public.operational_records (department_id);\ncreate index if not exists opportunities_branch_idx\n  on public.opportunities (branch_id);\ncreate index if not exists risks_branch_idx\n  on public.risks (branch_id);\ncreate index if not exists sales_records_branch_idx\n  on public.sales_records (branch_id);\ncreate index if not exists sales_records_department_idx\n  on public.sales_records (department_id);\ncreate index if not exists stock_audits_branch_idx\n  on public.stock_audits (branch_id);\n\n-- ── where a number came from: data source, metric ─────────────────────────\n--\n-- Disconnecting a data source or retiring a metric touches every fact table\n-- that referenced it.\n\ncreate index if not exists business_events_metric_idx\n  on public.business_events (metric_id);\ncreate index if not exists data_connections_source_idx\n  on public.data_connections (data_source_id);\ncreate index if not exists data_health_checks_source_idx\n  on public.data_health_checks (data_source_id);\ncreate index if not exists data_imports_source_idx\n  on public.data_imports (data_source_id);\ncreate index if not exists financial_records_source_idx\n  on public.financial_records (data_source_id);\ncreate index if not exists goals_metric_idx\n  on public.goals (metric_id);\ncreate index if not exists market_signals_market_source_idx\n  on public.market_signals (market_source_id);\ncreate index if not exists metric_values_source_idx\n  on public.metric_values (data_source_id);\ncreate index if not exists operational_records_source_idx\n  on public.operational_records (data_source_id);\ncreate index if not exists sales_records_source_idx\n  on public.sales_records (data_source_id);\n\n-- ── who did it: owners, assignees, actors, and the audit trail ────────────\n--\n-- These reference auth.users. Deleting a user — which POPIA erasure requires —\n-- checks every one of them.\n\ncreate index if not exists ai_recommendations_owner_idx\n  on public.ai_recommendations (owner_id);\ncreate index if not exists alerts_assignee_idx\n  on public.alerts (assignee_id);\ncreate index if not exists data_imports_uploaded_by_idx\n  on public.data_imports (uploaded_by);\ncreate index if not exists data_sources_created_by_idx\n  on public.data_sources (created_by);\ncreate index if not exists goal_progress_recorded_by_idx\n  on public.goal_progress (recorded_by);\ncreate index if not exists goals_owner_idx\n  on public.goals (owner_id);\ncreate index if not exists opportunity_activities_actor_idx\n  on public.opportunity_activities (actor_id);\ncreate index if not exists opportunity_assignments_assigned_by_idx\n  on public.opportunity_assignments (assigned_by);\ncreate index if not exists opportunity_assignments_assignee_idx\n  on public.opportunity_assignments (assignee_id);\ncreate index if not exists organisation_invitations_accepted_by_idx\n  on public.organisation_invitations (accepted_by);\ncreate index if not exists organisation_invitations_invited_by_idx\n  on public.organisation_invitations (invited_by);\ncreate index if not exists organisation_members_invited_by_idx\n  on public.organisation_members (invited_by);\ncreate index if not exists organisations_dpa_accepted_by_idx\n  on public.organisations (dpa_accepted_by);\ncreate index if not exists reports_generated_by_idx\n  on public.reports (generated_by);\ncreate index if not exists risk_events_actor_idx\n  on public.risk_events (actor_id);\ncreate index if not exists risks_owner_idx\n  on public.risks (owner_id);\ncreate index if not exists stock_audits_created_by_idx\n  on public.stock_audits (created_by);\ncreate index if not exists strategic_initiatives_owner_idx\n  on public.strategic_initiatives (owner_id);\ncreate index if not exists subscription_activations_activated_by_idx\n  on public.subscription_activations (activated_by);\ncreate index if not exists subscription_activations_confirmed_by_idx\n  on public.subscription_activations (confirmed_by);\ncreate index if not exists subscription_activations_requested_by_idx\n  on public.subscription_activations (requested_by);\ncreate index if not exists subscriptions_activated_by_idx\n  on public.subscriptions (activated_by);\n\n-- ── record to record: alerts, activities, events ──────────────────────────\n\ncreate index if not exists alerts_event_idx\n  on public.alerts (business_event_id);\ncreate index if not exists alerts_opportunity_idx\n  on public.alerts (opportunity_id);\ncreate index if not exists alerts_risk_idx\n  on public.alerts (risk_id);\ncreate index if not exists ai_recommendations_opportunity_idx\n  on public.ai_recommendations (opportunity_id);\ncreate index if not exists competitor_events_competitor_idx\n  on public.competitor_events (competitor_id);\ncreate index if not exists opportunity_assignments_opportunity_idx\n  on public.opportunity_assignments (opportunity_id);\ncreate index if not exists risk_events_risk_idx\n  on public.risk_events (risk_id);\n\n-- ── the permission and entitlement catalogues ─────────────────────────────\n--\n-- Small and rarely changed, so these earn their place on the cascade argument\n-- rather than the query one. Included for the same reason as the rest: a\n-- foreign key with no index is a sequential scan waiting for the day somebody\n-- edits the catalogue.\n\ncreate index if not exists member_permission_overrides_permission_idx\n  on public.member_permission_overrides (permission_key);\ncreate index if not exists plan_entitlements_entitlement_idx\n  on public.plan_entitlements (entitlement_key);\ncreate index if not exists role_permissions_permission_idx\n  on public.role_permissions (permission_key);\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260906090000_23_job_runner.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260906090000_23_job_runner.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 23 — The job runner, and feature flags\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Everything this platform computes, it computes inside the request that\n-- renders it. That is the right answer for a health score over twelve rows and\n-- the wrong answer for everything coming next: an analysis measured in minutes,\n-- a simulation run five hundred times, a brief that has to be written at six in\n-- the morning whether or not anybody has opened a page. None of those fit in an\n-- HTTP request, and a server action that tried would be killed by a proxy long\n-- before it finished.\n--\n-- So: a queue in the database, and a worker that drains it. This migration is\n-- the queue. The worker is src/worker/main.ts.\n--\n-- ── why the database and not a queue service ──────────────────────────────\n-- A separate broker would mean a second store that can disagree with this one.\n-- The thing a job is *about* lives in PostgreSQL — the organisation, the\n-- figures, the row it will write — and a job that has been acknowledged by a\n-- broker but whose transaction rolled back is a job that ran against a state\n-- that never existed. Keeping the queue in the same database makes enqueueing\n-- and the change that justified it one transaction, which is the only version\n-- of this that is correct rather than usually correct.\n--\n-- `for update skip locked` is what makes that safe with more than one worker.\n-- It has been in PostgreSQL since 9.5 and is exactly the primitive a broker\n-- would be reimplementing.\n--\n-- ── what is deliberately not here ─────────────────────────────────────────\n-- There is no customer-facing way to enqueue a job. Nothing in the application\n-- creates one yet, and an entry point with no caller is an entry point whose\n-- permission check nobody has ever exercised. The first thing that genuinely\n-- needs to enqueue from a page brings its own function, with the permission\n-- that job actually requires. Until then the only writer is the worker, over a\n-- direct connection, as the owner.\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 1. The queue\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate type public.job_status as enum (\n  'queued', 'running', 'succeeded', 'failed', 'cancelled'\n);\n\ncreate table public.job_runs (\n  id               uuid primary key default gen_random_uuid(),\n\n  -- Null is a platform job: pruning, sweeping, anything that belongs to the\n  -- installation rather than to a customer. Everything else is a tenant's, and\n  -- is subject to that tenant's feature flag below.\n  organisation_id  uuid references public.organisations (id) on delete cascade,\n\n  -- Which handler runs it. Matched against the registry in\n  -- src/lib/jobs/registry.ts; a kind with no handler fails loudly rather than\n  -- sitting in the queue looking healthy.\n  kind             text not null check (kind <> ''),\n  payload          jsonb not null default '{}'::jsonb,\n\n  status           public.job_status not null default 'queued',\n  -- Lower runs first. A default rather than a scale, so that \"ahead of the\n  -- ordinary work\" is expressible without deciding today what the scale means.\n  priority         integer not null default 100,\n  -- The earliest it may run. Backoff sets this forward; a schedule sets it to\n  -- the top of the hour it belongs to.\n  run_at           timestamptz not null default now(),\n\n  -- Counted on *claim*, not on completion. A job that reliably kills the\n  -- worker process would otherwise never record an attempt and would be picked\n  -- up for ever by whichever worker started next.\n  attempts         integer not null default 0 check (attempts >= 0),\n  max_attempts     integer not null default 3 check (max_attempts >= 1),\n\n  -- ── the two ways of saying \"not twice\" ─────────────────────────────────\n  -- They are different questions and one column cannot answer both.\n  --\n  -- dedupe_key is once, ever: the nightly tick for the 6th of September is one\n  -- job whether four workers noticed it was due or one did. Unique across\n  -- every row regardless of status, so a succeeded slot is never re-enqueued.\n  --\n  -- singleton_key is once, at a time: one analysis per organisation in flight,\n  -- and another may be queued the moment that one finishes. Unique only while\n  -- the job is queued or running.\n  dedupe_key       text,\n  singleton_key    text,\n\n  -- ── the lease ──────────────────────────────────────────────────────────\n  -- A worker that dies mid-job cannot tell anybody. Without a lease its job\n  -- stays 'running' for ever and the work is simply lost. With one, the job\n  -- becomes claimable again the moment the lease lapses, and the attempt it\n  -- consumed is already recorded.\n  worker_id        text,\n  lease_until      timestamptz,\n\n  started_at       timestamptz,\n  finished_at      timestamptz,\n  duration_ms      integer check (duration_ms is null or duration_ms >= 0),\n\n  result           jsonb,\n  error            text,\n\n  -- Who asked for it, where a person did. Null for a schedule.\n  requested_by     uuid references auth.users (id) on delete set null,\n\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n\n  -- One-directional on purpose: worker_id and lease_until are kept after the\n  -- job ends, because \"which worker was holding this when it failed\" is the\n  -- first question anybody asks and clearing it destroys the answer.\n  constraint running_holds_a_lease check (\n    status <> 'running' or (worker_id is not null and lease_until is not null)\n  ),\n  constraint finished_has_a_time check (\n    (status in ('succeeded', 'failed', 'cancelled')) = (finished_at is not null)\n  ),\n  constraint succeeded_carries_no_error check (\n    status <> 'succeeded' or error is null\n  )\n);\n\ncomment on table public.job_runs is\n  'Work that does not fit in a request. One row per attempt to run something; the worker in src/worker/main.ts claims, runs and closes them.';\ncomment on column public.job_runs.organisation_id is\n  'Null for platform housekeeping. Where set, the job runs only if that organisation has the background_jobs flag enabled.';\ncomment on column public.job_runs.dedupe_key is\n  'Once, ever. A scheduled slot uses it so four workers noticing the same due time create one job.';\ncomment on column public.job_runs.singleton_key is\n  'Once, at a time. Unique only while queued or running, so the next one may be queued as soon as this finishes.';\ncomment on column public.job_runs.attempts is\n  'Counted on claim, not on completion, so a job that kills the worker still consumes an attempt.';\n\ncreate trigger job_runs_touch\n  before update on public.job_runs\n  for each row execute function amryn.touch_updated_at();\n\n-- ── indexes ───────────────────────────────────────────────────────────────\n--\n-- The two uniques are the deduplication rules above, expressed where they\n-- cannot be got round.\ncreate unique index job_runs_dedupe_key\n  on public.job_runs (dedupe_key)\n  where dedupe_key is not null;\n\ncreate unique index job_runs_singleton_key\n  on public.job_runs (singleton_key)\n  where singleton_key is not null and status in ('queued', 'running');\n\n-- What the claim query reads, in the order it reads it. Partial, because the\n-- rows it must never look at are the overwhelming majority once the table has\n-- any history.\ncreate index job_runs_claimable_idx\n  on public.job_runs (priority, run_at)\n  where status = 'queued';\n\n-- Expired leases, for the same reason.\ncreate index job_runs_lease_idx\n  on public.job_runs (lease_until)\n  where status = 'running';\n\n-- Both foreign keys, prefix-first, as test 23 requires. The organisation index\n-- carries created_at as well because every reading of this table by hand is\n-- \"what has this customer been running lately\".\ncreate index job_runs_org_idx on public.job_runs (organisation_id, created_at desc);\ncreate index job_runs_requested_by_idx on public.job_runs (requested_by);\n\n-- ── row level security ────────────────────────────────────────────────────\n--\n-- Read only, and only your own. The worker does not come through here: it\n-- holds a direct connection as the owner, which is also why there is no write\n-- policy for anybody. Nothing that reaches PostgREST may change this table.\nalter table public.job_runs enable row level security;\nalter table public.job_runs force row level security;\n\ncreate policy job_runs_read on public.job_runs\n  for select to authenticated\n  using (organisation_id is not null and amryn.is_member(organisation_id));\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 2. Feature flags\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Not a second entitlement system. An entitlement answers \"has this company\n-- bought it?\" and is a property of the tier; a flag answers \"is this finished\n-- enough to be switched on for this company?\" and is a property of the\n-- rollout. Conflating them means either selling something unfinished or\n-- shipping a rollout control that a plan change silently rewrites.\n--\n-- Off is the absence of a row, so a flag is off for every organisation the\n-- moment it is registered, including ones created afterwards. There is no way\n-- to write a default of true, which is the point.\n\ncreate table public.feature_flags (\n  key         text primary key check (key ~ '^[a-z][a-z0-9_]*$'),\n  name        text not null,\n  description text not null,\n  created_at  timestamptz not null default now(),\n  updated_at  timestamptz not null default now()\n);\n\ncomment on table public.feature_flags is\n  'The catalogue of rollout switches. Registering one turns it on for nobody; organisation_feature_flags is what enables it, one organisation at a time.';\n\ncreate trigger feature_flags_touch\n  before update on public.feature_flags\n  for each row execute function amryn.touch_updated_at();\n\ncreate table public.organisation_feature_flags (\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  flag_key        text not null references public.feature_flags (key) on delete cascade,\n  enabled         boolean not null default false,\n  -- Why it was turned on, for the person reading this in six months wondering\n  -- whether it is safe to turn on everywhere.\n  note            text,\n  enabled_by      uuid references auth.users (id) on delete set null,\n  enabled_at      timestamptz,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n  primary key (organisation_id, flag_key)\n);\n\ncomment on table public.organisation_feature_flags is\n  'Which organisations have which rollout switch on. Absent means off, which is why new behaviour reaches nobody until somebody names an organisation.';\n\ncreate trigger organisation_feature_flags_touch\n  before update on public.organisation_feature_flags\n  for each row execute function amryn.touch_updated_at();\n\n-- flag_key is the second column of the primary key, so the key's own foreign\n-- constraint has no index serving it. Test 23 catches exactly this.\ncreate index organisation_feature_flags_flag_idx\n  on public.organisation_feature_flags (flag_key);\ncreate index organisation_feature_flags_enabled_by_idx\n  on public.organisation_feature_flags (enabled_by);\n\nalter table public.feature_flags enable row level security;\nalter table public.feature_flags force row level security;\n\n-- The catalogue is readable by anybody signed in: naming the switches is not a\n-- disclosure, and a support conversation goes badly when neither side can see\n-- the list.\ncreate policy feature_flags_read on public.feature_flags\n  for select to authenticated using (true);\n\nalter table public.organisation_feature_flags enable row level security;\nalter table public.organisation_feature_flags force row level security;\n\n-- Read your own. No write policy: a rollout switch a customer can set is not a\n-- rollout switch. It is turned on over a direct connection, by us.\ncreate policy organisation_feature_flags_read on public.organisation_feature_flags\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\n-- ── resolving one ─────────────────────────────────────────────────────────\n--\n-- Definer so that a caller who cannot read the tables still gets an answer,\n-- and stable so a policy or a query calling it repeatedly evaluates it once.\ncreate or replace function amryn.feature_enabled(org uuid, key text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public, pg_temp\nas $$\n  select coalesce(\n    (select f.enabled\n       from public.organisation_feature_flags f\n      where f.organisation_id = org and f.flag_key = key),\n    false)\n$$;\n\ncomment on function amryn.feature_enabled is\n  'Whether a rollout switch is on for one organisation. False for an unregistered flag, an organisation with no row, and null input — off is always the answer that needs no explanation.';\n\n-- What the application reads, shaped like organisation_entitlements so the two\n-- are read the same way. The tenant filter is the underlying policy's, not\n-- restated here.\ncreate view public.organisation_features\nwith (security_invoker = true)\nas\nselect\n  o.organisation_id,\n  c.key      as flag_key,\n  c.name,\n  c.description,\n  coalesce(o.enabled, false) as enabled,\n  o.enabled_at\nfrom public.organisation_feature_flags o\njoin public.feature_flags c on c.key = o.flag_key;\n\ncomment on view public.organisation_features is\n  'The rollout switches an organisation has a row for, resolved against the catalogue. A flag absent from this view is off.';\n\ngrant select on public.organisation_features to authenticated;\n\n-- ── the one flag this migration ships ─────────────────────────────────────\n--\n-- Registered because it is used, immediately, by the claim function below —\n-- not because a later phase might want it. A flag nothing reads is a comment\n-- with a table behind it.\ninsert into public.feature_flags (key, name, description) values\n  ('background_jobs',\n   'Background processing',\n   'Whether work queued for this organisation is picked up by the worker. Off means jobs are recorded and wait, so switching it on drains the backlog rather than losing it.');\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 3. What the worker calls\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- All in `amryn`, which PostgREST does not expose, and revoked from every\n-- browser-reachable role besides. The worker holds a direct connection as the\n-- owner, so it needs no grant at all — these are definer functions only so\n-- that the day something else is allowed to call one, the decision is a grant\n-- rather than a rewrite.\n\n-- ── claiming ──────────────────────────────────────────────────────────────\n--\n-- One statement. Selecting a batch and then updating it would let two workers\n-- select the same rows in the gap between the two, which is the entire failure\n-- this exists to prevent: `for update skip locked` inside the same statement\n-- means the second worker steps over rows the first has taken rather than\n-- waiting for them or duplicating them.\n--\n-- A job whose lease has lapsed is claimable again on the same terms as a new\n-- one. That is the whole recovery story for a worker that was killed: no\n-- reaper, no timeout thread, no separate process that has to be running for\n-- the system to heal.\ncreate or replace function amryn.claim_jobs(\n  p_worker text,\n  p_limit  integer  default 1,\n  p_lease  interval default interval '5 minutes'\n)\nreturns setof public.job_runs\nlanguage plpgsql\nvolatile\nsecurity definer\nset search_path = public, pg_temp\nas $$\nbegin\n  if coalesce(trim(p_worker), '') = '' then\n    raise exception 'a worker must identify itself' using errcode = '22023';\n  end if;\n\n  return query\n  with claimable as (\n    select j.id\n      from public.job_runs j\n     where j.attempts < j.max_attempts\n       and (\n         (j.status = 'queued'  and j.run_at <= now())\n         or\n         -- Abandoned by a worker that stopped saying it was alive.\n         (j.status = 'running' and j.lease_until < now())\n       )\n       -- A tenant's work waits until that tenant is switched on. It is not\n       -- discarded: the row stays queued, so enabling the flag later runs the\n       -- backlog rather than losing it.\n       and (\n         j.organisation_id is null\n         or amryn.feature_enabled(j.organisation_id, 'background_jobs')\n       )\n     order by j.priority, j.run_at\n     limit greatest(coalesce(p_limit, 1), 0)\n     for update skip locked\n  )\n  update public.job_runs j\n     set status      = 'running',\n         attempts    = j.attempts + 1,\n         worker_id   = p_worker,\n         lease_until = now() + p_lease,\n         started_at  = coalesce(j.started_at, now())\n    from claimable c\n   where j.id = c.id\n  returning j.*;\nend $$;\n\ncomment on function amryn.claim_jobs is\n  'Takes up to p_limit runnable jobs for one worker and marks them running under a lease. Skips rows another worker holds; reclaims rows whose lease lapsed.';\n\n-- ── staying alive ─────────────────────────────────────────────────────────\n--\n-- Returns false when the job is no longer this worker's — the lease lapsed and\n-- somebody else took it. The worker is expected to stop rather than finish and\n-- write over the other one's result, which is the only way two workers running\n-- the same job produces a wrong answer rather than a wasted one.\ncreate or replace function amryn.heartbeat_job(\n  p_id     uuid,\n  p_worker text,\n  p_lease  interval default interval '5 minutes'\n)\nreturns boolean\nlanguage plpgsql\nvolatile\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  held boolean;\nbegin\n  update public.job_runs\n     set lease_until = now() + p_lease\n   where id = p_id\n     and status = 'running'\n     and worker_id = p_worker\n     and lease_until >= now();\n\n  get diagnostics held = row_count;\n  return held;\nend $$;\n\ncomment on function amryn.heartbeat_job is\n  'Extends a running job''s lease. False means the job was reclaimed by another worker and this one should abandon it.';\n\n-- ── finishing ─────────────────────────────────────────────────────────────\ncreate or replace function amryn.complete_job(\n  p_id     uuid,\n  p_result jsonb default '{}'::jsonb\n)\nreturns public.job_runs\nlanguage plpgsql\nvolatile\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  finished public.job_runs;\nbegin\n  update public.job_runs\n     set status      = 'succeeded',\n         finished_at = now(),\n         duration_ms = greatest(\n           0,\n           (extract(epoch from (now() - coalesce(started_at, now()))) * 1000)::integer),\n         result      = coalesce(p_result, '{}'::jsonb),\n         error       = null\n   where id = p_id\n     and status = 'running'\n  returning * into finished;\n\n  if not found then\n    raise exception 'job % is not running and cannot be completed', p_id\n      using errcode = 'P0002';\n  end if;\n\n  return finished;\nend $$;\n\ncomment on function amryn.complete_job is\n  'Closes a running job as succeeded. Refuses a job that is not running, so a worker whose lease lapsed cannot overwrite the outcome of the worker that took over.';\n\n-- ── failing, and deciding whether to try again ────────────────────────────\n--\n-- The delay is the worker's to choose and the decision is not. A worker that\n-- has just crashed on a poison payload is the last thing that should be\n-- deciding whether to run it again — attempts and max_attempts are columns\n-- precisely so that answer is the database's.\n--\n-- A null p_retry_in means the worker has established there is no point: an\n-- unknown kind, a payload that will never parse. Those fail terminally on the\n-- first attempt rather than three times.\ncreate or replace function amryn.fail_job(\n  p_id       uuid,\n  p_error    text,\n  p_retry_in interval default null\n)\nreturns public.job_runs\nlanguage plpgsql\nvolatile\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  existing public.job_runs;\n  finished public.job_runs;\nbegin\n  select * into existing from public.job_runs where id = p_id and status = 'running';\n  if not found then\n    raise exception 'job % is not running and cannot be failed', p_id\n      using errcode = 'P0002';\n  end if;\n\n  if p_retry_in is not null and existing.attempts < existing.max_attempts then\n    update public.job_runs\n       set status      = 'queued',\n           run_at      = now() + p_retry_in,\n           error       = p_error,\n           finished_at = null\n     where id = p_id\n    returning * into finished;\n  else\n    update public.job_runs\n       set status      = 'failed',\n           finished_at = now(),\n           duration_ms = greatest(\n             0,\n             (extract(epoch from (now() - coalesce(started_at, now()))) * 1000)::integer),\n           error       = p_error\n     where id = p_id\n    returning * into finished;\n  end if;\n\n  return finished;\nend $$;\n\ncomment on function amryn.fail_job is\n  'Records a failure and either requeues with the delay the worker asked for or gives up, depending on attempts against max_attempts. A null delay gives up immediately.';\n\n-- ── housekeeping ──────────────────────────────────────────────────────────\n--\n-- Two jobs the queue has to do for itself.\n--\n-- The first is the case the lease alone does not cover: a job that has used\n-- every attempt and was abandoned mid-run is not claimable and never will be,\n-- so without this it stays 'running' for ever and reads as work in progress.\n--\n-- The second is that a queue nobody empties becomes the largest table in the\n-- database. Failures are kept whatever their age — they are the only record of\n-- something having gone wrong, and the retention that matters is the one on\n-- the things that went right.\ncreate or replace function amryn.sweep_jobs(p_retain interval default interval '30 days')\nreturns jsonb\nlanguage plpgsql\nvolatile\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  abandoned integer;\n  removed   integer;\nbegin\n  update public.job_runs\n     set status      = 'failed',\n         finished_at = now(),\n         error       = coalesce(error, 'abandoned: the worker holding this stopped and no attempts remained')\n   where status = 'running'\n     and lease_until < now()\n     and attempts >= max_attempts;\n  get diagnostics abandoned = row_count;\n\n  delete from public.job_runs\n   where status in ('succeeded', 'cancelled')\n     and finished_at < now() - p_retain;\n  get diagnostics removed = row_count;\n\n  return jsonb_build_object('abandoned', abandoned, 'removed', removed);\nend $$;\n\ncomment on function amryn.sweep_jobs is\n  'Closes runs abandoned with no attempts left, and deletes succeeded runs past the retention window. Failures are never deleted.';\n\n-- Nothing browser-reachable calls any of these.\nrevoke all on function amryn.claim_jobs(text, integer, interval)     from public, anon, authenticated;\nrevoke all on function amryn.heartbeat_job(uuid, text, interval)     from public, anon, authenticated;\nrevoke all on function amryn.complete_job(uuid, jsonb)               from public, anon, authenticated;\nrevoke all on function amryn.fail_job(uuid, text, interval)          from public, anon, authenticated;\nrevoke all on function amryn.sweep_jobs(interval)                    from public, anon, authenticated;\nrevoke all on function amryn.feature_enabled(uuid, text)             from public, anon;\ngrant execute on function amryn.feature_enabled(uuid, text)          to authenticated;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 4. The lapsed-subscription guard\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Migration 16 attached its guard by iterating the catalogue as it stood at\n-- that moment, so every table added since carries it only if somebody says so.\n-- Test 19 asserts that every table with an organisation_id is either guarded\n-- or named on its exemption list, which is what turns \"somebody remembered\"\n-- into a failing test.\n--\n-- Both of these are guarded rather than exempt. Neither is reachable from a\n-- browser today — job_runs has no write policy and the flag table has none\n-- either — so the trigger fires for nobody, and that is exactly why it should\n-- be there before something is allowed to write to them. The worker is\n-- unaffected: it holds no JWT, and the guard lets an unclaimed caller through\n-- precisely so that scheduled work and payments keep running.\ncreate trigger zz_subscription_job_runs\n  before insert or update or delete on public.job_runs\n  for each row execute function amryn.refuse_lapsed_write();\n\ncreate trigger zz_subscription_organisation_feature_flags\n  before insert or update or delete on public.organisation_feature_flags\n  for each row execute function amryn.refuse_lapsed_write();\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260906120000_24_imprint.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260906120000_24_imprint.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 24 — The Amryn™ Imprint®\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- What migration 17 called onboarding is now the Imprint: the record of what a\n-- business is, taken once and revised for ever after. The rename is not\n-- cosmetic. \"Onboarding\" describes something done *to* a customer that is\n-- finished and forgotten; an Imprint is a thing they own, come back to, and\n-- which everything the platform says about them is derived from. The word\n-- shapes how it gets built.\n--\n-- ── why a new table rather than a rename ──────────────────────────────────\n-- `alter table ... rename to` is one statement and would be wrong. The\n-- application is deployed by starting new containers alongside the old ones\n-- and retiring the old ones as the new pass their health checks, so for a\n-- minute or so both are serving. A rename breaks every request the old\n-- containers handle in that window — not with a redirect or a stale page, but\n-- with \"relation does not exist\" on the setup flow, for real customers, with\n-- no way to retry until the rollout finishes.\n--\n-- So this is additive: new tables beside the old, a backfill, and the old ones\n-- left in place and untouched. Once every container is serving the new code\n-- and the backfill has been confirmed, a later migration removes them — as its\n-- own decision, with a backup, rather than as a side effect of this one.\n--\n-- That does mean the word survives in the database until then. It is worth\n-- being exact about that rather than claiming otherwise: `onboarding_progress`\n-- and its two functions still exist after this migration and nothing reads\n-- them.\n--\n-- ── the shape, and why it is not the old one ──────────────────────────────\n-- Migration 17 kept progress as three text arrays on one row: which steps were\n-- completed, which were skipped, and a bag of answers. That works for a wizard\n-- and stops working the moment anything needs to ask a question of one layer —\n-- which is now everything. A Quality Score has to know what was answered\n-- *within* a layer; the analysis has to know which fields are missing and act\n-- differently; a screen has to show a person where the gaps are.\n--\n-- A row per layer answers all three. Arrays of names answer none of them.\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 1. The eight Layers\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- The order is not arbitrary: each is answerable from what the one before\n-- established. You cannot say which site sells which product before the sites\n-- exist, and you cannot say what you are trying to achieve before you have\n-- said what you sell and to whom. Reordering them produces questions nobody in\n-- the room can answer yet, which is how a setup flow gets abandoned halfway.\ncreate type public.imprint_layer as enum (\n  'identity',\n  'location',\n  'offer',\n  'customers',\n  'operations',\n  'commercial',\n  'digital',\n  'intent'\n);\n\ncomment on type public.imprint_layer is\n  'The eight layers of an Imprint, in the order they are answerable. Mirrored in src/features/imprint/layers.ts.';\n\n-- Answered, deliberately passed over, or not yet reached. Three states rather\n-- than a boolean, because \"not applicable to us\" and \"not got to it yet\" need\n-- different sentences on the review screen and are treated differently by the\n-- Quality Score.\ncreate type public.imprint_layer_state as enum ('unanswered', 'answered', 'skipped');\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 2. The record\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.imprint_records (\n  organisation_id uuid primary key references public.organisations (id) on delete cascade,\n\n  -- Where \"continue\" goes. Advisory: the layer actually resumed at is computed\n  -- from what has been answered, so going back to correct one thing does not\n  -- rewind the whole Imprint.\n  current_layer   public.imprint_layer not null default 'identity',\n\n  /*\n   * How complete and how trustworthy this Imprint is, 0 to 100.\n   *\n   * Null means not yet computed, which is the honest state for an Imprint\n   * backfilled from the old record: the score is defined over fields that\n   * record did not track, and inventing a number for it would be inventing\n   * exactly the kind of figure this platform exists not to invent.\n   *\n   * Computed in one place — src/features/imprint/quality.ts — and stored here\n   * rather than derived in SQL. Two implementations of a score that gates what\n   * the platform is willing to say would eventually disagree, and the one that\n   * disagreed silently would be this one.\n   */\n  quality_score   smallint check (quality_score is null or quality_score between 0 and 100),\n  scored_at       timestamptz,\n\n  started_at      timestamptz not null default now(),\n  completed_at    timestamptz,\n  -- When the model was first built from the Imprint. Separate from completion:\n  -- somebody can answer everything and not press the button.\n  initialised_at  timestamptz,\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  -- A score with no time on it cannot be told from a stale one.\n  constraint scored_carries_a_time check ((quality_score is null) = (scored_at is null))\n);\n\ncomment on table public.imprint_records is\n  'One Imprint per organisation: where it is up to, how complete it is, and when it was last built into the model. The answers themselves are in imprint_layers.';\ncomment on column public.imprint_records.quality_score is\n  'Zero to a hundred, computed by src/features/imprint/quality.ts and stored. Null means not yet scored — never zero, which would read as a bad Imprint rather than an unmeasured one.';\n\ncreate trigger imprint_records_touch\n  before update on public.imprint_records\n  for each row execute function amryn.touch_updated_at();\n\ncreate table public.imprint_layers (\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  layer           public.imprint_layer not null,\n\n  state           public.imprint_layer_state not null default 'unanswered',\n\n  -- What was said that has no table of its own. Kept as a document because the\n  -- questions will change and a column per question would mean a migration\n  -- every time somebody rewords one.\n  answers         jsonb not null default '{}'::jsonb,\n\n  /*\n   * Which fields in this layer were left blank.\n   *\n   * \"Gaps, not blocks\" is the rule this column exists for. A person who does\n   * not know their gross margin should be able to move on and be asked again\n   * later — not stopped, and not silently recorded as having answered. Without\n   * somewhere to put the gap, the only two options are a required field or a\n   * missing answer indistinguishable from an answered one.\n   *\n   * It is also what the Quality Score reads, and what the analysis will use to\n   * say which figure it could not obtain rather than estimating one.\n   */\n  gaps            text[] not null default '{}',\n\n  answered_at     timestamptz,\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  primary key (organisation_id, layer),\n\n  -- A layer that says it is answered and carries nothing is a layer that will\n  -- be scored as complete and read as empty.\n  constraint answered_carries_a_time check ((state = 'answered') = (answered_at is not null))\n);\n\ncomment on table public.imprint_layers is\n  'One row per layer per organisation: what was said, what was left blank, and whether the layer was answered, skipped or not yet reached.';\ncomment on column public.imprint_layers.gaps is\n  'Field names left blank in this layer. What makes a gap different from an unanswered layer, and what stops the analysis estimating a figure the customer simply has not given.';\n\ncreate trigger imprint_layers_touch\n  before update on public.imprint_layers\n  for each row execute function amryn.touch_updated_at();\n\n-- The primary key leads with organisation_id, so the foreign key is served by\n-- it and needs no index of its own. Test 23 checks exactly that.\ncreate index imprint_layers_state_idx\n  on public.imprint_layers (organisation_id, state);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 3. Who may read and write it\n-- ═══════════════════════════════════════════════════════════════════════════\n\nalter table public.imprint_records enable row level security;\nalter table public.imprint_records force row level security;\nalter table public.imprint_layers  enable row level security;\nalter table public.imprint_layers  force row level security;\n\n-- Every member can see how far the Imprint has got. A colleague who lands on a\n-- half-empty Command Centre deserves to know why rather than assume it is\n-- broken.\ncreate policy imprint_records_read on public.imprint_records\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\ncreate policy imprint_records_write on public.imprint_records\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ncreate policy imprint_layers_read on public.imprint_layers\n  for select to authenticated\n  using (amryn.is_member(organisation_id));\n\ncreate policy imprint_layers_write on public.imprint_layers\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\n-- ── the lapsed-subscription guard does not reach these, on purpose ────────\n--\n-- Migration 16 refuses writes to business records while a subscription is\n-- lapsed. Both tables here are deliberately exempt, for the reason migration\n-- 17 gave for the record it replaced: taking an Imprint is how a trial becomes\n-- a customer, and an organisation whose trial ran out midway must be able to\n-- finish and then pay. Test 19 asserts the exemption is deliberate by naming\n-- them, so the next table added is a failing test rather than a silent gap.\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 4. Opening one, and finishing it\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- Definer, because the first caller is the person who has just created the\n-- organisation and the row has to exist before anything can be saved against\n-- it. Idempotent, so a refresh or a second tab costs nothing.\ncreate or replace function public.ensure_imprint(p_organisation uuid)\nreturns public.imprint_records\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  result public.imprint_records;\nbegin\n  if not amryn.is_member(p_organisation) then\n    raise exception 'not a member of that organisation' using errcode = '42501';\n  end if;\n\n  insert into public.imprint_records (organisation_id)\n  values (p_organisation)\n  on conflict (organisation_id) do nothing;\n\n  -- Recorded here rather than by the application, because here is the only\n  -- place that knows an Imprint was actually opened rather than merely looked\n  -- at. This function is called on every page load; `found` is what tells the\n  -- first call from the several thousand after it.\n  if found then\n    insert into public.audit_logs\n      (organisation_id, actor_id, action, entity_type, entity_id, summary)\n    values\n      (p_organisation, auth.uid(), 'imprint.started', 'organisation',\n       p_organisation::text, 'Imprint opened');\n  end if;\n\n  -- Every layer gets a row immediately, in the 'unanswered' state. The\n  -- alternative — creating rows as layers are answered — means \"not started\"\n  -- and \"does not exist\" are the same absence, and every reader has to know\n  -- the list of layers to tell them apart.\n  insert into public.imprint_layers (organisation_id, layer)\n  select p_organisation, l\n    from unnest(enum_range(null::public.imprint_layer)) as l\n  on conflict (organisation_id, layer) do nothing;\n\n  select * into result from public.imprint_records\n   where organisation_id = p_organisation;\n\n  return result;\nend $$;\n\ncomment on function public.ensure_imprint is\n  'Opens an Imprint and its eight layer rows. Idempotent, so calling it on every page load costs nothing.';\n\n-- One statement, so that \"the layers are answered\" and \"the model has been\n-- built\" cannot disagree, and so the audit entry is written in the same\n-- transaction as the thing it records.\ncreate or replace function public.complete_imprint(p_organisation uuid)\nreturns public.imprint_records\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  result public.imprint_records;\nbegin\n  if not amryn.has_permission(p_organisation, 'manage_organisation') then\n    raise exception 'only an administrator can finish the Imprint' using errcode = '42501';\n  end if;\n\n  update public.imprint_records\n     set completed_at   = coalesce(completed_at, now()),\n         initialised_at = coalesce(initialised_at, now()),\n         current_layer  = 'intent'\n   where organisation_id = p_organisation\n  returning * into result;\n\n  if not found then\n    raise exception 'that organisation has not started an Imprint' using errcode = 'P0002';\n  end if;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values\n    (p_organisation, auth.uid(), 'imprint.completed', 'organisation',\n     p_organisation::text, 'Imprint completed and the model initialised');\n\n  return result;\nend $$;\n\ncomment on function public.complete_imprint is\n  'Closes an Imprint and records it. One statement, so completion and the audit row cannot disagree.';\n\n-- Same reach as the record they replace: signed-in callers only.\nrevoke all on function public.ensure_imprint(uuid)   from public, anon;\nrevoke all on function public.complete_imprint(uuid) from public, anon;\ngrant execute on function public.ensure_imprint(uuid)   to authenticated;\ngrant execute on function public.complete_imprint(uuid) to authenticated;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 5. Bringing the old record across\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Nobody who has already answered the seven steps should be asked again.\n--\n-- Six of the old steps map onto a layer. Two of them — objectives and market —\n-- map onto the same one, Intent, so it counts as answered only if both were\n-- answered and skipped only if both were skipped; anything else is left\n-- unanswered, which is the truthful reading of \"half of it was done\".\n--\n-- Offer, Customers and Digital are new questions that were never asked, so\n-- they start unanswered for everybody. That is not a gap in the backfill; it\n-- is the reason the Imprint exists.\n--\n-- No score is written. The Quality Score is defined over fields the old record\n-- did not track, so any number here would be invented — and a made-up\n-- completeness figure is precisely the kind of thing that later gets quoted as\n-- a measurement.\n--\n-- ── why this is a function and not eight statements ───────────────────────\n-- A backfill is the part of a migration most likely to be wrong and least\n-- likely to be noticed, because it runs exactly once, against data the person\n-- writing it cannot see, and leaves no failure behind when it silently matches\n-- nothing. Written inline it is also untestable by construction: by the time\n-- any test runs, the migration has been applied and there is no old record\n-- left to bring across.\n--\n-- As a function it can be called again with fixtures in front of it, which is\n-- what supabase/tests/25 does. Every statement is guarded on the layer still\n-- being 'unanswered', so calling it a second time — after a customer has\n-- answered more — cannot overwrite what they said with what they used to say.\ncreate or replace function amryn.backfill_imprint_from_onboarding()\nreturns integer\nlanguage plpgsql\nvolatile\nsecurity definer\nset search_path = public, pg_temp\nas $backfill$\ndeclare\n  brought integer;\nbegin\n  insert into public.imprint_records (organisation_id, started_at, completed_at, initialised_at, current_layer)\n  select\n    p.organisation_id,\n    p.started_at,\n    p.completed_at,\n    p.initialised_at,\n    'identity'::public.imprint_layer\n  from public.onboarding_progress p\n  on conflict (organisation_id) do nothing;\n\n  get diagnostics brought = row_count;\n\n  insert into public.imprint_layers (organisation_id, layer)\n  select p.organisation_id, l\n    from public.onboarding_progress p\n   cross join unnest(enum_range(null::public.imprint_layer)) as l\n  on conflict (organisation_id, layer) do nothing;\n\n  -- The straightforward four, each old step onto one layer.\n  update public.imprint_layers t\n     set state       = 'answered',\n         answered_at = coalesce(p.completed_at, p.updated_at, now()),\n         answers     = coalesce(p.answers -> m.old_step, '{}'::jsonb)\n    from public.onboarding_progress p\n    join (values\n      ('identity',   'identity'),\n      ('structure',  'location'),\n      ('systems',    'operations'),\n      ('data',       'commercial')\n    ) as m(old_step, new_layer) on true\n   where t.organisation_id = p.organisation_id\n     and t.layer = m.new_layer::public.imprint_layer\n     and t.state = 'unanswered'\n     and m.old_step = any (p.completed_steps);\n\n  update public.imprint_layers t\n     set state = 'skipped'\n    from public.onboarding_progress p\n    join (values\n      ('structure',  'location'),\n      ('systems',    'operations'),\n      ('data',       'commercial')\n    ) as m(old_step, new_layer) on true\n   where t.organisation_id = p.organisation_id\n     and t.layer = m.new_layer::public.imprint_layer\n     and t.state = 'unanswered'\n     and m.old_step = any (p.skipped_steps);\n\n  -- Intent, which two old steps feed. Answered only if both were answered,\n  -- skipped only if both were skipped: \"half of it was done\" is not either.\n  update public.imprint_layers t\n     set state       = 'answered',\n         answered_at = coalesce(p.completed_at, p.updated_at, now())\n    from public.onboarding_progress p\n   where t.organisation_id = p.organisation_id\n     and t.layer = 'intent'\n     and t.state = 'unanswered'\n     and 'objectives' = any (p.completed_steps)\n     and 'market'     = any (p.completed_steps);\n\n  update public.imprint_layers t\n     set state = 'skipped'\n    from public.onboarding_progress p\n   where t.organisation_id = p.organisation_id\n     and t.layer = 'intent'\n     and t.state = 'unanswered'\n     and 'objectives' = any (p.skipped_steps)\n     and 'market'     = any (p.skipped_steps);\n\n  return brought;\nend $backfill$;\n\ncomment on function amryn.backfill_imprint_from_onboarding is\n  'Brings an organisation''s old seven-step record across to its Imprint. Idempotent and non-destructive: only layers still unanswered are touched, so a second call cannot overwrite what a customer has since said.';\n\nrevoke all on function amryn.backfill_imprint_from_onboarding() from public, anon, authenticated;\n\nselect amryn.backfill_imprint_from_onboarding();\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260906150000_25_provenance.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260906150000_25_provenance.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Amryn™ AIGrowthIntelligence® Software\n-- Migration 25 — Where a number came from, and how sure it is\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- This platform's entire claim is that it explains rather than describes. That\n-- claim survives exactly as long as a reader can tell a figure the business\n-- actually reported from a figure something inferred — and until now nothing\n-- in the schema could tell them apart. `impact_cents` on an insight and\n-- `impact_cents` on a recommendation are the same column type whether the\n-- number was added up from invoices or produced by a model with a plausible\n-- manner.\n--\n-- ── why a column and not a sentence ───────────────────────────────────────\n-- The tempting version writes \"estimated\" into the narrative. That fails three\n-- ways: it cannot be filtered on, it cannot be enforced, and it is the first\n-- thing lost when a figure is quoted onward into a board pack. A column is\n-- none of those. It travels with the number, a query can exclude everything\n-- uncertain, and — the part that matters most — the database can refuse to\n-- store an estimate that does not say how uncertain it is.\n--\n-- ── the four kinds ───────────────────────────────────────────────────────\n--   fact       the business reported it, or stated it about itself. A revenue\n--              figure from an import. The only kind that needs no defence.\n--   derived    arithmetic on facts, by an engine, deterministically. Gross\n--              margin from revenue and cost. Reproducible: run it again and it\n--              is the same number.\n--   estimated  inferred. Nobody measured it and it might be wrong. Requires a\n--              range, always.\n--   simulated  produced by a model run rather than observed. A Monte Carlo\n--              percentile. Requires a range for the same reason, and is kept\n--              distinct from `estimated` because a simulation can be re-run\n--              and an estimate cannot.\n--\n-- ── which tables ─────────────────────────────────────────────────────────\n-- The three that assert a money figure the business did not give us. Measured\n-- tables — financial_records, metric_values — are facts by construction and\n-- adding a column that would read 'fact' on every row would be noise pretending\n-- to be rigour.\n--\n-- All three are empty in production, so the constraints below are strict from\n-- the first row rather than accommodating a legacy nobody has to live with.\n\ncreate type public.provenance as enum ('fact', 'derived', 'estimated', 'simulated');\n\ncomment on type public.provenance is\n  'Where a number came from: reported, computed, inferred, or simulated. Mirrored in src/lib/provenance.ts.';\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- The rule, applied three times\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Four constraints per table, and each one closes a way of being misleading\n-- while appearing rigorous:\n--\n--   whole      three percentiles or none. Two is a half-drawn range that every\n--              reader completes differently.\n--   ordered    P10 ≤ P50 ≤ P90. A range that runs backwards is a transposition\n--              nobody notices because both numbers look reasonable.\n--   median     the headline figure *is* the P50. Otherwise a row carries two\n--              numbers both claiming to be the estimate, and a screen showing\n--              one beside a report showing the other is unexplainable.\n--   ranged     an estimate or a simulation with a figure must carry the range.\n--              This is the brief's rule, and it is here rather than in the\n--              application because a rule enforced by whoever remembers is not\n--              a rule.\n\nalter table public.business_insights\n  -- No default. The writer has to decide, which is the entire point of the\n  -- column — a default is a way of not deciding that still fills the field in.\n  add column provenance         public.provenance not null,\n  add column impact_p10_cents   bigint,\n  add column impact_p50_cents   bigint,\n  add column impact_p90_cents   bigint,\n  add constraint insight_interval_is_whole check (\n    (impact_p10_cents is null) = (impact_p50_cents is null)\n    and (impact_p50_cents is null) = (impact_p90_cents is null)\n  ),\n  add constraint insight_interval_is_ordered check (\n    impact_p10_cents is null\n    or (impact_p10_cents <= impact_p50_cents and impact_p50_cents <= impact_p90_cents)\n  ),\n  add constraint insight_headline_is_the_median check (\n    impact_p50_cents is null or impact_cents = impact_p50_cents\n  ),\n  add constraint insight_uncertainty_carries_a_range check (\n    provenance in ('fact', 'derived')\n    or impact_cents is null\n    or impact_p50_cents is not null\n  );\n\ncomment on column public.business_insights.provenance is\n  'Where the impact figure came from. An estimate or a simulation cannot be stored without a P10/P50/P90 range.';\n\nalter table public.ai_recommendations\n  add column provenance         public.provenance not null,\n  add column impact_p10_cents   bigint,\n  add column impact_p50_cents   bigint,\n  add column impact_p90_cents   bigint,\n  add constraint recommendation_interval_is_whole check (\n    (impact_p10_cents is null) = (impact_p50_cents is null)\n    and (impact_p50_cents is null) = (impact_p90_cents is null)\n  ),\n  add constraint recommendation_interval_is_ordered check (\n    impact_p10_cents is null\n    or (impact_p10_cents <= impact_p50_cents and impact_p50_cents <= impact_p90_cents)\n  ),\n  add constraint recommendation_headline_is_the_median check (\n    impact_p50_cents is null or impact_cents = impact_p50_cents\n  ),\n  add constraint recommendation_uncertainty_carries_a_range check (\n    provenance in ('fact', 'derived')\n    or impact_cents is null\n    or impact_p50_cents is not null\n  );\n\ncomment on column public.ai_recommendations.provenance is\n  'Where the impact figure came from. An estimate or a simulation cannot be stored without a P10/P50/P90 range.';\n\n-- Opportunities are the sharpest case. `estimated_value_cents` has the word in\n-- its name and could still be stored as a bare number with nothing saying how\n-- firm it was — a tender with a published contract value and a guess at what a\n-- new market might be worth were indistinguishable once written down.\nalter table public.opportunities\n  add column provenance       public.provenance not null,\n  add column value_p10_cents  bigint,\n  add column value_p50_cents  bigint,\n  add column value_p90_cents  bigint,\n  add constraint opportunity_interval_is_whole check (\n    (value_p10_cents is null) = (value_p50_cents is null)\n    and (value_p50_cents is null) = (value_p90_cents is null)\n  ),\n  add constraint opportunity_interval_is_ordered check (\n    value_p10_cents is null\n    or (value_p10_cents <= value_p50_cents and value_p50_cents <= value_p90_cents)\n  ),\n  add constraint opportunity_headline_is_the_median check (\n    value_p50_cents is null or estimated_value_cents = value_p50_cents\n  ),\n  add constraint opportunity_uncertainty_carries_a_range check (\n    provenance in ('fact', 'derived')\n    or estimated_value_cents is null\n    or value_p50_cents is not null\n  );\n\ncomment on column public.opportunities.provenance is\n  'Where the value came from. A published tender value is a fact; what a new market might be worth is an estimate, and cannot be stored without a range.';\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- An external claim has to say where it came from\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- market_signals is the only table holding assertions about the world outside\n-- the business, and `source_url` has always been nullable — so a signal could\n-- be stored saying anything at all, with no way to check it and nothing to show\n-- a reader who asks \"says who?\".\n--\n-- Not a check constraint, because a legitimate signal can come from somewhere\n-- with no URL: a phone call, a trade publication, something a customer\n-- mentioned. What cannot happen is a signal with no attribution of any kind.\n-- So the requirement is that *something* identifies the origin, and a new\n-- column carries the case a URL cannot.\nalter table public.market_signals\n  add column sourced_from text,\n  add constraint signal_says_where_it_came_from check (\n    source_url is not null or sourced_from is not null\n  );\n\ncomment on column public.market_signals.sourced_from is\n  'Where this came from when there is no URL to point at — a publication, a conversation, a filing. One of this and source_url must be present: an external claim nobody can attribute is a rumour.';\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260906180000_26_analysis_runs.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260906180000_26_analysis_runs.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 26. The analysis run\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Finishing an Imprint has, until now, recorded an audit row and done nothing\n-- else. The screens a customer then opens compute what they show inside the\n-- request that renders them: a health score over twelve rows, a trend over a\n-- year of orders. That is the right shape for a number a page can produce in\n-- forty milliseconds and the wrong shape for the thing this platform is\n-- actually selling — reading a whole business once, properly, and saying what\n-- it found.\n--\n-- That reading takes minutes rather than milliseconds, so it belongs in the\n-- queue built in #61. This migration is the record of one such reading.\n--\n-- ── why a run is a row and not just a job ─────────────────────────────────\n--\n-- job_runs already tracks attempts, leases and failures, and none of that is\n-- what a customer needs to know. They need to know that their business is\n-- being read, roughly how far along it is, what it concluded, and — the part\n-- that matters most — how much the platform is willing to stand behind what\n-- it concluded. A job row cannot answer the last of those without becoming a\n-- domain object in disguise.\n--\n-- So: job_runs stays infrastructure, analysis_runs is the domain object, and\n-- they point at each other. An operator debugging a stuck worker reads one; a\n-- customer asking \"what happened to my analysis\" reads the other.\n--\n-- ── the gate is stored, not recomputed ────────────────────────────────────\n--\n-- Below a Quality Score of 70 the analysis marks everything provisional and\n-- refuses to discuss expansion. That threshold is a judgement about what the\n-- platform may claim, and the score it reads moves — somebody answers three\n-- more fields the next morning and it crosses 70.\n--\n-- Recomputing the gate at read time would therefore change the standing of\n-- findings that were produced under the old score, retroactively, with nothing\n-- recording that it happened. So the score at the moment of the run, and both\n-- decisions taken from it, are frozen onto the row. A finding's caveat is a\n-- fact about how it was produced, not a fact about the business today.\n--\n-- Additive throughout: one enum, one table, three nullable columns and one\n-- boolean with a default on each output table, and a function replaced. No\n-- data is rewritten, so this needs no backup.\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 1. What state a reading is in\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Deliberately not public.job_status. That enum has 'cancelled', which is a\n-- thing an operator does to a queue entry, and no 'superseded', which is what\n-- happens to a reading when a newer one lands. The two lifecycles look alike\n-- today and would drift the first time either grew a state the other did not\n-- want.\ncreate type public.analysis_status as enum (\n  'queued',      -- accepted, waiting for a worker\n  'running',     -- a worker holds it\n  'succeeded',   -- finished, findings written\n  'failed',      -- finished, nothing written\n  'superseded'   -- a later run for this organisation replaced it\n);\n\ncomment on type public.analysis_status is\n  'The lifecycle of one reading of a business. Separate from job_status: that describes a queue entry, this describes a thing a customer is waiting for.';\n\ncreate table public.analysis_runs (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n\n  -- The queue entry doing the work. Null until enqueued, and null forever for\n  -- a run recorded by something other than the worker.\n  job_id           uuid references public.job_runs (id) on delete set null,\n\n  -- What asked for this reading. Text rather than an enum because the set will\n  -- grow with every trigger added, and a migration per trigger is a tax on\n  -- exactly the experiments this is for.\n  trigger          text not null check (trigger <> ''),\n\n  status           public.analysis_status not null default 'queued',\n\n  /*\n   * The Quality Score as it stood when the run started, and the two decisions\n   * taken from it.\n   *\n   * Null score means the Imprint had never been scored — which is its own\n   * answer, and is treated as failing the gate rather than passing it. An\n   * unscored Imprint is one the platform cannot see into, and the safe reading\n   * of \"I do not know how complete this is\" is not \"complete enough\".\n   */\n  quality_score        smallint check (quality_score is null or quality_score between 0 and 100),\n  is_provisional       boolean not null,\n  expansion_suppressed boolean not null,\n\n  started_at       timestamptz,\n  finished_at      timestamptz,\n  duration_ms      integer check (duration_ms is null or duration_ms >= 0),\n\n  -- What it produced. Counts rather than a join, so a list of past runs costs\n  -- one query.\n  insight_count        integer not null default 0 check (insight_count        >= 0),\n  recommendation_count integer not null default 0 check (recommendation_count >= 0),\n  opportunity_count    integer not null default 0 check (opportunity_count    >= 0),\n\n  /*\n   * What the analysis wanted and did not have.\n   *\n   * The brief's rule is that the model may never fill a numeric gap from\n   * memory. Somewhere has to hold what was missing, or \"we did not have it\"\n   * and \"it did not matter\" become the same silence — and the second is what a\n   * reader assumes.\n   */\n  gaps             jsonb not null default '[]'::jsonb,\n\n  error            text,\n\n  requested_by     uuid references auth.users (id) on delete set null,\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n\n  -- A run that has finished says when, and one that has not says nothing.\n  constraint finished_carries_a_time\n    check ((status in ('succeeded','failed','superseded')) = (finished_at is not null)),\n  -- Succeeding without an error, failing with one. A failed run whose error is\n  -- null is a run nobody can act on.\n  constraint outcome_and_error_agree\n    check ((status = 'failed') = (error is not null)),\n  -- Below the threshold, both consequences follow. Above it, neither does.\n  -- Written as a constraint because the alternative is trusting that every\n  -- writer applied the same rule, and the one that did not would be silent.\n  constraint gate_is_applied_consistently\n    check (is_provisional = expansion_suppressed)\n);\n\ncomment on table public.analysis_runs is\n  'One reading of a business, from a completed Imprint. Holds the Quality Score gate as it stood at the time, because a finding''s caveat is a fact about how it was produced rather than about the business today.';\ncomment on column public.analysis_runs.gaps is\n  'What the analysis needed and did not have, so that \"missing\" and \"irrelevant\" stay distinguishable.';\n\ncreate index analysis_runs_org_idx\n  on public.analysis_runs (organisation_id, created_at desc);\n\n-- Both other foreign keys get one too. Migration 22 covered every key in the\n-- schema for the same reason: without an index, deleting a parent scans this\n-- table to find the children, and the scan is invisible until the table is\n-- large. Partial, because both columns are usually null — a run recorded\n-- outside the worker has no job, and a scheduled one has no requester.\ncreate index analysis_runs_job_idx\n  on public.analysis_runs (job_id) where job_id is not null;\ncreate index analysis_runs_requested_by_idx\n  on public.analysis_runs (requested_by) where requested_by is not null;\n\n-- At most one reading in flight per organisation. A second is not an error —\n-- it waits, or supersedes — but two running at once would write two sets of\n-- findings over each other and leave whichever finished last.\ncreate unique index analysis_runs_one_in_flight\n  on public.analysis_runs (organisation_id)\n  where status in ('queued','running');\n\ncreate trigger analysis_runs_touch\n  before update on public.analysis_runs\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 2. Which reading produced a finding, and whether to trust it yet\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- analysis_run_id is the join. is_provisional is the same fact copied onto the\n-- row, and the duplication is deliberate — it is the argument from #65,\n-- applied again.\n--\n-- A caveat that lives only on a parent row survives exactly as long as nobody\n-- quotes the child. The moment a figure is lifted into a board pack, an email\n-- or a screenshot, the join is gone and the number reads as settled. The\n-- provenance column exists because a sentence in the narrative could not be\n-- filtered on; this exists because a caveat one join away cannot be either.\n--\n-- Existing rows are not provisional, which is true: they were produced before\n-- any gate existed, by engines running inside a request, and were never\n-- claimed to be the output of a gated reading.\nalter table public.business_insights\n  add column analysis_run_id uuid references public.analysis_runs (id) on delete set null,\n  add column is_provisional  boolean not null default false;\n\nalter table public.ai_recommendations\n  add column analysis_run_id uuid references public.analysis_runs (id) on delete set null,\n  add column is_provisional  boolean not null default false;\n\nalter table public.opportunities\n  add column analysis_run_id uuid references public.analysis_runs (id) on delete set null,\n  add column is_provisional  boolean not null default false;\n\ncomment on column public.business_insights.is_provisional is\n  'Produced by a run whose Imprint scored below 70. Copied from the run rather than joined, because a caveat one join away is lost the moment the figure is quoted onward.';\n\ncreate index business_insights_run_idx   on public.business_insights   (analysis_run_id) where analysis_run_id is not null;\ncreate index ai_recommendations_run_idx  on public.ai_recommendations  (analysis_run_id) where analysis_run_id is not null;\ncreate index opportunities_run_idx       on public.opportunities       (analysis_run_id) where analysis_run_id is not null;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 3. Who may see a run\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Readable by the organisation, writable by nobody through PostgREST. The\n-- worker holds a direct connection as the owner and does not pass through\n-- these policies; a browser has no business creating or editing a reading.\nalter table public.analysis_runs enable row level security;\nalter table public.analysis_runs force row level security;\n\ncreate policy analysis_runs_read on public.analysis_runs\n  for select using (amryn.is_member(organisation_id));\n\ngrant select on public.analysis_runs to authenticated;\n\n-- The lapsed-account guard, attached the same way as every other org-scoped\n-- table. Test 19 iterates the catalogue and fails on anything unguarded, so\n-- omitting this would be caught — but being caught by a test is not the same\n-- as being right, and a lapsed account should not accumulate readings.\ncreate trigger analysis_runs_refuse_lapsed\n  before insert or update on public.analysis_runs\n  for each row execute function amryn.refuse_lapsed_write();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 4. The switch\n-- ═══════════════════════════════════════════════════════════════════════════\ninsert into public.feature_flags (key, name, description) values\n  ('imprint_analysis',\n   'Analysis on Imprint completion',\n   'Whether finishing an Imprint queues a full reading of the business. Off means completion is recorded and nothing is queued, so no backlog accumulates for an organisation the analysis has never been tried on.')\non conflict (key) do nothing;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 5. Completion queues the reading\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Replaced rather than added beside, because the enqueue has to happen in the\n-- same transaction as the completion. Two statements from the application\n-- would leave a window where an Imprint is complete and nothing was queued —\n-- and that window is invisible, because the symptom is an analysis that never\n-- starts for a customer who did everything right.\n--\n-- The flag is read here rather than at claim time. claim_jobs already gates on\n-- background_jobs and would refuse the work anyway, but a queue filling with\n-- jobs nobody intends to run is a queue whose depth stops meaning anything.\ncreate or replace function public.complete_imprint(p_organisation uuid)\nreturns public.imprint_records\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  result     public.imprint_records;\n  -- Prefixed, because `job_id` is also a column on the table this updates and\n  -- plpgsql resolves the column first: `set job_id = job_id` would have been a\n  -- no-op that looked exactly like a link being written.\n  v_run_id   uuid;\n  v_job_id   uuid;\n  gate       boolean;\nbegin\n  if not amryn.has_permission(p_organisation, 'manage_organisation') then\n    raise exception 'only an administrator can finish the Imprint' using errcode = '42501';\n  end if;\n\n  update public.imprint_records\n     set completed_at   = coalesce(completed_at, now()),\n         initialised_at = coalesce(initialised_at, now()),\n         current_layer  = 'intent'\n   where organisation_id = p_organisation\n  returning * into result;\n\n  if not found then\n    raise exception 'that organisation has not started an Imprint' using errcode = 'P0002';\n  end if;\n\n  insert into public.audit_logs\n    (organisation_id, actor_id, action, entity_type, entity_id, summary)\n  values\n    (p_organisation, auth.uid(), 'imprint.completed', 'organisation',\n     p_organisation::text, 'Imprint completed and the model initialised');\n\n  if amryn.feature_enabled(p_organisation, 'imprint_analysis') then\n    -- An unscored Imprint fails the gate. See the column comment: not knowing\n    -- how complete something is cannot be treated as complete enough.\n    gate := coalesce(result.quality_score, 0) < 70;\n\n    -- A reading already in flight keeps its place. The partial unique index\n    -- would refuse a second one, and refusing here with a clear outcome beats\n    -- raising a constraint violation at somebody pressing \"finish\" twice.\n    if not exists (\n      select 1 from public.analysis_runs\n       where organisation_id = p_organisation\n         and status in ('queued','running')\n    ) then\n      insert into public.analysis_runs\n        (organisation_id, trigger, status, quality_score,\n         is_provisional, expansion_suppressed, requested_by)\n      values\n        (p_organisation, 'imprint.completed', 'queued', result.quality_score,\n         gate, gate, auth.uid())\n      returning id into v_run_id;\n\n      insert into public.job_runs\n        (organisation_id, kind, payload, singleton_key, max_attempts, requested_by)\n      values\n        (p_organisation, 'analysis.run',\n         jsonb_build_object('analysis_run_id', v_run_id),\n         'analysis:' || p_organisation::text,\n         2,\n         auth.uid())\n      returning id into v_job_id;\n\n      update public.analysis_runs set job_id = v_job_id where id = v_run_id;\n    end if;\n  end if;\n\n  return result;\nend $$;\n\ncomment on function public.complete_imprint is\n  'Closes an Imprint, records it, and queues the reading — one transaction, so a completed Imprint with nothing queued is not a state that can exist.';\n\nrevoke all on function public.complete_imprint(uuid) from public, anon;\ngrant execute on function public.complete_imprint(uuid) to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260906200000_27_external_radar_flag.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260906200000_27_external_radar_flag.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 27. The switch for looking outside\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Its own flag rather than riding on imprint_analysis, because the two carry\n-- different risks and should be switchable apart.\n--\n-- The analysis reads a business's own answers: it is arithmetic, it costs a\n-- few milliseconds, and it cannot say anything the customer did not already\n-- tell us. The radar leaves the building. Every run spends money on searches,\n-- takes minutes rather than milliseconds, and is the only part of this system\n-- that writes a claim about the world.\n--\n-- So an organisation can have the analysis without the radar, which is the\n-- combination to start with. Turning the radar on for one tenant and watching\n-- what it admits and rejects is how it earns being turned on for the rest.\n--\n-- Additive: one row in a catalogue. Nothing is altered.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ninsert into public.feature_flags (key, name, description) values\n  ('external_radar',\n   'External market research',\n   'Whether an analysis also searches the web for what is happening around this business. Off means the reading uses the Imprint and internal records only, and records the absence as a gap rather than leaving the radar silently empty. Costs money per run.')\non conflict (key) do nothing;\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260906220000_28_twin_fidelity.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260906220000_28_twin_fidelity.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 28. How wrong the Twin has been\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Phase 5 is the Digital Twin simulation: an agent-based daily model, Monte\n-- Carlo over five hundred iterations, P10/P50/P90 on every output. This\n-- migration is not that. It is the thing that decides whether any of it may be\n-- shown, and it comes first for the same reason provenance came before the\n-- analysis in #65 and the Quality Score gate came before the findings in #68.\n--\n-- A simulation produces numbers whatever you feed it. Five hundred iterations\n-- of a model with no grounding produce a beautifully tight confidence interval\n-- around a fiction, and the interval makes it look *more* trustworthy rather\n-- than less. The only thing that distinguishes a simulation worth reading from\n-- one worth ignoring is a measurement of how wrong it has been, and that\n-- measurement has to exist before the first simulated figure reaches a screen\n-- — because afterwards there is no moment at which anybody goes back to ask.\n--\n-- ── the rule ──────────────────────────────────────────────────────────────\n--\n-- A figure whose provenance is 'simulated' must point at the fidelity\n-- measurement that licenses it. Not a flag somebody sets; a foreign key the\n-- database requires. Without a measurement there is no row to point at, so a\n-- simulated figure cannot be written at all.\n--\n-- This is the third time this shape has been used here, and deliberately so:\n-- provenance made \"where did this come from\" unforgeable, is_provisional made\n-- \"how much do we believe it\" unforgeable, and this makes \"has this model ever\n-- been right\" unforgeable. Each was a sentence somebody could have written in\n-- a narrative and each is a column instead.\n--\n-- ── measured against what ─────────────────────────────────────────────────\n--\n-- Three held-out months, per the brief: the model is fitted without them and\n-- then asked to predict them, and the error is what it scores on. Held out\n-- rather than in-sample, because a model scored on the data it was fitted to\n-- is scored on its memory.\n--\n-- The organisation this ships to has one financial record and no business\n-- events. So the honest first answer is 'not_measurable', and the constraint\n-- below makes that the *only* answer available: a run cannot record a score\n-- without having had the months to earn it.\n--\n-- Additive: one enum, one table, one nullable column and one check on each of\n-- three tables, one flag. No existing row is touched — verified first: there\n-- are no rows with provenance 'simulated' anywhere.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate type public.fidelity_status as enum (\n  'not_measurable',  -- not enough history to hold three months out\n  'measured',        -- fitted, predicted, scored\n  'failed'           -- the measurement itself broke\n);\n\ncomment on type public.fidelity_status is\n  'Whether a Twin has ever been checked against reality. ''not_measurable'' is a real answer and the common one early on — it is not a failure.';\n\ncreate table public.twin_fidelity (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n\n  status           public.fidelity_status not null,\n\n  -- Complete months of history that existed when this was attempted, and how\n  -- many the method needs. Stored rather than recomputed: a score is a claim\n  -- about a moment, and the history behind it grows.\n  months_available smallint not null check (months_available >= 0),\n  months_required  smallint not null default 3 check (months_required > 0),\n\n  /*\n   * 0 to 100, and null unless it was actually measured.\n   *\n   * Null is not zero. Zero would mean \"we checked and it was hopeless\", which\n   * is a finding; null means \"nobody has checked\", which is a different thing\n   * entirely and the one a reader must not mistake for the other.\n   */\n  score            smallint check (score is null or score between 0 and 100),\n\n  -- What was compared, and how it was scored. Text rather than enums: the\n  -- method will change more often than a migration is worth, and a score whose\n  -- method is not recorded beside it cannot be compared with a later one.\n  metric           text,\n  method           text,\n  error_pct        numeric(6,3) check (error_pct is null or error_pct >= 0),\n  sample_size      integer check (sample_size is null or sample_size >= 0),\n\n  -- Why there is no score, in words a person can act on.\n  reason           text,\n\n  measured_at      timestamptz not null default now(),\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n\n  -- A score exists exactly when the status says it was measured.\n  constraint measured_carries_a_score\n    check ((status = 'measured') = (score is not null)),\n  -- And anything else says why not. A run that could not measure and does not\n  -- say why leaves somebody to guess, and they will guess \"no data\" whether or\n  -- not that was it.\n  constraint anything_else_says_why\n    check ((status = 'measured') = (reason is null)),\n  /*\n   * The one that carries the weight.\n   *\n   * A score cannot be recorded without the months it was earned on. Without\n   * this, a well-meaning backfill or an eager handler could write a fidelity\n   * of 90 against one month of data, and every simulated figure in the product\n   * would then be licensed by a measurement that measured almost nothing.\n   */\n  constraint enough_history_to_measure\n    check (status <> 'measured' or months_available >= months_required)\n);\n\ncomment on table public.twin_fidelity is\n  'How wrong this business''s Digital Twin has been, measured on months held out of its fitting. A simulated figure must point at one of these rows, so a Twin that has never been checked cannot publish a number.';\ncomment on column public.twin_fidelity.score is\n  'Null means nobody has checked. Zero means somebody checked and it was hopeless. A reader must never mistake the first for the second.';\n\ncreate index twin_fidelity_org_idx\n  on public.twin_fidelity (organisation_id, measured_at desc);\n\ncreate trigger twin_fidelity_touch\n  before update on public.twin_fidelity\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- The licence a simulated figure has to carry\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- `on delete restrict`, not `set null`. Deleting the measurement that licenses\n-- a figure must fail loudly rather than quietly leaving the figure behind with\n-- nothing standing behind it — which is the exact state this table exists to\n-- make impossible.\nalter table public.business_insights\n  add column fidelity_id uuid references public.twin_fidelity (id) on delete restrict,\n  add constraint simulated_figure_is_licensed\n    check (provenance <> 'simulated' or fidelity_id is not null);\n\nalter table public.ai_recommendations\n  add column fidelity_id uuid references public.twin_fidelity (id) on delete restrict,\n  add constraint simulated_figure_is_licensed\n    check (provenance <> 'simulated' or fidelity_id is not null);\n\nalter table public.opportunities\n  add column fidelity_id uuid references public.twin_fidelity (id) on delete restrict,\n  add constraint simulated_figure_is_licensed\n    check (provenance <> 'simulated' or fidelity_id is not null);\n\ncomment on column public.business_insights.fidelity_id is\n  'The fidelity measurement licensing this figure. Required when provenance is ''simulated'': a simulation nobody has checked may not put a number on a screen.';\n\ncreate index business_insights_fidelity_idx  on public.business_insights  (fidelity_id) where fidelity_id is not null;\ncreate index ai_recommendations_fidelity_idx on public.ai_recommendations (fidelity_id) where fidelity_id is not null;\ncreate index opportunities_fidelity_idx      on public.opportunities      (fidelity_id) where fidelity_id is not null;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Who may see it, and the switch\n-- ═══════════════════════════════════════════════════════════════════════════\n\nalter table public.twin_fidelity enable row level security;\nalter table public.twin_fidelity force row level security;\n\ncreate policy twin_fidelity_read on public.twin_fidelity\n  for select using (amryn.is_member(organisation_id));\n\ngrant select on public.twin_fidelity to authenticated;\n\ncreate trigger twin_fidelity_refuse_lapsed\n  before insert or update on public.twin_fidelity\n  for each row execute function amryn.refuse_lapsed_write();\n\ninsert into public.feature_flags (key, name, description) values\n  ('digital_twin_simulation',\n   'Digital Twin simulation',\n   'Whether the Twin runs simulations for this organisation. Off until its fidelity has been measured against held-out months — and a simulated figure cannot be written without a measurement to point at regardless, so this switch decides when to try rather than whether the result may be trusted.')\non conflict (key) do nothing;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260907090000_29_twin_scenarios.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260907090000_29_twin_scenarios.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 29. Scenarios, and the runs they produce\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- A scenario is a named question about the same business: what if demand rose\n-- a fifth, what if we charged ten per cent more, what does the next ninety days\n-- look like if nothing changes. The Twin answers all of them the same way, so\n-- the only thing a scenario holds is the levers and the horizon.\n--\n-- ── the licence, again, and one step earlier than #70 ─────────────────────\n--\n-- #70 required a published figure with provenance 'simulated' to name the\n-- fidelity measurement licensing it. That rule protects business_insights,\n-- ai_recommendations and opportunities — the tables a customer reads.\n--\n-- It leaves a hole this migration would otherwise open. Once simulation runs\n-- are stored in their own table, a screen can read that table directly, and\n-- every P10/P50/P90 in it would reach a reader without ever passing through\n-- the tables the gate protects.\n--\n-- So fidelity_id is `not null` here. A simulation may not even be *recorded*\n-- without naming the measurement standing behind it.\n--\n-- That is not the same as requiring a good measurement, or any measurement at\n-- all in the ordinary sense: a row saying 'not_measurable' is a perfectly\n-- valid thing to name, and for most businesses it is the only one available.\n-- The rule is that the question \"how wrong has this been?\" must have been\n-- asked and answered before a simulated figure exists, even if the answer was\n-- \"we cannot tell yet\". An unanswerable question and an unasked one look the\n-- same afterwards, and only one of them is honest.\n--\n-- ── five hundred iterations, in the database too ──────────────────────────\n--\n-- The engine refuses fewer. So does the column. Two enforcements of one rule\n-- because the engine's is a line somebody can edit and the column's is not,\n-- and a percentile from eighty samples is a number with a confidence interval\n-- nobody quoted.\n--\n-- Additive: two tables, one index, no change to anything existing.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.twin_scenarios (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n\n  name             text not null check (name <> ''),\n  description      text,\n\n  /*\n   * The levers, as multipliers on what the business already stated.\n   *\n   * Multipliers rather than absolute figures on purpose: a scenario that says\n   * \"revenue of R2m\" has quietly replaced the model with an assertion, while\n   * one that says \"a fifth more demand\" is still a question about this\n   * business. The first cannot be wrong; the second can, which is what makes\n   * it worth asking.\n   */\n  demand_multiplier numeric(6,3) not null default 1 check (demand_multiplier > 0),\n  price_multiplier  numeric(6,3) not null default 1 check (price_multiplier  > 0),\n\n  -- Three years is the ceiling. Past that the assumption that nothing outside\n  -- the business changes stops being a simplification and becomes a fiction.\n  horizon_days     integer not null default 90\n                     check (horizon_days between 1 and 1095),\n\n  -- \"Carry on as you are\". One per organisation, so every other scenario has\n  -- something to be compared against.\n  is_baseline      boolean not null default false,\n\n  created_by       uuid references auth.users (id) on delete set null,\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n\n  constraint scenario_name_is_unique_per_organisation unique (organisation_id, name)\n);\n\ncomment on table public.twin_scenarios is\n  'A named question about the same business, held as multipliers on figures the business itself stated. A scenario asserting an absolute revenue would have replaced the model with a claim.';\n\ncreate unique index twin_scenarios_one_baseline\n  on public.twin_scenarios (organisation_id) where is_baseline;\n\ncreate index twin_scenarios_org_idx\n  on public.twin_scenarios (organisation_id, created_at desc);\ncreate index twin_scenarios_created_by_idx\n  on public.twin_scenarios (created_by) where created_by is not null;\n\ncreate trigger twin_scenarios_touch\n  before update on public.twin_scenarios\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.twin_simulations (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n  scenario_id      uuid not null references public.twin_scenarios (id) on delete cascade,\n\n  -- Not null, and the reason is at the top of this file.\n  fidelity_id      uuid not null references public.twin_fidelity (id) on delete restrict,\n\n  -- The seed is what makes a result arguable. Without it a figure somebody\n  -- disagrees with cannot be reproduced, and the disagreement ends with the\n  -- simulation saying something else the second time.\n  seed             bigint not null,\n  iterations       integer not null check (iterations >= 500),\n  horizon_days     integer not null check (horizon_days > 0),\n\n  revenue_p10_cents bigint not null,\n  revenue_p50_cents bigint not null,\n  revenue_p90_cents bigint not null,\n  orders_per_day_p50 numeric(12,3),\n\n  -- What the model believed about variation while producing this. Carried with\n  -- the result rather than left in the source, so a figure can be read beside\n  -- the beliefs that made it.\n  assumptions      jsonb not null default '[]'::jsonb,\n\n  duration_ms      integer check (duration_ms is null or duration_ms >= 0),\n  ran_at           timestamptz not null default now(),\n  created_at       timestamptz not null default now(),\n\n  -- #65's rule, on this table too: a transposed interval reads as reasonable\n  -- from either end.\n  constraint simulation_interval_is_ordered\n    check (revenue_p10_cents <= revenue_p50_cents\n       and revenue_p50_cents <= revenue_p90_cents)\n);\n\ncomment on table public.twin_simulations is\n  'One run of the Twin. Records the seed so the result can be reproduced, and must name the fidelity measurement standing behind it — a run whose fidelity was never asked about cannot be stored.';\ncomment on column public.twin_simulations.fidelity_id is\n  'Required. A measurement reading ''not_measurable'' is a valid thing to name; never having asked is not.';\n\ncreate index twin_simulations_org_idx\n  on public.twin_simulations (organisation_id, ran_at desc);\ncreate index twin_simulations_scenario_idx\n  on public.twin_simulations (scenario_id, ran_at desc);\ncreate index twin_simulations_fidelity_idx\n  on public.twin_simulations (fidelity_id);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Who may see and shape them\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Scenarios are written by people, so they carry insert and update policies —\n-- unlike simulations, which only the worker produces and which nobody should\n-- be able to edit after the fact. A simulated result somebody adjusted by hand\n-- is worse than no simulation.\n\nalter table public.twin_scenarios   enable row level security;\nalter table public.twin_scenarios   force  row level security;\nalter table public.twin_simulations enable row level security;\nalter table public.twin_simulations force  row level security;\n\ncreate policy twin_scenarios_read on public.twin_scenarios\n  for select using (amryn.is_member(organisation_id));\n\ncreate policy twin_scenarios_write on public.twin_scenarios\n  for insert with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ncreate policy twin_scenarios_update on public.twin_scenarios\n  for update using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ncreate policy twin_scenarios_delete on public.twin_scenarios\n  for delete using (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ncreate policy twin_simulations_read on public.twin_simulations\n  for select using (amryn.is_member(organisation_id));\n\ngrant select, insert, update, delete on public.twin_scenarios to authenticated;\ngrant select on public.twin_simulations to authenticated;\n\ncreate trigger twin_scenarios_refuse_lapsed\n  before insert or update on public.twin_scenarios\n  for each row execute function amryn.refuse_lapsed_write();\ncreate trigger twin_simulations_refuse_lapsed\n  before insert or update on public.twin_simulations\n  for each row execute function amryn.refuse_lapsed_write();\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260907140000_30_request_simulation.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260907140000_30_request_simulation.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 30. Asking for a run\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- #72 gave the Twin an engine, storage, a handler and a nightly tick. What it\n-- did not give anybody was a way to ask. The only path into the queue was\n-- 02:30 UTC, so a person who changed a lever waited until the following\n-- morning to see what it did — which is not a studio, it is a subscription to\n-- yesterday's answer.\n--\n-- ── why a function rather than a policy ───────────────────────────────────\n--\n-- job_runs has no write policy and should not get one. A queue a browser can\n-- insert into directly is a queue anybody can fill with work of any kind, at\n-- any priority, for any tenant they can name — the row-level check would have\n-- to re-implement every rule about what a job may be, in a policy, where it\n-- cannot be read beside the rules it enforces.\n--\n-- So the same shape complete_imprint uses: one definer function that knows\n-- exactly which two jobs it is allowed to queue, and grants nothing else. It\n-- is the second and last thing in this schema that may put work in the queue\n-- on a person's behalf.\n--\n-- ── measure first, and only wait when there is something to wait for ──────\n--\n-- A simulation cannot be recorded without naming a fidelity measurement, so\n-- this queues the measurement the same way the nightly tick does — same key,\n-- so the two share one measurement per organisation per day rather than\n-- racing.\n--\n-- If that measurement was already taken today the simulation starts now. If\n-- this call is what queued it, the simulation waits ninety seconds. The delay\n-- is slack rather than synchronisation: the measurement is one grouped query\n-- and a pure function, and if it somehow has not finished the simulation\n-- refuses with a named reason and nothing is lost. What it must never do is\n-- assume a measurement probably exists.\n--\n-- ── once at a time, not once ever ─────────────────────────────────────────\n--\n-- The nightly tick uses dedupe_key: one run per scenario per night, ever.\n-- That is right for a schedule and wrong for a person, who edits a multiplier\n-- and asks again. This uses singleton_key instead — one run of a scenario in\n-- flight at a time, and the next may be asked for the moment it lands.\n--\n-- Worth knowing while reading a re-run: the seed is fixed per scenario per\n-- day, so asking twice on one day gives the same answer unless a lever\n-- changed. That is deliberate. It means a difference between two runs is the\n-- lever you moved rather than the dice, which is the only way a comparison\n-- means anything.\n--\n-- Additive: one function. Nothing existing is altered.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate or replace function public.request_simulation(\n  p_organisation uuid,\n  p_scenario     uuid\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_scenario_name text;\n  v_measurement   uuid;\n  v_simulation    uuid;\n  v_night         text := to_char(now() at time zone 'utc', 'YYYY-MM-DD');\n  v_delay         interval;\nbegin\n  -- The same permission that lets somebody write a scenario. Reading a result\n  -- needs only membership; spending a worker's time needs more.\n  if not amryn.has_permission(p_organisation, 'manage_organisation') then\n    raise exception 'only an administrator can run a scenario' using errcode = '42501';\n  end if;\n\n  -- The flag is checked here as well as at claim time. claim_jobs would refuse\n  -- the work anyway, but a person pressing a button deserves to be told the\n  -- Twin is off rather than to watch a job sit queued for ever.\n  if not amryn.feature_enabled(p_organisation, 'digital_twin_simulation') then\n    raise exception 'the Twin is not switched on for this organisation'\n      using errcode = 'P0002';\n  end if;\n\n  select name into v_scenario_name\n    from public.twin_scenarios\n   where id = p_scenario and organisation_id = p_organisation;\n\n  if v_scenario_name is null then\n    raise exception 'that scenario does not belong to this organisation'\n      using errcode = 'P0002';\n  end if;\n\n  /*\n   * The measurement, on the nightly tick's key so the two cannot both take it.\n   * `do nothing` returning no row means it was already queued or already run\n   * today, which is the good case rather than a failure.\n   */\n  insert into public.job_runs (organisation_id, kind, payload, dedupe_key, priority, requested_by)\n  values (p_organisation, 'twin.measure_fidelity', '{}'::jsonb,\n          'twin-fidelity:' || p_organisation::text || ':' || v_night, 40, auth.uid())\n  on conflict (dedupe_key) where dedupe_key is not null do nothing\n  returning id into v_measurement;\n\n  -- Only wait if this call is what started the measurement.\n  v_delay := case when v_measurement is null then interval '0' else interval '90 seconds' end;\n\n  insert into public.job_runs\n    (organisation_id, kind, payload, singleton_key, priority, run_at, requested_by)\n  values\n    (p_organisation, 'twin.simulate',\n     jsonb_build_object('scenario_id', p_scenario),\n     'twin-simulate:' || p_scenario::text,\n     50, now() + v_delay, auth.uid())\n  on conflict (singleton_key)\n    where singleton_key is not null and status in ('queued', 'running')\n    do nothing\n  returning id into v_simulation;\n\n  if v_simulation is null then\n    -- Already queued or running. Not an error: somebody pressed twice, or the\n    -- nightly tick got there first, and either way the answer is on its way.\n    return jsonb_build_object(\n      'status', 'already_running',\n      'scenario', v_scenario_name,\n      'measurement_queued', v_measurement is not null,\n      'starts_in_seconds', 0);\n  end if;\n\n  return jsonb_build_object(\n    'status', 'queued',\n    'scenario', v_scenario_name,\n    'simulation_job', v_simulation,\n    'measurement_queued', v_measurement is not null,\n    'starts_in_seconds', extract(epoch from v_delay)::int);\nend $$;\n\ncomment on function public.request_simulation is\n  'Queues one scenario for the Twin, on a person''s behalf. The second and last thing that may write to job_runs from a session, and it can queue exactly two kinds of job.';\n\nrevoke all on function public.request_simulation(uuid, uuid) from public, anon;\ngrant execute on function public.request_simulation(uuid, uuid) to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260907160000_31_daily_brief.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260907160000_31_daily_brief.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 31. The Daily Intelligence Brief\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Five sections, at most five items, every one of them pointing at the row it\n-- came from.\n--\n-- ── the gate is a foreign-key-shaped thing, not a habit ───────────────────\n--\n-- \"Every item traceable to its source record\" is the requirement, and the only\n-- version of that which survives contact with a busy morning is one the\n-- database enforces. So source_table and source_id are both `not null`. An\n-- item that cannot name the row it came from cannot be written at all.\n--\n-- This is the fourth time this schema has taken that shape and the reasoning\n-- has not changed: provenance made \"where did this come from\" unforgeable,\n-- is_provisional made \"how much do we believe it\" unforgeable, fidelity_id\n-- made \"has this model ever been right\" unforgeable. Each could have been a\n-- sentence in a narrative. Each is a column.\n--\n-- source_table is text rather than an enum, for the reason analysis_runs.trigger\n-- is: the set of things a brief may cite will grow with the product, and a\n-- migration per source is a tax on exactly the additions this is for.\n--\n-- ── at most five, and the cap is structural ───────────────────────────────\n--\n-- rank between 1 and 5, unique per brief. Two constraints that together make\n-- six items impossible rather than discouraged — a brief that quietly grew to\n-- eleven items on a bad week is a brief nobody finishes reading, and \"maximum\n-- five, ranked by impact\" enforced only in the generator is a comment.\n--\n-- ── the licence rule reaches here too ─────────────────────────────────────\n--\n-- #70 required a figure with provenance 'simulated' to name the fidelity\n-- measurement standing behind it, because a confidence interval reads as more\n-- trustworthy than a single number whether or not the model has ever been\n-- right. A brief is read by more people than any screen in the product and is\n-- forwarded by email, so the rule applies here more than anywhere: a simulated\n-- figure in a brief must carry its licence on the row, not one join away\n-- through the source it cites.\n--\n-- Additive: one enum, two tables, one flag. Nothing existing is altered.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate type public.brief_section as enum (\n  'yesterday',    -- real performance against what the Twin predicted\n  'today',        -- the single action that matters most\n  'radar',        -- external signal seen since the last brief\n  'open_items',   -- proposals awaiting the reader's verification\n  'trajectory'    -- progress against what the Intent layer said they wanted\n);\n\ncomment on type public.brief_section is\n  'The five things a morning brief answers. Ordered as a reader works through them: what happened, what to do, what changed outside, what is waiting on me, and am I getting there.';\n\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.daily_briefs (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n\n  -- The morning this brief is for, not the moment it was composed. A job that\n  -- runs late still produces Tuesday's brief.\n  brief_date       date not null,\n\n  job_id           uuid references public.job_runs (id) on delete set null,\n\n  item_count       integer not null default 0 check (item_count between 0 and 5),\n\n  /*\n   * What was looked at and found nothing, as opposed to not looked at.\n   *\n   * A brief with three items might have had two empty sections or two sections\n   * nobody ran. Those are different, and a reader will assume the first — so\n   * the sections that produced nothing are named, with why.\n   */\n  empty_sections   jsonb not null default '[]'::jsonb,\n\n  -- Delivery. Both null means it has not been attempted; one or the other, not\n  -- both, once it has.\n  emailed_at       timestamptz,\n  email_skipped    text,\n\n  generated_at     timestamptz not null default now(),\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n\n  constraint one_brief_per_morning unique (organisation_id, brief_date),\n  constraint delivery_is_one_thing_or_the_other\n    check (emailed_at is null or email_skipped is null)\n);\n\ncomment on table public.daily_briefs is\n  'One morning''s brief for one organisation. Dated by the morning it is for rather than the moment it was composed, so a job that runs late still produces the right day''s brief.';\ncomment on column public.daily_briefs.empty_sections is\n  'Sections that ran and found nothing, with the reason. Without it a short brief and an unfinished one look identical.';\n\ncreate index daily_briefs_org_idx\n  on public.daily_briefs (organisation_id, brief_date desc);\ncreate index daily_briefs_job_idx\n  on public.daily_briefs (job_id) where job_id is not null;\n\ncreate trigger daily_briefs_touch\n  before update on public.daily_briefs\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.brief_items (\n  id               uuid primary key default gen_random_uuid(),\n  brief_id         uuid not null references public.daily_briefs (id) on delete cascade,\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n\n  section          public.brief_section not null,\n\n  -- 1 is the most important thing on the page. See the note at the top for why\n  -- the ceiling is a constraint rather than a convention.\n  rank             smallint not null check (rank between 1 and 5),\n\n  headline         text not null check (headline <> ''),\n  detail           text not null check (detail <> ''),\n\n  -- What it is worth, where that can honestly be said. Null is a real answer:\n  -- a signal on the radar has no rand figure and inventing one would be the\n  -- exact failure the provenance column exists to prevent.\n  impact_cents     bigint,\n\n  provenance       public.provenance not null,\n\n  /*\n   * The gate. Both not null, so an item that cannot name the row it came from\n   * cannot exist.\n   *\n   * For an item comparing an aggregate against a prediction, the cited row is\n   * the prediction — a real row with an id — and the aggregate beside it is\n   * marked 'derived'. That is the honest reading: the aggregate has no single\n   * record to point at, and pretending otherwise would be a citation that\n   * resolves to nothing.\n   */\n  source_table     text not null check (source_table <> ''),\n  source_id        uuid not null,\n\n  -- #70's rule, on the table a brief is read from and forwarded out of.\n  fidelity_id      uuid references public.twin_fidelity (id) on delete restrict,\n\n  created_at       timestamptz not null default now(),\n\n  constraint one_item_per_rank unique (brief_id, rank),\n  constraint simulated_figure_is_licensed\n    check (provenance <> 'simulated' or fidelity_id is not null)\n);\n\ncomment on table public.brief_items is\n  'One line in a morning brief. source_table and source_id are both required: an item that cannot name the record it came from is an assertion, and a brief of assertions is a newsletter.';\ncomment on column public.brief_items.rank is\n  '1 is the most important thing on the page. Unique per brief and capped at five, so a brief nobody finishes reading is not a state that can exist.';\ncomment on column public.brief_items.impact_cents is\n  'Null is a real answer. A radar signal has no rand figure, and inventing one is the failure provenance exists to prevent.';\n\ncreate index brief_items_brief_idx\n  on public.brief_items (brief_id, rank);\ncreate index brief_items_org_idx\n  on public.brief_items (organisation_id, created_at desc);\ncreate index brief_items_fidelity_idx\n  on public.brief_items (fidelity_id) where fidelity_id is not null;\n-- Reading back the other way: \"what has this recommendation appeared in?\"\ncreate index brief_items_source_idx\n  on public.brief_items (source_table, source_id);\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Who may see one\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Readable by the organisation, writable by nobody through PostgREST. The\n-- worker composes briefs over a direct connection; a browser has no business\n-- editing what a brief said it found.\n\nalter table public.daily_briefs enable row level security;\nalter table public.daily_briefs force  row level security;\nalter table public.brief_items  enable row level security;\nalter table public.brief_items  force  row level security;\n\ncreate policy daily_briefs_read on public.daily_briefs\n  for select using (amryn.is_member(organisation_id));\n\ncreate policy brief_items_read on public.brief_items\n  for select using (amryn.is_member(organisation_id));\n\ngrant select on public.daily_briefs to authenticated;\ngrant select on public.brief_items  to authenticated;\n\ncreate trigger daily_briefs_refuse_lapsed\n  before insert or update on public.daily_briefs\n  for each row execute function amryn.refuse_lapsed_write();\ncreate trigger brief_items_refuse_lapsed\n  before insert or update on public.brief_items\n  for each row execute function amryn.refuse_lapsed_write();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- The switch\n-- ═══════════════════════════════════════════════════════════════════════════\n\ninsert into public.feature_flags (key, name, description) values\n  ('daily_brief',\n   'Daily Intelligence Brief',\n   'Whether a brief is composed each morning for this organisation and, where mail is configured, emailed. Off means no brief is composed, so nothing accumulates for an organisation nobody is reading it for.')\non conflict (key) do nothing;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260909200000_32_proposals.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260909200000_32_proposals.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 32. Proposals: what the Assistant may write, and what it may not\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Change 6 lets the Assistant \"adjust Twin parameters as proposals, fill\n-- Imprint fields, and run scenarios\". This is the table that makes the word\n-- \"proposals\" mean something, and it comes before the Assistant that writes\n-- into it for the same reason the fidelity gate came before the simulation:\n-- afterwards there is no moment at which anybody goes back and adds the\n-- restraint.\n--\n-- ── nothing here is applied by anything ───────────────────────────────────\n--\n-- A proposal changes nothing. It records that something was suggested, what it\n-- would change, from what to what, and why. A person accepts it, and the\n-- accepting is what writes — through the ordinary path, with the ordinary\n-- permission, leaving the ordinary audit row.\n--\n-- That is a product decision rather than a technical one, and it is the whole\n-- point: the Imprint is the record every figure in this platform derives from.\n-- A model that can edit it can edit the basis of every number the platform\n-- will ever show, and no amount of care in a prompt is a control. The control\n-- is that the write requires a person.\n--\n-- ── a proposal cites, like everything else here ───────────────────────────\n--\n-- rationale is `not null` and non-empty. A suggestion with no stated reason is\n-- one a reader can only accept on trust, and this platform's entire claim is\n-- that it explains rather than asserts. Fourth or fifth time this argument has\n-- produced a column rather than a convention, and it has not got weaker.\n--\n-- ── why status is not just a boolean ──────────────────────────────────────\n--\n-- 'declined' has to be distinguishable from 'still waiting', or the same\n-- suggestion is made again next week and the person who already said no says\n-- it again. 'superseded' exists because the underlying figure moves: a\n-- proposal to change a value that has since changed by other means is not\n-- something to accept or decline, it is something that stopped applying.\n--\n-- Additive: one enum, one table. Nothing existing is altered.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate type public.proposal_status as enum (\n  'pending',     -- waiting for a person\n  'accepted',    -- a person applied it\n  'declined',    -- a person said no; do not raise it again\n  'superseded'   -- the thing it referred to moved on\n);\n\ncomment on type public.proposal_status is\n  'Declined is deliberately distinct from pending: without it the same suggestion is put to somebody who has already refused it.';\n\ncreate table public.proposals (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n\n  /*\n   * What it wants to change, as a table and a column and a row.\n   *\n   * Text rather than an enum, for the reason analysis_runs.trigger is text:\n   * the set of things worth proposing will grow, and a migration per kind is a\n   * tax on exactly the additions this exists for. The application decides what\n   * it knows how to apply; anything else stays pending and is visible as\n   * something nobody can action, which is the honest state.\n   */\n  target_table     text not null check (target_table <> ''),\n  target_id        uuid,\n  target_field     text not null check (target_field <> ''),\n\n  /*\n   * From what, to what — both as text, because a proposal spans a numeric Twin\n   * multiplier and a free-text Imprint answer and must render the same either\n   * way. current_value is null when the field is genuinely empty, which is the\n   * commonest case for an Imprint gap and is not the same as an empty string.\n   */\n  current_value    text,\n  proposed_value   text not null,\n\n  -- Never optional. See the note at the top.\n  rationale        text not null check (rationale <> ''),\n\n  -- Where it came from: the conversation, so a reader can go and see what was\n  -- being discussed when this was suggested.\n  conversation_id  uuid references public.ai_conversations (id) on delete set null,\n\n  status           public.proposal_status not null default 'pending',\n\n  proposed_by      uuid references auth.users (id) on delete set null,\n  decided_by       uuid references auth.users (id) on delete set null,\n  decided_at       timestamptz,\n  -- Why it was declined, for the person who wonders in six months.\n  decision_note    text,\n\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n\n  -- A decision has a time and a time has a decision. A row that says\n  -- 'declined' with no moment attached cannot be ordered against anything.\n  constraint decided_carries_a_time\n    check ((status in ('accepted','declined','superseded')) = (decided_at is not null)),\n\n  -- The same suggestion, once, while it is waiting. A second identical\n  -- proposal is not new information, and two of them in a list is how a person\n  -- learns to stop reading the list.\n  constraint proposal_moves_something\n    check (current_value is distinct from proposed_value)\n);\n\ncomment on table public.proposals is\n  'Something the platform suggests changing, waiting on a person. Nothing applies one automatically: the Imprint is what every figure derives from, and the control on a model editing it is that the write requires a human, not that the prompt asks nicely.';\ncomment on column public.proposals.rationale is\n  'Required. A suggestion with no stated reason can only be accepted on trust, which is the opposite of what this platform claims to do.';\ncomment on column public.proposals.current_value is\n  'Null means the field is empty — the ordinary case for an Imprint gap, and not the same as an empty string.';\n\ncreate unique index proposals_one_pending_per_field\n  on public.proposals (organisation_id, target_table, target_field, coalesce(target_id, '00000000-0000-0000-0000-000000000000'::uuid))\n  where status = 'pending';\n\ncreate index proposals_org_idx\n  on public.proposals (organisation_id, status, created_at desc);\ncreate index proposals_conversation_idx\n  on public.proposals (conversation_id) where conversation_id is not null;\ncreate index proposals_proposed_by_idx\n  on public.proposals (proposed_by) where proposed_by is not null;\ncreate index proposals_decided_by_idx\n  on public.proposals (decided_by) where decided_by is not null;\n\ncreate trigger proposals_touch\n  before update on public.proposals\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Who may see one, raise one, and decide one\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Reading is membership: a proposal is a thing about the business and everyone\n-- who can see the business can see what has been suggested about it.\n--\n-- Raising one needs only membership too, and that is deliberate. A proposal\n-- changes nothing, and a colleague who spots a wrong figure should be able to\n-- say so without an administrator's rights. What needs the rights is deciding.\n--\n-- There is no delete policy. A proposal that was declined is a record that it\n-- was declined, and removing it is how the same argument gets had twice.\n\nalter table public.proposals enable row level security;\nalter table public.proposals force  row level security;\n\ncreate policy proposals_read on public.proposals\n  for select using (amryn.is_member(organisation_id));\n\ncreate policy proposals_raise on public.proposals\n  for insert with check (amryn.is_member(organisation_id));\n\ncreate policy proposals_decide on public.proposals\n  for update using (amryn.has_permission(organisation_id, 'manage_organisation'))\n  with check (amryn.has_permission(organisation_id, 'manage_organisation'));\n\ngrant select, insert, update on public.proposals to authenticated;\n\ncreate trigger proposals_refuse_lapsed\n  before insert or update on public.proposals\n  for each row execute function amryn.refuse_lapsed_write();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- The switch\n-- ═══════════════════════════════════════════════════════════════════════════\n\ninsert into public.feature_flags (key, name, description) values\n  ('assistant_proposals',\n   'Assistant may raise proposals',\n   'Whether the Assistant may suggest changes to the Imprint and the Twin. Off means it answers questions and suggests nothing. It can never apply a change either way — accepting is a person''s action.')\non conflict (key) do nothing;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260909210000_33_worker_heartbeat.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260909210000_33_worker_heartbeat.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 33. The worker says it is alive\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Phase 7 is production: monitoring, error tracking, backups, rate limits,\n-- cost controls. This is the monitoring gap that cost an evening.\n--\n-- The worker was down twice for a combined thirty-five minutes and the only\n-- reason anybody knew was that somebody happened to open the deployment\n-- dashboard. /api/health answered \"ok\" throughout, because it checks the web\n-- service and the database and has never had anything to say about the worker.\n-- Every schedule stopped — the nightly Twin run, the morning brief, the sweep,\n-- the rate-limit prune — and the product reported itself healthy.\n--\n-- ── why a heartbeat rather than reading job_runs ──────────────────────────\n--\n-- The obvious check is \"when did a job last finish?\", and it is wrong. This\n-- queue is quiet by design: the prune is hourly, the sweep and both nightly\n-- ticks are daily. Between 03:31 and 20:00 a perfectly healthy worker touches\n-- nothing, so a silence-based check either alerts every night or is set so\n-- loose it would have missed tonight entirely.\n--\n-- A heartbeat separates \"nothing to do\" from \"nobody to do it\". The worker\n-- writes on every poll whether or not it claimed anything, so the reading is\n-- unambiguous: fresh means alive, stale means gone, and the threshold can be\n-- tight because the poll is five seconds.\n--\n-- ── one row per worker, not one per beat ──────────────────────────────────\n--\n-- Upserted on the worker's own id. A row per beat would be seventeen thousand\n-- rows a day per worker to answer a question about the newest one, and the\n-- pruning job would then need pruning.\n--\n-- Dead workers are left rather than deleted. A row saying a worker was last\n-- seen at 19:31 is the record of an outage, and the check reads the freshest\n-- one — so an old row is evidence, not noise.\n--\n-- Additive: one table. Nothing existing is altered.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.worker_heartbeats (\n  -- The worker's own id: host, pid and a random suffix. Not a uuid, because\n  -- it has to be readable in a log line beside the beat it explains.\n  worker_id       text primary key check (worker_id <> ''),\n\n  last_seen_at    timestamptz not null default now(),\n  started_at      timestamptz not null default now(),\n\n  -- What it believes it can run. A worker beating happily with a stale handler\n  -- list is a deploy that did not take, which looks identical to a healthy one\n  -- from every other angle.\n  handlers        text[] not null default '{}',\n\n  -- How many jobs it had in flight when it last beat. Zero is the usual and\n  -- correct answer on this queue; it is here so a worker wedged on one job\n  -- looks different from an idle one.\n  in_flight       integer not null default 0 check (in_flight >= 0),\n\n  /*\n   * The commit the worker is running.\n   *\n   * Two services deploy from one image, and they can end up on different\n   * commits when one build fails — which is invisible until a handler the web\n   * service expects is not there. Null when the deployment does not say.\n   */\n  revision        text,\n\n  created_at      timestamptz not null default now(),\n  updated_at      timestamptz not null default now(),\n\n  constraint started_before_seen check (started_at <= last_seen_at)\n);\n\ncomment on column public.worker_heartbeats.handlers is\n  'What the worker believes it can run. A fresh beat carrying a stale handler list is a deploy that did not take, which looks healthy from every other angle.';\n\ncreate index worker_heartbeats_freshest\n  on public.worker_heartbeats (last_seen_at desc);\n\ncreate trigger worker_heartbeats_touch\n  before update on public.worker_heartbeats\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Who may see one\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Nobody, through PostgREST. This is not a tenant's data — it is the\n-- platform's own plumbing, and it names hosts and process ids. The worker\n-- writes it over a direct connection as the owner; the diagnostics page reads\n-- it the same way, which is how every other operator-only check here works.\n--\n-- RLS is enabled with no policy at all, which is the strongest available\n-- statement: not \"members only\", but \"no session, ever\".\n\nalter table public.worker_heartbeats enable row level security;\nalter table public.worker_heartbeats force  row level security;\n\ncomment on table public.worker_heartbeats is\n  'One row per worker process, upserted on every poll. Separates \"nothing to do\" from \"nobody to do it\". RLS is on with no policy: this is platform plumbing naming hosts and pids, readable only over a direct connection.';\n\n-- Revoked explicitly, rather than relied on being absent.\n--\n-- Migration 09 sets default privileges that grant select, insert, update and\n-- delete to `authenticated` on every new table in this schema — so \"we simply\n-- did not grant anything\" is not true here and never was. Without this revoke\n-- the only thing standing between a signed-in caller and this table is the\n-- absence of a policy, which protects it but for a reason nobody reading this\n-- file would see.\n--\n-- With both, a session is refused at the privilege check and again at the\n-- policy check, and neither depends on somebody remembering migration 09.\nrevoke all on public.worker_heartbeats from authenticated, anon;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260909220000_34_schema_drift.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260909220000_34_schema_drift.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 34. A worker that knows the database is behind it\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Phase 7, promotion. The failure this closes has now happened twice.\n--\n-- Both times the worker deployed before its migrations were applied, so it\n-- came up carrying handlers that referenced tables the database did not yet\n-- have. twin.nightly claimed, ran, and failed on `relation\n-- \"public.twin_scenarios\" does not exist` — three times, until it had spent\n-- every attempt it was allowed. The migration was applied by hand a few\n-- minutes later, at which point the job was permanently failed and stayed\n-- that way: the queue had already given up on work that would now have\n-- succeeded, and somebody had to reset the row by hand to get it back.\n--\n-- Nothing about that was a code fault. The handler was right, the schema was\n-- right, and they were right at different times.\n--\n-- ── the fix is ordering; this column is what makes the ordering visible ───\n--\n-- The ordering is enforced outside the database, by applying migrations\n-- before the new worker is allowed to start. But a deploy step can be\n-- removed, skipped, or silently fail, and the whole lesson of the last two\n-- evenings is that a control nothing reports on is a control nobody knows\n-- has stopped working.\n--\n-- So the worker also decides for itself. It ships with the list of migrations\n-- its build was made from, compares that against the ledger on every poll,\n-- and while the database is behind it declines to claim anything rather than\n-- claiming work it cannot do. Waiting costs a few seconds. Claiming costs the\n-- job its attempts, and someone an evening.\n--\n-- What is recorded here is what it found, so the state is legible from\n-- outside the process — /diagnostics reads this column and names the missing\n-- files. Empty is the healthy answer and the default, so a worker on an older\n-- build that never writes it reads as healthy rather than as alarming.\n--\n-- Additive: one column with a default. Nothing existing is altered.\n-- ═══════════════════════════════════════════════════════════════════════════\n\nalter table public.worker_heartbeats\n  add column if not exists pending_migrations text[] not null default '{}';\n\ncomment on column public.worker_heartbeats.pending_migrations is\n  'Migrations this worker''s build carries that the database has not recorded. Non-empty means the worker is ahead of the schema and is deliberately not claiming jobs. Empty is healthy.';\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260910070000_35_backups.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260910070000_35_backups.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 35. A record of every backup that was actually taken\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Phase 7, backups. The procedure has existed since migration 25:\n-- scripts/backup.mjs takes a dump, verifies it is complete, counts what it\n-- captured, and writes a manifest; scripts/migrate.mjs refuses a migration\n-- that is not purely additive unless that manifest is recent and intact.\n--\n-- All of which protects migrations, and none of which answers the question\n-- somebody asks after a disaster: **is there a backup, and how old is it?**\n--\n-- Until now the only evidence a backup ever happened was a file on whichever\n-- machine took it. Nothing in the platform knew. \"We have backups\" was an\n-- assumption, and the failure mode of an assumption is that it is discovered\n-- to be false at the worst possible moment.\n--\n-- ── why a table rather than reading the files ─────────────────────────────\n--\n-- The files are not here. They are on an operator's machine by design — the\n-- deployment container's filesystem is discarded, which backup.mjs says in\n-- its own error message. So the platform cannot inspect them; it can only be\n-- told. This is where it is told.\n--\n-- A row is written when a dump completes and verifies, never before. A row\n-- therefore means: at this moment, a complete dump of this database existed,\n-- of this size, containing these rows. What it cannot promise is that the\n-- file still exists — see stored_at, and the note on restore below.\n--\n-- ── what the row is for ───────────────────────────────────────────────────\n--\n-- /diagnostics reads the newest one and reports its age. That turns silence\n-- into a statement: no backup in nine days is a sentence somebody can act on,\n-- where an empty backups directory on a laptop nobody has opened is not.\n--\n-- Additive: one table.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.backups (\n  id               uuid primary key default gen_random_uuid(),\n\n  -- When the dump was taken, not when the row was written. They differ when a\n  -- backup is recorded after the fact, and the first is the one that matters.\n  taken_at         timestamptz not null,\n\n  /*\n   * Which database this is a backup *of*.\n   *\n   * The digest of host and database name, from backup-manifest.mjs — never the\n   * connection string, which carries a password. Without this a staging dump\n   * and a production dump are indistinguishable rows, and the reassuring one\n   * is always the wrong one.\n   */\n  database_digest  text not null check (database_digest <> ''),\n  database_label   text not null check (database_label <> ''),\n\n  bytes            bigint not null check (bytes > 0),\n\n  -- pg_dump's own output, hashed. Two rows with one checksum are one backup\n  -- recorded twice, not two backups.\n  sha256           text not null check (char_length(sha256) = 64),\n\n  -- The client that produced it. A dump taken by a pg_dump older than the\n  -- server can omit what it does not know about, so which one took it is part\n  -- of what the backup is.\n  pg_dump_version  text not null check (pg_dump_version <> ''),\n\n  /*\n   * What was captured, counted from the dump itself rather than from the\n   * database — so the figures describe the file, not the intention.\n   *\n   * Zero organisations in a backup of a live system is the number worth\n   * noticing before trusting it, which is why this is stored rather than\n   * summarised away.\n   */\n  rows             jsonb not null default '{}'::jsonb,\n\n  /*\n   * Where the operator put it. A path on a machine, or wherever it was moved\n   * to afterwards.\n   *\n   * Deliberately free text and deliberately not trusted: the platform cannot\n   * see that filesystem, so this records what it was told and nothing more. A\n   * row does not prove the file is still there — only that it once was.\n   */\n  stored_at        text not null check (stored_at <> ''),\n\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n\n  -- One backup of one database at one instant is one row, however many times\n  -- it is reported.\n  constraint one_row_per_backup unique (database_digest, taken_at)\n);\n\ncomment on table public.backups is\n  'One row per completed, verified database dump. Written by scripts/backup.mjs after the dump passes its completion check. /diagnostics reads the newest to report how old the last backup is. A row proves a backup existed, not that the file still does.';\n\ncomment on column public.backups.rows is\n  'Row counts read out of the dump itself. Zero organisations in a backup of a live system is the figure worth noticing before trusting it.';\n\ncomment on column public.backups.stored_at is\n  'Where the operator said they put it. Not verifiable from here — the platform cannot see that filesystem.';\n\ncreate index backups_newest on public.backups (database_digest, taken_at desc);\n\ncreate trigger backups_touch\n  before update on public.backups\n  for each row execute function amryn.touch_updated_at();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Who may see one\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Nobody, through PostgREST — the same treatment as worker_heartbeats, for the\n-- same reason and with one more. This is platform plumbing rather than a\n-- tenant's data, and it names hosts, file paths and how many organisations\n-- exist. A signed-in customer learning the size of the customer base from a\n-- diagnostics table is a leak, however small.\n--\n-- RLS on with no policy at all, plus the explicit revoke: migration 09 grants\n-- select, insert, update and delete to `authenticated` by default on every new\n-- table in this schema, so the absence of a policy is not on its own the whole\n-- defence and never was.\n\nalter table public.backups enable row level security;\nalter table public.backups force  row level security;\n\nrevoke all on public.backups from authenticated, anon;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260910120000_36_pricing_and_connector_entitlements.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260910120000_36_pricing_and_connector_entitlements.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 36. The 2026 price list, and the entitlements connectors will need\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Two changes that belong together because the second is what the first is\n-- charging for.\n--\n-- ── the price list ───────────────────────────────────────────────────────\n--\n-- Starter R999 → R1,499, Growth R3,999 → R4,999, Professional R9,999 →\n-- R12,999, Enterprise from a single R20,000 to a negotiated R25,000–R75,000.\n--\n-- No price is hardcoded anywhere in the application — the billing page reads\n-- subscription_plans and always has — so this is the whole of the repricing.\n-- That was a deliberate decision made in migration 16 and it is the reason\n-- this migration is nine lines of update rather than a search through forty\n-- components.\n--\n-- ── two things the table could not say ───────────────────────────────────\n--\n-- **A negotiated range.** Enterprise is quoted per contract, and one\n-- price_cents_monthly column can only hold the floor. It has been holding\n-- R20,000 and the sales conversation has been carrying the rest, which means\n-- the number on the page has never been the number anyone pays. A ceiling\n-- column lets the page say \"R25,000 to R75,000+\" and mean it.\n--\n-- **Implementation fees.** These exist commercially and have never existed in\n-- the schema — not a column, not a table, not a line of interface. A customer\n-- on Growth is quoted somewhere between R7,500 and R20,000 to be set up, and\n-- until now the only place that lived was in a person's head. A range per\n-- tier, because the fee genuinely varies with how much of the customer's\n-- estate has to be connected, and a single number would be a fiction.\n--\n-- ── eight new entitlements, and the six that already existed ────────────\n--\n-- The connector brief asked for fifteen entitlement keys. Six of them are\n-- already here under Amryn's own names — opportunity_pipeline is the\n-- Opportunity Radar, custom_reports is advanced reporting, ai_assistant and\n-- ai_credits together are the AI tier, and branches, api_access and sso are\n-- themselves. Adding second keys for those would split enforcement across two\n-- vocabularies, and the half of the application that checked the older name\n-- would silently keep working while the other half diverged.\n--\n-- So eight are added — the seven asked for plus digital_twin, which the\n-- brief lists and which has until now been gated by a feature flag rather\n-- than by what anybody bought — and the rest are mapped to what exists.\n--\n-- max_connections is deliberately NOT among them: data_sources is already the\n-- quota for \"how many systems may feed the platform\", already carries\n-- per-plan ceilings, and is already displayed on the billing page. A second\n-- key counting the same thing is how two limits come to disagree.\n--\n-- ── Professional loses unlimited sources ─────────────────────────────────\n--\n-- From null (no limit) to 20. This is a reduction and it is the one change\n-- here that could take something away from somebody, so: no organisation is\n-- on Professional today — the only subscription in the database is not — and\n-- nothing is withdrawn from anyone. Recorded plainly rather than left for\n-- someone to discover in a diff.\n--\n-- Additive throughout: three new columns, eight new catalogue rows, and\n-- updates to values. No drop, no destructive alter, nothing removed.\n-- ═══════════════════════════════════════════════════════════════════════════\n\n-- ── a ceiling for negotiated pricing, and the implementation fee ─────────\n\nalter table public.subscription_plans\n  add column if not exists price_cents_monthly_max   integer,\n  add column if not exists implementation_fee_cents_min integer,\n  add column if not exists implementation_fee_cents_max integer;\n\ncomment on column public.subscription_plans.price_cents_monthly_max is\n  'Upper bound of a negotiated range. Null where the published monthly price is the price.';\ncomment on column public.subscription_plans.implementation_fee_cents_min is\n  'One-off setup fee, lower bound. Null where implementation is not charged.';\ncomment on column public.subscription_plans.implementation_fee_cents_max is\n  'One-off setup fee, upper bound. Null where the fee is a single figure or not charged.';\n\nalter table public.subscription_plans\n  add constraint subscription_plans_price_range_ordered\n    check (\n      price_cents_monthly_max is null\n      or price_cents_monthly is null\n      or price_cents_monthly_max >= price_cents_monthly\n    ),\n  add constraint subscription_plans_fee_range_ordered\n    check (\n      implementation_fee_cents_max is null\n      or implementation_fee_cents_min is null\n      or implementation_fee_cents_max >= implementation_fee_cents_min\n    ),\n  add constraint subscription_plans_fee_not_negative\n    check (\n      (implementation_fee_cents_min is null or implementation_fee_cents_min >= 0)\n      and (implementation_fee_cents_max is null or implementation_fee_cents_max >= 0)\n    );\n\n-- ── the prices ───────────────────────────────────────────────────────────\n--\n-- Annual is eleven months for twelve, which is the discount migration 16 set\n-- and this keeps. Enterprise has no annual price because it has no published\n-- monthly one either.\n\nupdate public.subscription_plans set\n  price_cents_monthly          = 149900,\n  price_cents_annual           = 1648900,\n  implementation_fee_cents_min = 250000,\n  implementation_fee_cents_max = 750000,\n  updated_at                   = now()\nwhere plan = 'starter';\n\nupdate public.subscription_plans set\n  price_cents_monthly          = 499900,\n  price_cents_annual           = 5498900,\n  implementation_fee_cents_min = 750000,\n  implementation_fee_cents_max = 2000000,\n  updated_at                   = now()\nwhere plan = 'growth';\n\nupdate public.subscription_plans set\n  price_cents_monthly          = 1299900,\n  price_cents_annual           = 14298900,\n  implementation_fee_cents_min = 2000000,\n  implementation_fee_cents_max = 5000000,\n  updated_at                   = now()\nwhere plan = 'professional';\n\nupdate public.subscription_plans set\n  price_cents_monthly          = 2500000,\n  price_cents_monthly_max      = 7500000,\n  price_cents_annual           = null,\n  implementation_fee_cents_min = 5000000,\n  implementation_fee_cents_max = 25000000,\n  updated_at                   = now()\nwhere plan = 'enterprise';\n\n-- ── the eight new entitlements ───────────────────────────────────────────\n--\n-- Sort orders continue from 21, so the billing page lists them after the\n-- existing catalogue rather than interleaved with it.\n\ninsert into public.entitlements (key, category, name, description, kind, sort_order) values\n  ('digital_twin',          'Intelligence', 'Digital Twin',              'A working model of the business, run against scenarios.',      'feature', 22),\n  ('microsoft_365',         'Connectors',   'Microsoft 365',             'Outlook, Teams, SharePoint, OneDrive and Excel.',              'feature', 23),\n  ('google_workspace',      'Connectors',   'Google Workspace',          'Gmail, Drive, Sheets and Calendar.',                           'feature', 24),\n  ('power_bi',              'Connectors',   'Power BI',                  'Reports, dashboards and datasets read into Amryn.',            'feature', 25),\n  ('enterprise_connectors', 'Connectors',   'Enterprise systems',        'SAP, Dynamics 365 and Salesforce.',                            'feature', 26),\n  ('custom_connectors',     'Connectors',   'Connectors built for you',  'A system of yours that nobody else connects.',                 'feature', 27),\n  ('workflows',             'Operations',   'Workflows',                 'Actions that run when the numbers say they should.',           'feature', 28),\n  ('ai_agents',             'Intelligence', 'AI agents',                 'Agents that carry out analysis without being asked each time.', 'feature', 29)\non conflict (key) do nothing;\n\n-- ── who gets what ────────────────────────────────────────────────────────\n--\n-- The shape of the ladder: Starter is the business itself; Growth adds the\n-- systems a growing company runs on; Professional adds the Microsoft and\n-- analytics estate that a multi-branch operation lives in; Enterprise adds\n-- the systems that require a procurement process to connect to.\n\ninsert into public.plan_entitlements (plan, entitlement_key, included, limit_value) values\n  -- Digital Twin: the product's centre, included everywhere.\n  ('starter',      'digital_twin',          true,  null),\n  ('growth',       'digital_twin',          true,  null),\n  ('professional', 'digital_twin',          true,  null),\n  ('enterprise',   'digital_twin',          true,  null),\n\n  ('starter',      'microsoft_365',         false, null),\n  ('growth',       'microsoft_365',         false, null),\n  ('professional', 'microsoft_365',         true,  null),\n  ('enterprise',   'microsoft_365',         true,  null),\n\n  ('starter',      'google_workspace',      false, null),\n  ('growth',       'google_workspace',      false, null),\n  ('professional', 'google_workspace',      true,  null),\n  ('enterprise',   'google_workspace',      true,  null),\n\n  ('starter',      'power_bi',              false, null),\n  ('growth',       'power_bi',              false, null),\n  ('professional', 'power_bi',              true,  null),\n  ('enterprise',   'power_bi',              true,  null),\n\n  ('starter',      'enterprise_connectors', false, null),\n  ('growth',       'enterprise_connectors', false, null),\n  ('professional', 'enterprise_connectors', false, null),\n  ('enterprise',   'enterprise_connectors', true,  null),\n\n  ('starter',      'custom_connectors',     false, null),\n  ('growth',       'custom_connectors',     false, null),\n  ('professional', 'custom_connectors',     false, null),\n  ('enterprise',   'custom_connectors',     true,  null),\n\n  ('starter',      'workflows',             false, null),\n  ('growth',       'workflows',             false, null),\n  ('professional', 'workflows',             true,  null),\n  ('enterprise',   'workflows',             true,  null),\n\n  ('starter',      'ai_agents',             false, null),\n  ('growth',       'ai_agents',             false, null),\n  ('professional', 'ai_agents',             true,  null),\n  ('enterprise',   'ai_agents',             true,  null)\non conflict (plan, entitlement_key) do nothing;\n\n-- ── the connection ceilings ──────────────────────────────────────────────\n--\n-- 2 / 8 / 20 / unlimited, against a brief asking for 1–2, 5–8, 10–20+ and\n-- per contract. Starter and Growth already sat at the top of their band and\n-- are unchanged; Professional becomes a number.\n\nupdate public.plan_entitlements\n   set limit_value = 20\n where entitlement_key = 'data_sources'\n   and plan = 'professional';\n\n-- subscription_plans carries its own denormalised copy, used when a\n-- subscription row is created. Left in step with the entitlement matrix,\n-- because two numbers that mean the same thing must not be allowed to drift.\nupdate public.subscription_plans\n   set data_source_limit = 20,\n       updated_at        = now()\n where plan = 'professional';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260910180000_37_documents.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260910180000_37_documents.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 37. Files a customer gives Amryn\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Until now the only file the platform would take was a stocktake, and only as\n-- a CSV. Everything else a business actually holds — the supplier contract, the\n-- bank statement, the lease, the insurance schedule, the month-end pack a\n-- bookkeeper emails as a PDF — had nowhere to go.\n--\n-- ── the distinction this table is built around ───────────────────────────\n--\n-- Amryn can do exactly two things with a file, and conflating them would be\n-- the beginning of a much worse product:\n--\n--   read it   A spreadsheet. Its columns and rows are legible, so what is in\n--             them can become stock lines, records, figures — things the Twin\n--             may reason from.\n--\n--   keep it   Everything else. It is stored, listed, and handed back when\n--             asked for. Nobody has read it. No score moves because of it.\n--\n-- `handling` records which, per file, and it is not decoration: it is what\n-- stops a page saying \"12 documents analysed\" over a folder of PDFs nothing\n-- opened. The rule against the model filling a numeric gap from memory is the\n-- same rule — a business that believed Amryn had read its contracts would be\n-- relying on an analysis that never happened.\n--\n-- ── where the bytes are ──────────────────────────────────────────────────\n--\n-- In Supabase Storage, not in this table. A bytea column would put a customer's\n-- files into every backup dump, every restore-check, and the replication\n-- stream, and would make the row-count arithmetic in backup.mjs meaningless.\n-- The row here is the record; `storage_path` is the pointer.\n--\n-- ── purely additive ──────────────────────────────────────────────────────\n--\n-- One table, one bucket, four policies, one trigger. No column is dropped, no\n-- row updated, nothing existing altered — so this applies to a live database\n-- without the backup gate, which is the shape every migration here is meant\n-- to have.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ncreate table public.data_documents (\n  id               uuid primary key default gen_random_uuid(),\n  organisation_id  uuid not null references public.organisations (id) on delete cascade,\n\n  filename         text not null check (length(filename) between 1 and 300),\n  content_type     text not null default '',\n  byte_size        bigint not null check (byte_size >= 0),\n\n  -- 'table' or 'document'. Constrained rather than free text, because the\n  -- interface makes a promise about what happened to the file based on it.\n  handling         text not null check (handling in ('table', 'document')),\n\n  -- '<organisation_id>/<document id>'. The customer's own file name is *not*\n  -- in the path: it would have to be sanitised, sanitising is where path\n  -- traversal bugs live, and the name is already in the column above.\n  storage_path     text not null unique,\n\n  -- sha256 of the contents. Two uploads of the same file are a common accident\n  -- and this is how a page can say so.\n  checksum         text not null default '',\n\n  -- What reading it found, where it was readable. Empty for a document.\n  sheet_names      text[] not null default '{}',\n  columns_found    text[] not null default '{}',\n  row_count        integer not null default 0 check (row_count >= 0),\n\n  -- Why it could not be read, where it was a spreadsheet and would not open.\n  -- Kept rather than discarded: \"we tried and here is what went wrong\" is a\n  -- different statement from \"we did not try\", and the list has to show both.\n  read_error       text not null default '',\n\n  note             text not null default '' check (length(note) <= 2000),\n\n  uploaded_by      uuid references auth.users (id) on delete set null,\n  created_at       timestamptz not null default now(),\n  updated_at       timestamptz not null default now(),\n  deleted_at       timestamptz\n);\n\ncomment on table public.data_documents is\n  'A file a customer uploaded. handling says whether Amryn read its rows or is merely holding it.';\n\ncomment on column public.data_documents.handling is\n  'table: rows were read and may be used. document: stored and given back, never interpreted.';\n\ncreate index data_documents_org_idx\n  on public.data_documents (organisation_id, created_at desc);\n\n-- Migration 22's rule: every foreign key gets an index, so a cascade delete\n-- does not sequentially scan.\ncreate index data_documents_uploaded_by_idx on public.data_documents (uploaded_by);\n\n-- Finding the duplicate somebody just uploaded again.\ncreate index data_documents_checksum_idx\n  on public.data_documents (organisation_id, checksum)\n  where checksum <> '';\n\ncreate trigger data_documents_touch\n  before update on public.data_documents\n  for each row execute function amryn.touch_updated_at();\n\n-- ── who may read and write them ───────────────────────────────────────────\n\nalter table public.data_documents enable row level security;\nalter table public.data_documents force row level security;\n\ncreate policy data_documents_read on public.data_documents\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'view_data_sources'));\n\ncreate policy data_documents_write on public.data_documents\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'import_data'))\n  with check (amryn.has_permission(organisation_id, 'import_data'));\n\n-- ── the lapsed-subscription guard ─────────────────────────────────────────\n--\n-- Attached by hand, as migration 18 explains: migration 16 attached these by\n-- iterating the catalogue as it stood then, and a table added afterwards\n-- carries none. Test 19 asserts the whole list, so a new table is a failing\n-- test until somebody decides in writing which side of the line it is on.\n--\n-- Guarded. An organisation whose subscription has lapsed keeps every file it\n-- has already given us — those are its records and withholding them would be\n-- leverage, not enforcement — and cannot add more.\ncreate trigger zz_subscription_data_documents\n  before insert or update or delete on public.data_documents\n  for each row execute function amryn.refuse_lapsed_write();\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- The bucket, and who may reach into it\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Private. A public bucket serves any object to anyone holding its URL, and\n-- these are one company's contracts and bank statements.\n--\n-- Access is by signed URL, minted per request by a server that has already\n-- established which organisation the caller belongs to. The policies below are\n-- the second lock: if a bug ever hands a customer a client that queries\n-- storage directly, the database still refuses the other tenants' rows.\n\ninsert into storage.buckets (id, name, public)\nvalues ('documents', 'documents', false)\non conflict (id) do nothing;\n\n/*\n * The organisation that owns an object, from its path.\n *\n * Objects are named '<organisation_id>/<document id>', so the first segment is\n * the tenant. The regexp guard is not defensive padding: an object whose first\n * segment is not a UUID would raise on the cast, and a policy that raises is a\n * policy that fails a query rather than denying a row — which reads as an\n * outage instead of a refusal. Null means \"no organisation\", and\n * has_permission(null, …) is false.\n */\ncreate or replace function amryn.storage_org(p_name text)\nreturns uuid\nlanguage sql\nimmutable\nset search_path = public, pg_temp\nas $$\n  select case\n    when split_part(p_name, '/', 1)\n         ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'\n      then split_part(p_name, '/', 1)::uuid\n    else null\n  end;\n$$;\n\ncomment on function amryn.storage_org(text) is\n  'The tenant that owns a storage object, read from the first segment of its path. Null if the path is not tenant-shaped.';\n\ncreate policy documents_read on storage.objects\n  for select to authenticated\n  using (\n    bucket_id = 'documents'\n    and amryn.has_permission(amryn.storage_org(name), 'view_data_sources')\n  );\n\ncreate policy documents_insert on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'documents'\n    and amryn.has_permission(amryn.storage_org(name), 'import_data')\n  );\n\ncreate policy documents_update on storage.objects\n  for update to authenticated\n  using (\n    bucket_id = 'documents'\n    and amryn.has_permission(amryn.storage_org(name), 'import_data')\n  )\n  with check (\n    bucket_id = 'documents'\n    and amryn.has_permission(amryn.storage_org(name), 'import_data')\n  );\n\ncreate policy documents_delete on storage.objects\n  for delete to authenticated\n  using (\n    bucket_id = 'documents'\n    and amryn.has_permission(amryn.storage_org(name), 'import_data')\n  );\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260910200000_38_document_text.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260910200000_38_document_text.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 38. The words inside a document\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Migration 37 could keep a PDF and could not read one. This adds the reading:\n-- text pulled out of PDFs, Word documents, presentations and plain text on\n-- upload, stored beside the file so it can be searched and quoted.\n--\n-- ── why the text is in its own table ─────────────────────────────────────\n--\n-- A three-hundred-page contract yields something close to a megabyte of text.\n-- Put that column on data_documents and every `select *` behind the file list\n-- drags the whole corpus across the wire to render a list of names — a page\n-- that gets slower with every upload, for no reason a reader could guess.\n--\n-- One row per document, cascading with it, fetched only when somebody opens\n-- the document itself. The counts that the list *does* show — pages, how many\n-- characters — stay on the parent row where they are cheap.\n--\n-- ── the third value of `handling`, and the line it must not cross ────────\n--\n--   table     rows read\n--   text      words extracted and stored\n--   document  kept, not read\n--\n-- 'text' means the words are available. It does not mean anything has been\n-- understood: no term noted, no risk assessed, no figure taken. That\n-- distinction is one careless sentence from collapsing — \"we have the words\"\n-- and \"we know what it says\" look alike in a hurry — and the whole reason it\n-- is a constrained column rather than a convention is so a page cannot claim\n-- the second by accident. Test 36 already refuses 'analysed'.\n--\n-- ── the case that must not read as an empty file ─────────────────────────\n--\n-- A scanned invoice is a photograph of paper. It has pages and no text layer,\n-- so extraction returns nothing — indistinguishable from a blank document\n-- unless the row says which it was. `read_error` carries that sentence, and\n-- most of what a small business actually holds arrives this way.\n--\n-- Purely additive: three columns, one table, one constraint widened. Nothing\n-- dropped, no row rewritten.\n-- ═══════════════════════════════════════════════════════════════════════════\n\nalter table public.data_documents\n  add column page_count integer not null default 0 check (page_count >= 0),\n  add column text_chars integer not null default 0 check (text_chars >= 0),\n  add column text_truncated boolean not null default false;\n\ncomment on column public.data_documents.page_count is\n  'Pages in a PDF, slides in a presentation. Zero where the format has no such unit.';\n\ncomment on column public.data_documents.text_chars is\n  'How much text was extracted. Zero with handling=document and a read_error set means we tried and could not.';\n\n-- The constraint is widened rather than replaced in spirit: every value that\n-- was legal before is legal now. Dropping and recreating is the only way\n-- PostgreSQL offers to widen a check, and it rewrites no rows.\nalter table public.data_documents\n  drop constraint data_documents_handling_check;\n\nalter table public.data_documents\n  add constraint data_documents_handling_check\n  check (handling in ('table', 'text', 'document'));\n\ncreate table public.data_document_text (\n  document_id     uuid primary key references public.data_documents (id) on delete cascade,\n  organisation_id uuid not null references public.organisations (id) on delete cascade,\n  content         text not null,\n  created_at      timestamptz not null default now()\n);\n\ncomment on table public.data_document_text is\n  'The words extracted from one document. Separate from data_documents so listing files does not read the corpus.';\n\n-- organisation_id is repeated here rather than reached through the join.\n-- A row level security policy that had to join to its parent to know which\n-- tenant it belongs to is a policy that runs a subquery per row, and one whose\n-- correctness depends on the join staying right.\ncreate index data_document_text_org_idx on public.data_document_text (organisation_id);\n\nalter table public.data_document_text enable row level security;\nalter table public.data_document_text force row level security;\n\ncreate policy data_document_text_read on public.data_document_text\n  for select to authenticated\n  using (amryn.has_permission(organisation_id, 'view_data_sources'));\n\ncreate policy data_document_text_write on public.data_document_text\n  for all to authenticated\n  using (amryn.has_permission(organisation_id, 'import_data'))\n  with check (amryn.has_permission(organisation_id, 'import_data'));\n\n-- Guarded, like its parent: an organisation whose subscription has lapsed\n-- keeps everything already extracted and adds nothing new.\ncreate trigger zz_subscription_data_document_text\n  before insert or update or delete on public.data_document_text\n  for each row execute function amryn.refuse_lapsed_write();\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260910220000_39_document_ocr.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260910220000_39_document_ocr.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 39. Reading a scan\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Migration 38 could pull the words out of a PDF that had words in it, and\n-- said so honestly when one did not: a photographed invoice is a picture of a\n-- page, and there is nothing to extract. That is a large share of what a small\n-- business actually holds.\n--\n-- Character recognition closes it, and it runs on our own worker rather than\n-- through a paid service. That decision is worth recording with its numbers,\n-- because the alternative looked cheap too:\n--\n--   Tesseract on the worker    R0 per page. Measured at ~275 ms for an A4\n--                              invoice. The file never leaves our own\n--                              infrastructure, so the processor register in\n--                              the privacy notice does not change.\n--\n--   A cloud OCR service        Around $1.50 per thousand pages at Google,\n--                              Azure and AWS alike. Cheap, and it means every\n--                              customer's invoices and bank statements go to\n--                              a third party — a new processor to declare and\n--                              a new jurisdiction to name.\n--\n--   A vision model             Ruled out, and not on price. A generative model\n--                              asked to transcribe an invoice can produce a\n--                              figure that is plausible and absent from the\n--                              page. Tesseract's failures look like failures.\n--                              For a product whose claim is that its numbers\n--                              are traceable, that difference decides it.\n--\n-- ── why the source of the text is now a column ───────────────────────────\n--\n-- Text lifted from a PDF's own text layer is what the document says. Text from\n-- character recognition is a *reading* of what the document says, and it is\n-- wrong often enough to matter — measurably so. Running Tesseract over an\n-- invoice rendered two ways produced two different sets of errors: one run\n-- dropped a quantity of 140 entirely, the other turned R42.50 into \"RA250\".\n-- Both runs looked equally confident.\n--\n-- So the two are not interchangeable and the interface must not present them\n-- as one. `text_source` is what lets a page say \"read by character\n-- recognition — check the figures against the image\", and it is the same\n-- discipline as the provenance column on a metric: where a number came from\n-- travels with the number.\n--\n-- Purely additive: two columns with defaults, one index. No row is rewritten.\n-- ═══════════════════════════════════════════════════════════════════════════\n\nalter table public.data_documents\n  add column text_source text not null default 'none'\n    check (text_source in ('none', 'embedded', 'ocr')),\n  add column ocr_state text not null default 'not_needed'\n    check (ocr_state in ('not_needed', 'queued', 'running', 'done', 'failed'));\n\ncomment on column public.data_documents.text_source is\n  'none: no text. embedded: lifted from the file''s own text layer, and is what the document says. ocr: read off an image by character recognition, and is a reading of what the document says — presented with that caveat, never as equivalent.';\n\ncomment on column public.data_documents.ocr_state is\n  'Where the recognition job is. queued and running are what the file list shows while the worker has it.';\n\n-- Finding the work. Partial, because all but a handful of rows are\n-- 'not_needed' and an index over those would be a copy of the table.\ncreate index data_documents_ocr_pending_idx\n  on public.data_documents (organisation_id, created_at)\n  where ocr_state in ('queued', 'running');\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- Asking for a scan to be read\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- A function rather than an insert. job_runs is not writable from a session —\n-- deliberately, since migration 23 — and the two existing ways in are both\n-- functions that check a permission first and can queue exactly one kind of\n-- job each. This is the third, on the same terms.\n--\n-- It exists at all because the alternative was the upload action inserting a\n-- job row itself, which would mean granting a browser session the ability to\n-- write to the queue. A queue anybody can put anything into is not a queue.\ncreate or replace function public.request_document_ocr(p_document uuid)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, pg_temp\nas $$\ndeclare\n  v_org      uuid;\n  v_state    text;\n  v_job      uuid;\nbegin\n  -- The document decides the organisation, not the caller. Taking the\n  -- organisation as a parameter would let a well-formed call name one it does\n  -- not belong to and have the permission check pass against it.\n  select organisation_id, ocr_state\n    into v_org, v_state\n    from public.data_documents\n   where id = p_document and deleted_at is null;\n\n  if v_org is null then\n    raise exception 'that document does not exist' using errcode = 'P0002';\n  end if;\n\n  -- The same permission that allows the upload. Reading a file needs only\n  -- view_data_sources; spending a worker's time on it needs more.\n  if not amryn.has_permission(v_org, 'import_data') then\n    raise exception 'you do not have permission to read that document'\n      using errcode = '42501';\n  end if;\n\n  -- Already queued or running. Returning quietly rather than raising: a person\n  -- who presses the button twice has not made a mistake worth an error.\n  if v_state in ('queued', 'running') then\n    return null;\n  end if;\n\n  insert into public.job_runs\n    (organisation_id, kind, payload, singleton_key, max_attempts, requested_by)\n  values\n    (v_org, 'document.ocr',\n     jsonb_build_object('documentId', p_document::text),\n     -- One reading of one document at a time. Keyed on the document rather\n     -- than the organisation: two people uploading two scans at once are not\n     -- competing for anything.\n     'ocr:' || p_document::text,\n     2,\n     auth.uid())\n  returning id into v_job;\n\n  update public.data_documents\n     set ocr_state = 'queued', read_error = ''\n   where id = p_document;\n\n  return v_job;\nend $$;\n\ncomment on function public.request_document_ocr is\n  'Queues one scanned document to be read by the worker. The third and last thing that may write to job_runs from a session, and it can queue exactly one kind of job.';\n\nrevoke all on function public.request_document_ocr(uuid) from public, anon;\ngrant execute on function public.request_document_ocr(uuid) to authenticated;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260911070000_40_volume_headroom.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260911070000_40_volume_headroom.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 40. How much room is left where the backups go\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- Migration 35 made the *age* of the last backup visible, which turned \"we\n-- have backups\" from an assumption into a statement. This is the other half of\n-- the same question, and it has the same failure mode: a nightly dump that\n-- silently stops because the volume filled looks exactly like one that is\n-- still running, right up until somebody needs it.\n--\n-- ── why this is on the heartbeat rather than on the backup row ───────────\n--\n-- A backup row is written once a night. A volume can fill at ten in the\n-- morning, and learning about it fifteen hours later is learning about it\n-- after the dump that would have told you has already failed.\n--\n-- The heartbeat beats every five seconds and already carries the operational\n-- facts about the worker that nothing else can see — its handler list, its\n-- revision, whether it is ahead of the schema. Free space belongs with those:\n-- the volume is mounted on the worker, and the diagnostics page is rendered by\n-- the web service, which cannot see that filesystem at all.\n--\n-- ── why not the host's own monitor ──────────────────────────────────────\n--\n-- Railway has disk-usage monitors and they are gated behind a plan this\n-- deployment is not on. A check that exists only for customers who pay more is\n-- not a check this platform has. Measuring it here costs one syscall per beat\n-- and works on every plan, including none.\n--\n-- Additive: three columns with defaults. No row is rewritten — zero is the\n-- default and reads as \"never reported\", which is what a worker on an older\n-- build honestly is.\n-- ═══════════════════════════════════════════════════════════════════════════\n\nalter table public.worker_heartbeats\n  add column volume_path        text   not null default '',\n  add column volume_total_bytes bigint not null default 0 check (volume_total_bytes >= 0),\n  add column volume_free_bytes  bigint not null default 0 check (volume_free_bytes  >= 0);\n\ncomment on column public.worker_heartbeats.volume_path is\n  'Where the worker writes backups. Empty when it has no volume mounted, or is running a build from before this column existed.';\n\ncomment on column public.worker_heartbeats.volume_total_bytes is\n  'Size of that volume as the worker measured it. Zero means it did not report, which is not the same as full — /diagnostics reads it as unknown.';\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- 20260911090000_41_backup_storage.sql\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$ begin raise notice 'applying 20260911090000_41_backup_storage.sql'; end $setup$;\n\n-- ═══════════════════════════════════════════════════════════════════════════\n-- 41. Somewhere a deploy can put a backup\n-- ═══════════════════════════════════════════════════════════════════════════\n--\n-- The backup rule has been enforced since migration 25: scripts/migrate.mjs\n-- refuses a migration that rewrites rows unless a recent, verified dump is to\n-- hand. That rule is right and it has one consequence nobody designed for —\n-- the worker's pre-deploy command cannot satisfy it, so a migration that\n-- updates a single row stops the deploy of both services until a person\n-- applies it by hand. Migration 36 did exactly that.\n--\n-- ── why the deploy could not simply take one ─────────────────────────────\n--\n-- Because it has nowhere to put it. Railway does not mount volumes during the\n-- pre-deploy command — their documentation says so in four places — so a dump\n-- written there lands on a filesystem that is discarded minutes later. That is\n-- not a backup; it is a green check over nothing, which is worse than the\n-- refusal it would replace.\n--\n-- ── and why not just let the deploy through ──────────────────────────────\n--\n-- Letting migrate.mjs give up quietly looked attractive until the consequence\n-- was followed through. A worker whose database is behind claims nothing —\n-- migration 34, deliberately — and enqueues nothing either, so the nightly\n-- backup stops with everything else. The one thing needed to unblock the\n-- migration is the one thing that has stopped running. A deadlock, reached by\n-- being careful.\n--\n-- So: a private bucket the deploy can write to. The dump goes here, the\n-- migration proceeds, and no human is in the path.\n--\n-- ── what this is honestly worth ──────────────────────────────────────────\n--\n-- A dump stored in the same project it was taken from does not survive losing\n-- that project, and nothing here pretends otherwise. It is complete protection\n-- against the thing the gate exists for — an update or a delete that turns out\n-- to be wrong — and no protection at all against the account going away. The\n-- nightly dump onto the worker's own volume, and whatever an operator copies\n-- off it, remain the answer to the second question.\n--\n-- ── who may read it ──────────────────────────────────────────────────────\n--\n-- Nobody through a session. No policy is written for this bucket at all, which\n-- given storage's row level security means every signed-in caller is refused —\n-- the same treatment public.backups gets, and for a stronger reason: these\n-- objects are the whole database, every tenant at once, in one file.\n--\n-- Only the service role reaches it, which bypasses policies by design and is\n-- held by the deploy and the worker.\n--\n-- Additive: one bucket row.\n-- ═══════════════════════════════════════════════════════════════════════════\n\ninsert into storage.buckets (id, name, public)\nvalues ('backups', 'backups', false)\non conflict (id) do nothing;\n\nnotify pgrst, 'reload schema';\n\n-- ══════════════════════════════════════════════════════════════════════\n-- Did it work?\n-- ══════════════════════════════════════════════════════════════════════\ndo $setup$\ndeclare\n  tables_found bigint;\n  perms_found  bigint;\n  grants_found bigint;\nbegin\n  select count(*) into tables_found from pg_tables where schemaname = 'public';\n  select count(*) into perms_found  from public.permissions;\n  select count(*) into grants_found from public.role_permissions;\n\n  if tables_found <> 72 then\n    raise exception 'expected 72 tables, found %', tables_found;\n  end if;\n  if perms_found <> 31 then\n    raise exception 'expected 31 permissions, found %', perms_found;\n  end if;\n  if grants_found < 100 then\n    raise exception 'expected the role matrix to be seeded, found % grants', grants_found;\n  end if;\n\n  raise notice 'setup complete: % tables, % permissions, % role grants',\n    tables_found, perms_found, grants_found;\nend $setup$;\n\ncommit;\n\n-- Outside the transaction: PostgREST answers from a cached copy of the\n-- schema, and nothing above is visible to the application until it is told.\nnotify pgrst, 'reload schema';\n";

